impl StratumPoolLedgerState {
    fn new(
        network_id: String,
        start_height: u64,
        start_tip_hash: Hash256,
        now_unix_sec: u64,
        max_share_records: usize,
        max_round_records: usize,
    ) -> Self {
        let mut rounds = VecDeque::<PoolRoundRecord>::new();
        rounds.push_back(PoolRoundRecord {
            round_id: 1,
            start_height,
            start_tip_hash,
            start_unix_sec: now_unix_sec,
            end_height: None,
            end_tip_hash: None,
            end_unix_sec: None,
            closed_by_worker: None,
            found_block_hash: None,
            found_block_reward_atomic: 0,
            orphaned: false,
        });
        Self {
            network_id,
            current_round_id: 1,
            current_round_start_height: start_height,
            current_round_start_tip_hash: start_tip_hash,
            current_round_start_unix_sec: now_unix_sec,
            shares: VecDeque::new(),
            share_index: HashSet::new(),
            rounds,
            workers: HashMap::new(),
            pending_payouts: VecDeque::new(),
            completed_payouts: VecDeque::new(),
            max_share_records: max_share_records.max(1),
            max_round_records: max_round_records.max(1),
            payout_cfg: PoolPayoutConfig::default(),
            last_payout_run_unix_sec: 0,
            pps_guardrail_alerts_total: 0,
        }
    }

    fn from_snapshot(
        snapshot: PoolLedgerSnapshot,
        fallback_start_height: u64,
        fallback_start_tip_hash: Hash256,
        now_unix_sec: u64,
        max_share_records: usize,
        max_round_records: usize,
    ) -> Self {
        let mut shares = snapshot.shares.into_iter().collect::<VecDeque<_>>();
        let shares_overflow = shares.len().saturating_sub(max_share_records.max(1));
        for _ in 0..shares_overflow {
            let _ = shares.pop_front();
        }
        let share_index = shares
            .iter()
            .map(|share| share.share_key.clone())
            .collect::<HashSet<_>>();
        let mut rounds = snapshot.rounds.into_iter().collect::<VecDeque<_>>();
        let rounds_overflow = rounds.len().saturating_sub(max_round_records.max(1));
        for _ in 0..rounds_overflow {
            let _ = rounds.pop_front();
        }
        let workers = snapshot
            .workers
            .into_iter()
            .map(|record| (record.worker.clone(), record))
            .collect::<HashMap<_, _>>();
        let pending_payouts = snapshot
            .pending_payouts
            .into_iter()
            .collect::<VecDeque<_>>();
        let completed_payouts = snapshot
            .completed_payouts
            .into_iter()
            .collect::<VecDeque<_>>();

        let mut state = Self {
            network_id: snapshot.network_id,
            current_round_id: snapshot.current_round_id.max(1),
            current_round_start_height: fallback_start_height,
            current_round_start_tip_hash: fallback_start_tip_hash,
            current_round_start_unix_sec: now_unix_sec,
            shares,
            share_index,
            rounds,
            workers,
            pending_payouts,
            completed_payouts,
            max_share_records: max_share_records.max(1),
            max_round_records: max_round_records.max(1),
            payout_cfg: PoolPayoutConfig::default(),
            last_payout_run_unix_sec: 0,
            pps_guardrail_alerts_total: 0,
        };
        if let Some(open) = state.rounds.back()
            && open.end_height.is_none()
            && open.end_tip_hash.is_none()
        {
            state.current_round_id = open.round_id;
            state.current_round_start_height = open.start_height;
            state.current_round_start_tip_hash = open.start_tip_hash;
            state.current_round_start_unix_sec = open.start_unix_sec;
            return state;
        }
        state.open_next_round(fallback_start_height, fallback_start_tip_hash, now_unix_sec);
        state
    }

    fn set_payout_config(&mut self, payout_cfg: PoolPayoutConfig) {
        self.payout_cfg = payout_cfg;
        if matches!(
            self.payout_cfg.mode,
            PoolPayoutModeArg::Pplns | PoolPayoutModeArg::Hybrid
        ) {
            self.recompute_pplns_accruals();
        } else {
            for worker in self.workers.values_mut() {
                worker.pplns_accrual_atomic = 0;
            }
        }
    }

    fn reward_after_pool_fee(&self, gross_reward_atomic: u128) -> u128 {
        let fee_bps = self.payout_cfg.pool_fee_bps.min(10_000) as u128;
        gross_reward_atomic.saturating_mul(10_000u128.saturating_sub(fee_bps)) / 10_000u128
    }

    fn total_outstanding_atomic(&self) -> u128 {
        self.workers
            .values()
            .map(|worker| {
                worker
                    .pplns_accrual_atomic
                    .saturating_add(worker.pps_accrual_atomic)
                    .saturating_sub(worker.paid_total_atomic)
            })
            .fold(0u128, |acc, value| acc.saturating_add(value))
    }

    fn pps_liability_exceeds_cap(&self, next_credit: u128) -> bool {
        if self.payout_cfg.pps_max_liability_atomic == 0 {
            return false;
        }
        self.total_outstanding_atomic().saturating_add(next_credit)
            > self.payout_cfg.pps_max_liability_atomic
    }

    fn apply_pps_share_credit(&mut self, worker: &str, reserve_spendable_atomic: Option<u128>) {
        if !matches!(
            self.payout_cfg.mode,
            PoolPayoutModeArg::Pps | PoolPayoutModeArg::Hybrid
        ) {
            return;
        }
        let credit = self.payout_cfg.pps_share_atomic as u128;
        if credit == 0 {
            return;
        }
        if self.payout_cfg.pps_reserve_floor_atomic > 0 {
            match reserve_spendable_atomic {
                Some(reserve) if reserve >= self.payout_cfg.pps_reserve_floor_atomic => {}
                _ => {
                    self.pps_guardrail_alerts_total =
                        self.pps_guardrail_alerts_total.saturating_add(1);
                    return;
                }
            }
        }
        if self.pps_liability_exceeds_cap(credit) {
            self.pps_guardrail_alerts_total = self.pps_guardrail_alerts_total.saturating_add(1);
            return;
        }
        if let Some(entry) = self.workers.get_mut(worker) {
            entry.pps_accrual_atomic = entry.pps_accrual_atomic.saturating_add(credit);
        }
    }

    fn recompute_pplns_accruals(&mut self) {
        for worker in self.workers.values_mut() {
            worker.pplns_accrual_atomic = 0;
        }
        if !matches!(
            self.payout_cfg.mode,
            PoolPayoutModeArg::Pplns | PoolPayoutModeArg::Hybrid
        ) {
            return;
        }
        let mut accepted = self
            .shares
            .iter()
            .filter(|share| share.accepted)
            .cloned()
            .collect::<Vec<_>>();
        accepted.sort_by(|a, b| {
            a.timestamp_unix_sec
                .cmp(&b.timestamp_unix_sec)
                .then(a.share_key.cmp(&b.share_key))
        });

        for round in &self.rounds {
            if round.orphaned {
                continue;
            }
            let Some(end_unix_sec) = round.end_unix_sec else {
                continue;
            };
            let gross = round.found_block_reward_atomic;
            if gross == 0 {
                continue;
            }
            let reward = self.reward_after_pool_fee(gross);
            if reward == 0 {
                continue;
            }
            let mut window = accepted
                .iter()
                .filter(|share| share.timestamp_unix_sec <= end_unix_sec)
                .collect::<Vec<_>>();
            if window.is_empty() {
                continue;
            }
            let window_limit = self.payout_cfg.pplns_window_shares.max(1);
            let start = window.len().saturating_sub(window_limit);
            if start != 0 {
                window = window[start..].to_vec();
            }
            let mut worker_weights = HashMap::<String, f64>::new();
            let mut total_weight = 0.0f64;
            for share in window {
                let weight = share.expected_hashes.max(0.0);
                if weight <= 0.0 {
                    continue;
                }
                total_weight += weight;
                *worker_weights.entry(share.worker.clone()).or_insert(0.0) += weight;
            }
            if total_weight <= 0.0 {
                continue;
            }
            for (worker, weight) in worker_weights {
                let payout = ((reward as f64) * (weight / total_weight)).floor() as u128;
                if payout == 0 {
                    continue;
                }
                if let Some(entry) = self.workers.get_mut(&worker) {
                    entry.pplns_accrual_atomic = entry.pplns_accrual_atomic.saturating_add(payout);
                }
            }
        }
    }

    fn queue_due_payouts(&mut self, now_unix_sec: u64) -> Vec<PoolPayoutRecord> {
        if self.payout_cfg.mode == PoolPayoutModeArg::Solo {
            return Vec::new();
        }
        if now_unix_sec.saturating_sub(self.last_payout_run_unix_sec)
            < self.payout_cfg.payout_interval_sec.max(1)
        {
            return Vec::new();
        }
        self.last_payout_run_unix_sec = now_unix_sec;

        let threshold = self.payout_cfg.payout_threshold_atomic.max(1);
        let mut created = Vec::<PoolPayoutRecord>::new();
        let pending_workers = self
            .pending_payouts
            .iter()
            .map(|p| p.worker.clone())
            .collect::<HashSet<_>>();
        let mut workers = self.workers.keys().cloned().collect::<Vec<_>>();
        workers.sort();
        for worker in workers {
            if pending_workers.contains(&worker) {
                continue;
            }
            let Some(entry) = self.workers.get(&worker) else {
                continue;
            };
            let outstanding = entry
                .pplns_accrual_atomic
                .saturating_add(entry.pps_accrual_atomic)
                .saturating_sub(entry.paid_total_atomic);
            if outstanding < threshold {
                continue;
            }
            if parse_address(&worker).is_err() {
                self.pps_guardrail_alerts_total = self.pps_guardrail_alerts_total.saturating_add(1);
                continue;
            }
            let payout = PoolPayoutRecord {
                payout_id: format!(
                    "payout-{}-{}-{}",
                    now_unix_sec,
                    worker,
                    self.pending_payouts
                        .len()
                        .saturating_add(created.len())
                        .saturating_add(1)
                ),
                worker: worker.clone(),
                amount_atomic: outstanding,
                created_unix_sec: now_unix_sec,
                submitted_txid_hex: None,
                confirmed: false,
            };
            self.pending_payouts.push_back(payout.clone());
            created.push(payout);
        }
        created
    }

    fn mark_pending_payout_submitted(&mut self, payout_id: &str, txid_hex: &str) -> bool {
        for payout in &mut self.pending_payouts {
            if payout.payout_id == payout_id {
                payout.submitted_txid_hex = Some(txid_hex.to_owned());
                return true;
            }
        }
        false
    }

    fn settle_confirmed_payouts(&mut self, runtime: &ChainRuntime) -> usize {
        let mut moved = 0usize;
        let mut keep = VecDeque::<PoolPayoutRecord>::new();
        while let Some(mut payout) = self.pending_payouts.pop_front() {
            let confirmed = payout
                .submitted_txid_hex
                .as_deref()
                .and_then(|hex| Hash256::from_hex(hex).ok())
                .is_some_and(|txid| runtime_contains_txid(runtime, txid));
            if confirmed {
                payout.confirmed = true;
                if let Some(worker) = self.workers.get_mut(&payout.worker) {
                    worker.paid_total_atomic = worker
                        .paid_total_atomic
                        .saturating_add(payout.amount_atomic);
                }
                self.completed_payouts.push_back(payout);
                moved = moved.saturating_add(1);
            } else {
                keep.push_back(payout);
            }
        }
        self.pending_payouts = keep;
        moved
    }

    fn share_key(channel_id: u32, job_id: u32, nonce: u64, ntime: u64) -> String {
        format!("{channel_id}:{job_id}:{nonce}:{ntime}")
    }

    #[allow(clippy::too_many_arguments)]
    fn register_share(
        &mut self,
        worker: &str,
        channel_id: u32,
        job_id: u32,
        nonce: u64,
        ntime: u64,
        expected_hashes: f64,
        accepted: bool,
        is_block: bool,
        now_unix_sec: u64,
        reserve_spendable_atomic: Option<u128>,
    ) -> bool {
        let key = Self::share_key(channel_id, job_id, nonce, ntime);
        if !self.share_index.insert(key.clone()) {
            return false;
        }
        self.shares.push_back(PoolShareRecord {
            share_key: key,
            worker: worker.to_owned(),
            timestamp_unix_sec: now_unix_sec,
            channel_id,
            job_id,
            nonce,
            ntime,
            expected_hashes,
            accepted,
            is_block,
        });
        while self.shares.len() > self.max_share_records {
            let Some(front) = self.shares.pop_front() else {
                break;
            };
            self.share_index.remove(&front.share_key);
        }

        let counters =
            self.workers
                .entry(worker.to_owned())
                .or_insert_with(|| PoolWorkerAccrualRecord {
                    worker: worker.to_owned(),
                    accepted_total: 0,
                    rejected_total: 0,
                    blocks_found_total: 0,
                    expected_hashes_accumulated: 0.0,
                    pplns_accrual_atomic: 0,
                    pps_accrual_atomic: 0,
                    paid_total_atomic: 0,
                    last_share_unix_sec: 0,
                });
        if accepted {
            counters.accepted_total = counters.accepted_total.saturating_add(1);
            counters.expected_hashes_accumulated =
                (counters.expected_hashes_accumulated + expected_hashes.max(0.0)).max(0.0);
        } else {
            counters.rejected_total = counters.rejected_total.saturating_add(1);
        }
        if is_block && accepted {
            counters.blocks_found_total = counters.blocks_found_total.saturating_add(1);
        }
        counters.last_share_unix_sec = now_unix_sec;
        if accepted {
            self.apply_pps_share_credit(worker, reserve_spendable_atomic);
        }
        true
    }

    fn register_rejected_only(&mut self, worker: &str, now_unix_sec: u64) {
        let counters =
            self.workers
                .entry(worker.to_owned())
                .or_insert_with(|| PoolWorkerAccrualRecord {
                    worker: worker.to_owned(),
                    accepted_total: 0,
                    rejected_total: 0,
                    blocks_found_total: 0,
                    expected_hashes_accumulated: 0.0,
                    pplns_accrual_atomic: 0,
                    pps_accrual_atomic: 0,
                    paid_total_atomic: 0,
                    last_share_unix_sec: 0,
                });
        counters.rejected_total = counters.rejected_total.saturating_add(1);
        counters.last_share_unix_sec = now_unix_sec;
    }

    fn close_round_with_block(
        &mut self,
        worker: &str,
        found_block_hash: Hash256,
        found_block_reward_atomic: u128,
        end_height: u64,
        end_tip_hash: Hash256,
        now_unix_sec: u64,
    ) {
        if let Some(current) = self.rounds.back_mut() {
            current.end_height = Some(end_height);
            current.end_tip_hash = Some(end_tip_hash);
            current.end_unix_sec = Some(now_unix_sec);
            current.closed_by_worker = Some(worker.to_owned());
            current.found_block_hash = Some(found_block_hash);
            current.found_block_reward_atomic = found_block_reward_atomic;
            current.orphaned = false;
        }
        if matches!(
            self.payout_cfg.mode,
            PoolPayoutModeArg::Pplns | PoolPayoutModeArg::Hybrid
        ) {
            self.recompute_pplns_accruals();
        }
        self.open_next_round(end_height, end_tip_hash, now_unix_sec);
    }

    fn open_next_round(&mut self, start_height: u64, start_tip_hash: Hash256, now_unix_sec: u64) {
        self.current_round_id = self.current_round_id.saturating_add(1);
        self.current_round_start_height = start_height;
        self.current_round_start_tip_hash = start_tip_hash;
        self.current_round_start_unix_sec = now_unix_sec;
        self.rounds.push_back(PoolRoundRecord {
            round_id: self.current_round_id,
            start_height,
            start_tip_hash,
            start_unix_sec: now_unix_sec,
            end_height: None,
            end_tip_hash: None,
            end_unix_sec: None,
            closed_by_worker: None,
            found_block_hash: None,
            found_block_reward_atomic: 0,
            orphaned: false,
        });
        while self.rounds.len() > self.max_round_records {
            if self.rounds.pop_front().is_none() {
                break;
            }
        }
    }

    fn reconcile_with_runtime(&mut self, runtime: &ChainRuntime, now_unix_sec: u64) -> bool {
        let mut changed = false;
        for round in &mut self.rounds {
            let on_active_chain = match (round.end_height, round.end_tip_hash) {
                (Some(end_height), Some(end_tip_hash)) => {
                    runtime.block_hash_at_height(end_height) == Some(end_tip_hash)
                }
                _ => true,
            };
            let should_mark_orphaned = !on_active_chain;
            if round.orphaned != should_mark_orphaned {
                round.orphaned = should_mark_orphaned;
                changed = true;
            }
        }

        if let Some(open_round) = self.rounds.back_mut()
            && open_round.end_height.is_none()
        {
            let open_round_still_on_chain = runtime.block_hash_at_height(open_round.start_height)
                == Some(open_round.start_tip_hash);
            if !open_round_still_on_chain {
                let rebased_height = runtime.tip_height();
                let rebased_hash = runtime.tip_hash();
                open_round.start_height = rebased_height;
                open_round.start_tip_hash = rebased_hash;
                open_round.start_unix_sec = now_unix_sec;
                self.current_round_start_height = rebased_height;
                self.current_round_start_tip_hash = rebased_hash;
                self.current_round_start_unix_sec = now_unix_sec;
                changed = true;
            }
        }

        if changed
            && matches!(
                self.payout_cfg.mode,
                PoolPayoutModeArg::Pplns | PoolPayoutModeArg::Hybrid
            )
        {
            self.recompute_pplns_accruals();
        }

        changed
    }

    fn snapshot(&self) -> PoolLedgerSnapshot {
        let mut workers = self.workers.values().cloned().collect::<Vec<_>>();
        workers.sort_by(|a, b| a.worker.cmp(&b.worker));
        PoolLedgerSnapshot {
            network_id: self.network_id.clone(),
            current_round_id: self.current_round_id,
            shares: self.shares.iter().cloned().collect(),
            rounds: self.rounds.iter().cloned().collect(),
            workers,
            pending_payouts: self.pending_payouts.iter().cloned().collect(),
            completed_payouts: self.completed_payouts.iter().cloned().collect(),
        }
    }
}

#[derive(Clone, Debug)]
struct StratumShareSample {
    timestamp_unix_sec: u64,
    worker: String,
    expected_hashes: f64,
}

#[derive(Clone, Debug, Default)]
struct StratumWorkerCounters {
    accepted_total: u64,
    rejected_total: u64,
    blocks_found_total: u64,
    last_share_unix_sec: u64,
}

#[derive(Clone, Debug, Default)]
struct StratumPoolTelemetryState {
    accepted_total: u64,
    rejected_total: u64,
    blocks_found_total: u64,
    samples: VecDeque<StratumShareSample>,
    workers: HashMap<String, StratumWorkerCounters>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct StratumWorkerHashrateSnapshot {
    worker: String,
    hashrate_hps: f64,
    accepted_total: u64,
    rejected_total: u64,
    blocks_found_total: u64,
    last_share_unix_sec: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct StratumServerTelemetrySnapshot {
    timestamp_unix_sec: u64,
    active_clients: usize,
    workers_tracked_total: usize,
    workers_active: usize,
    hashrate_window_sec: u64,
    pool_hashrate_hps: f64,
    accepted_total: u64,
    rejected_total: u64,
    blocks_found_total: u64,
    top_workers: Vec<StratumWorkerHashrateSnapshot>,
}

impl StratumPoolTelemetryState {
    fn sanitize_worker_label(raw: &str) -> String {
        let compact = raw
            .chars()
            .filter(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | ':' | '.'))
            .take(80)
            .collect::<String>();
        if compact.is_empty() {
            "default".to_owned()
        } else {
            compact
        }
    }

    fn prune_samples(&mut self, now_unix_sec: u64, window_sec: u64) {
        while let Some(front) = self.samples.front() {
            if now_unix_sec.saturating_sub(front.timestamp_unix_sec) <= window_sec {
                break;
            }
            self.samples.pop_front();
        }
    }

    fn register_accepted_share(
        &mut self,
        worker: &str,
        now_unix_sec: u64,
        expected_hashes: f64,
        is_block: bool,
    ) {
        let worker_label = Self::sanitize_worker_label(worker);
        self.accepted_total = self.accepted_total.saturating_add(1);
        if is_block {
            self.blocks_found_total = self.blocks_found_total.saturating_add(1);
        }
        let counters = self.workers.entry(worker_label.clone()).or_default();
        counters.accepted_total = counters.accepted_total.saturating_add(1);
        if is_block {
            counters.blocks_found_total = counters.blocks_found_total.saturating_add(1);
        }
        counters.last_share_unix_sec = now_unix_sec;
        self.samples.push_back(StratumShareSample {
            timestamp_unix_sec: now_unix_sec,
            worker: worker_label,
            expected_hashes: expected_hashes.max(0.0),
        });
        self.prune_samples(now_unix_sec, STRATUM_HASHRATE_WINDOW_SEC);
    }

    fn register_rejected_share(&mut self, worker: &str, now_unix_sec: u64) {
        let worker_label = Self::sanitize_worker_label(worker);
        self.rejected_total = self.rejected_total.saturating_add(1);
        let counters = self.workers.entry(worker_label).or_default();
        counters.rejected_total = counters.rejected_total.saturating_add(1);
        counters.last_share_unix_sec = now_unix_sec;
        self.prune_samples(now_unix_sec, STRATUM_HASHRATE_WINDOW_SEC);
    }

    fn snapshot(
        &mut self,
        active_clients: usize,
        now_unix_sec: u64,
    ) -> StratumServerTelemetrySnapshot {
        self.prune_samples(now_unix_sec, STRATUM_HASHRATE_WINDOW_SEC);
        let window_sec = STRATUM_HASHRATE_WINDOW_SEC.max(1);
        let mut by_worker_hashes = HashMap::<String, f64>::new();
        let mut pool_hashes = 0.0f64;
        for sample in &self.samples {
            pool_hashes += sample.expected_hashes;
            *by_worker_hashes.entry(sample.worker.clone()).or_insert(0.0) += sample.expected_hashes;
        }
        let pool_hashrate_hps = pool_hashes / window_sec as f64;
        let mut top_workers = by_worker_hashes
            .into_iter()
            .map(|(worker, hashes)| {
                let counters = self.workers.get(&worker).cloned().unwrap_or_default();
                StratumWorkerHashrateSnapshot {
                    worker,
                    hashrate_hps: hashes / window_sec as f64,
                    accepted_total: counters.accepted_total,
                    rejected_total: counters.rejected_total,
                    blocks_found_total: counters.blocks_found_total,
                    last_share_unix_sec: counters.last_share_unix_sec,
                }
            })
            .collect::<Vec<_>>();
        top_workers.sort_by(|a, b| b.hashrate_hps.total_cmp(&a.hashrate_hps));
        if top_workers.len().saturating_sub(STRATUM_TOP_WORKERS_LIMIT) != 0 {
            top_workers.truncate(STRATUM_TOP_WORKERS_LIMIT);
        }
        let workers_active = top_workers
            .iter()
            .filter(|entry| entry.hashrate_hps > 0.0)
            .count();
        StratumServerTelemetrySnapshot {
            timestamp_unix_sec: now_unix_sec,
            active_clients,
            workers_tracked_total: self.workers.len(),
            workers_active,
            hashrate_window_sec: window_sec,
            pool_hashrate_hps,
            accepted_total: self.accepted_total,
            rejected_total: self.rejected_total,
            blocks_found_total: self.blocks_found_total,
            top_workers,
        }
    }
}

fn relay_fee_hint(runtime: &ChainRuntime, mempool: &Mempool, tx: &Transaction) -> u64 {
    tx_fee_from_known_prevouts(runtime, mempool, tx).unwrap_or(0)
}

fn tx_fee_from_known_prevouts(
    runtime: &ChainRuntime,
    mempool: &Mempool,
    tx: &Transaction,
) -> Option<u64> {
    if tx.inputs.is_empty() {
        return None;
    }
    let mut input_total = 0u128;
    for input in &tx.inputs {
        if input.prev_out.is_coinbase() {
            return None;
        }
        if let Some(utxo) = runtime.utxo_set().get(&input.prev_out) {
            input_total = input_total.checked_add(utxo.value as u128)?;
            continue;
        }
        let (parent, _fee) = mempool.get_with_fee(&input.prev_out.txid)?;
        let output = parent.outputs.get(input.prev_out.vout as usize)?;
        input_total = input_total.checked_add(output.value as u128)?;
    }
    let output_total = tx
        .outputs
        .iter()
        .try_fold(0u128, |acc, out| acc.checked_add(out.value as u128))?;
    if input_total < output_total {
        return None;
    }
    u64::try_from(input_total - output_total).ok()
}

fn template_fee_meets_minimum(fee: u64, min_required: u64) -> bool {
    fee >= min_required
}

fn sanitize_should_continue(pending_len: usize, safety_budget: usize) -> bool {
    pending_len > 0 && safety_budget > 0
}

fn sanitize_stalled(progressed: bool) -> bool {
    !progressed
}

fn should_persist_startup_mempool_cleanup(removed_confirmed_startup: usize) -> bool {
    removed_confirmed_startup > 0
}

fn relay_mark_outbound_worker_start(state: &Arc<Mutex<RelayServerState>>) {
    if let Ok(mut guard) = state.lock() {
        guard.outbound_worker_starts_total = guard.outbound_worker_starts_total.saturating_add(1);
    }
}

fn relay_mark_outbound_supervisor_start(state: &Arc<Mutex<RelayServerState>>) {
    if let Ok(mut guard) = state.lock() {
        guard.outbound_supervisor_starts_total =
            guard.outbound_supervisor_starts_total.saturating_add(1);
    }
}

fn relay_forget_pending_orphan_block(state: &mut RelayServerState, hash: Hash256) {
    state.pending_block_orphans.remove(&hash);
    state
        .pending_block_orphan_order
        .retain(|queued| *queued != hash);
}

fn relay_store_pending_orphan_block(state: &mut RelayServerState, block: scam_core::Block) {
    let block_hash = block.header.block_hash();
    if state.pending_block_orphans.contains_key(&block_hash) {
        return;
    }
    if state.pending_block_orphan_order.len() >= RELAY_MAX_PENDING_BLOCK_ORPHANS
        && let Some(evicted) = state.pending_block_orphan_order.pop_front()
    {
        state.pending_block_orphans.remove(&evicted);
    }
    state.pending_block_orphans.insert(block_hash, block);
    state.pending_block_orphan_order.push_back(block_hash);
}

fn relay_apply_main_chain_transition(
    state: &mut RelayServerState,
    chain_before: &[Hash256],
    chain_after: &[Hash256],
    now_unix_sec: u64,
) {
    let before_set = chain_before.iter().copied().collect::<HashSet<_>>();
    let after_set = chain_after.iter().copied().collect::<HashSet<_>>();

    let connected_hashes = chain_after
        .iter()
        .copied()
        .filter(|hash| !before_set.contains(hash))
        .collect::<Vec<_>>();
    let disconnected_hashes = chain_before
        .iter()
        .copied()
        .filter(|hash| !after_set.contains(hash))
        .collect::<Vec<_>>();

    let mut connected_txids = HashSet::<Hash256>::new();
    let mut connected_blocks = Vec::<scam_core::Block>::new();
    for hash in &connected_hashes {
        if let Some(block) = state.runtime.block_by_hash(hash).cloned() {
            for tx in block.transactions.iter().skip(1) {
                connected_txids.insert(tx.txid());
            }
            connected_blocks.push(block);
        }
    }

    if !connected_hashes.is_empty() || !disconnected_hashes.is_empty() {
        let confirmed = connected_txids.iter().copied().collect::<Vec<_>>();
        let _ = state.relay.mempool.remove_confirmed_txids(&confirmed);
        let _ = remove_mempool_txs_with_missing_inputs(&state.runtime, &mut state.relay.mempool);
    }

    for block in connected_blocks {
        let _ = state.relay.gossip.announce_block(block.clone());
        relay_forget_pending_orphan_block(state, block.header.block_hash());
    }

    let mut resurrect_candidates = Vec::<Transaction>::new();
    for hash in disconnected_hashes {
        let Some(block) = state.runtime.block_by_hash(&hash) else {
            continue;
        };
        for tx in block.transactions.iter().skip(1) {
            if !connected_txids.contains(&tx.txid()) {
                resurrect_candidates.push(tx.clone());
            }
        }
    }

    for tx in resurrect_candidates {
        let txid = tx.txid();
        if state.relay.mempool.contains(&txid) {
            continue;
        }
        let fee_hint = relay_fee_hint(&state.runtime, &state.relay.mempool, &tx);

        let missing = detect_missing_outpoints(&state.runtime, &state.relay.mempool, &tx);
        if missing.is_empty() {
            let _ = state.relay.mempool.insert_with_fee(tx, fee_hint);
            continue;
        }

        let _ = state
            .relay
            .orphan_pool
            .insert(tx, fee_hint, missing, now_unix_sec);
    }
}

fn relay_should_request_parent_sync(
    state: &mut RelayServerState,
    parent: Hash256,
    now_unix_sec: u64,
) -> bool {
    state
        .last_parent_sync_request_sec
        .retain(|_, ts| now_unix_sec.saturating_sub(*ts) <= RELAY_PARENT_RESYNC_COOLDOWN_SEC * 30);
    match state.last_parent_sync_request_sec.get(&parent).copied() {
        Some(last) if now_unix_sec.saturating_sub(last) < RELAY_PARENT_RESYNC_COOLDOWN_SEC => false,
        _ => {
            state
                .last_parent_sync_request_sec
                .insert(parent, now_unix_sec);
            true
        }
    }
}

fn relay_recovery_messages_for_unknown_parent(
    state: &mut RelayServerState,
    parent: Hash256,
    now_unix_sec: u64,
) -> Vec<WireMessage> {
    if !relay_should_request_parent_sync(state, parent, now_unix_sec) {
        return Vec::new();
    }
    let locator = build_block_locator(state.runtime.block_hashes());
    vec![
        WireMessage::GetData {
            items: vec![InventoryItem::Block(parent)],
        },
        WireMessage::GetBlocks {
            locator,
            stop: None,
        },
    ]
}

fn relay_try_apply_pending_orphans(state: &mut RelayServerState, now_unix_sec: u64) {
    let max_passes = state.pending_block_orphan_order.len().saturating_add(1);
    for _pass in 0..max_passes {
        let mut progressed = false;
        let queued = state
            .pending_block_orphan_order
            .iter()
            .copied()
            .collect::<Vec<_>>();
        for orphan_hash in queued {
            let Some(orphan_block) = state.pending_block_orphans.get(&orphan_hash).cloned() else {
                relay_forget_pending_orphan_block(state, orphan_hash);
                continue;
            };
            let parent = orphan_block.header.prev_block;
            if state.runtime.block_by_hash(&parent).is_none() {
                continue;
            }
            let chain_before = state.runtime.block_hashes().to_vec();
            match state.runtime.submit_block(orphan_block.clone()) {
                Ok(_) => {
                    let chain_after = state.runtime.block_hashes().to_vec();
                    relay_apply_main_chain_transition(
                        state,
                        &chain_before,
                        &chain_after,
                        now_unix_sec,
                    );
                    relay_forget_pending_orphan_block(state, orphan_hash);
                    state.last_parent_sync_request_sec.remove(&parent);
                    progressed = true;
                }
                Err(ChainError::UnknownParent { .. }) => {}
                Err(_) => {
                    // Drop invalid orphan candidates to avoid retry loops on malformed blocks.
                    relay_forget_pending_orphan_block(state, orphan_hash);
                }
            }
        }
        if !progressed {
            break;
        }
    }
}

fn nonempty_parent_dir(path: &Path) -> Option<&Path> {
    let parent = path.parent()?;
    if parent.as_os_str().is_empty() {
        None
    } else {
        Some(parent)
    }
}

fn relay_record_peer_tip_height(state: &mut RelayServerState, peer_id: u64, tip_height: u64) {
    let entry = state
        .peer_reported_tip_heights
        .entry(peer_id)
        .or_insert(tip_height);
    *entry = (*entry).max(tip_height);
}

fn relay_forget_peer_tip_height(state: &mut RelayServerState, peer_id: u64) {
    state.peer_reported_tip_heights.remove(&peer_id);
    state.peer_last_headers_request_sec.remove(&peer_id);
    state.peer_last_blocks_request_sec.remove(&peer_id);
}

fn relay_max_known_tip_height(state: &RelayServerState) -> u64 {
    let local_tip = state.runtime.tip_height();
    state
        .peer_reported_tip_heights
        .values()
        .copied()
        .max()
        .map_or(local_tip, |peer_tip| local_tip.max(peer_tip))
}

fn relay_estimate_headers_tip_height(
    runtime: &ChainRuntime,
    headers: &[scam_core::BlockHeader],
) -> Option<u64> {
    if headers.is_empty() {
        return None;
    }

    let chain = runtime.block_hashes();
    let mut known_heights = HashMap::<Hash256, u64>::with_capacity(chain.len() + headers.len());
    for (height, hash) in chain.iter().copied().enumerate() {
        known_heights.insert(hash, height as u64);
    }

    let mut tip_height = None::<u64>;
    for header in headers {
        let parent_height = *known_heights.get(&header.prev_block)?;
        let next_height = parent_height.saturating_add(1);
        known_heights.insert(header.block_hash(), next_height);
        tip_height = Some(next_height);
    }
    tip_height
}

fn relay_should_request_headers_catchup(
    state: &RelayServerState,
    peer_id: u64,
    now_unix_sec: u64,
) -> bool {
    let local_tip = state.runtime.tip_height();
    let peer_tip = state
        .peer_reported_tip_heights
        .get(&peer_id)
        .copied()
        .unwrap_or(local_tip);
    let last = state
        .peer_last_headers_request_sec
        .get(&peer_id)
        .copied()
        .unwrap_or(0);
    let elapsed = now_unix_sec.saturating_sub(last);
    if peer_tip > local_tip {
        let lag = peer_tip.saturating_sub(local_tip);
        let interval = if lag >= relay_headers_aggressive_lag_threshold() {
            relay_headers_aggressive_interval_sec()
        } else {
            relay_headers_catchup_interval_sec()
        };
        return elapsed >= interval;
    }
    elapsed >= relay_headers_probe_interval_sec()
}

fn relay_maybe_request_headers_catchup(
    state: &mut RelayServerState,
    peer_id: u64,
    now_unix_sec: u64,
) -> Option<WireMessage> {
    if !relay_should_request_headers_catchup(state, peer_id, now_unix_sec) {
        return None;
    }
    Some(relay_build_headers_request(state, peer_id, now_unix_sec))
}

fn relay_should_request_blocks_catchup(
    state: &RelayServerState,
    peer_id: u64,
    now_unix_sec: u64,
) -> bool {
    let local_tip = state.runtime.tip_height();
    let peer_tip = state
        .peer_reported_tip_heights
        .get(&peer_id)
        .copied()
        .unwrap_or(local_tip);
    if peer_tip <= local_tip {
        return false;
    }
    let last = state
        .peer_last_blocks_request_sec
        .get(&peer_id)
        .copied()
        .unwrap_or(0);
    let lag = peer_tip.saturating_sub(local_tip);
    let interval = if lag >= relay_headers_aggressive_lag_threshold() {
        relay_blocks_aggressive_interval_sec()
    } else {
        relay_blocks_catchup_interval_sec()
    };
    now_unix_sec.saturating_sub(last) >= interval
}

fn relay_maybe_request_blocks_catchup(
    state: &mut RelayServerState,
    peer_id: u64,
    now_unix_sec: u64,
) -> Option<WireMessage> {
    if !relay_should_request_blocks_catchup(state, peer_id, now_unix_sec) {
        return None;
    }
    Some(relay_build_blocks_request(state, peer_id, now_unix_sec))
}

fn relay_build_headers_request(
    state: &mut RelayServerState,
    peer_id: u64,
    now_unix_sec: u64,
) -> WireMessage {
    let locator = build_block_locator(state.runtime.block_hashes());
    state
        .peer_last_headers_request_sec
        .insert(peer_id, now_unix_sec);
    WireMessage::GetHeaders {
        locator,
        stop: None,
    }
}

fn relay_build_blocks_request(
    state: &mut RelayServerState,
    peer_id: u64,
    now_unix_sec: u64,
) -> WireMessage {
    let locator = build_block_locator(state.runtime.block_hashes());
    state
        .peer_last_blocks_request_sec
        .insert(peer_id, now_unix_sec);
    WireMessage::GetBlocks {
        locator,
        stop: None,
    }
}

fn relay_unknown_block_inv_count(state: &RelayServerState, items: &[InventoryItem]) -> u64 {
    items
        .iter()
        .filter(|item| match item {
            InventoryItem::Block(hash) => {
                state.runtime.header_by_hash(hash).is_none()
                    && !state.pending_block_orphans.contains_key(hash)
                    && !state.pending_compact_blocks.contains_key(hash)
            }
            InventoryItem::Tx(_) => false,
        })
        .count() as u64
}

fn relay_maybe_request_headers_on_block_inv(
    state: &mut RelayServerState,
    peer_id: u64,
    items: &[InventoryItem],
    now_unix_sec: u64,
) -> Option<WireMessage> {
    let unknown_count = relay_unknown_block_inv_count(state, items);
    if unknown_count == 0 {
        return None;
    }
    let local_tip = state.runtime.tip_height();
    // Treat an unknown block inventory as "peer is at least one block ahead",
    // then trigger accelerated headers catchup cadence.
    relay_record_peer_tip_height(state, peer_id, local_tip.saturating_add(unknown_count));
    let last = state
        .peer_last_headers_request_sec
        .get(&peer_id)
        .copied()
        .unwrap_or(0);
    if now_unix_sec.saturating_sub(last) < relay_headers_inv_trigger_interval_sec() {
        return None;
    }
    Some(relay_build_headers_request(state, peer_id, now_unix_sec))
}

fn relay_maybe_request_blocks_on_block_inv(
    state: &mut RelayServerState,
    peer_id: u64,
    items: &[InventoryItem],
    now_unix_sec: u64,
) -> Option<WireMessage> {
    if relay_unknown_block_inv_count(state, items) == 0 {
        return None;
    }
    let last = state
        .peer_last_blocks_request_sec
        .get(&peer_id)
        .copied()
        .unwrap_or(0);
    if now_unix_sec.saturating_sub(last) < relay_headers_inv_trigger_interval_sec() {
        return None;
    }
    Some(relay_build_blocks_request(state, peer_id, now_unix_sec))
}

fn relay_server_snapshot(
    state: &RelayServerState,
    active_peers: usize,
    now_unix_sec: u64,
) -> RelayServerTelemetrySnapshot {
    let mem = state.relay.mempool.telemetry();
    let orphan = state.relay.orphan_pool.telemetry();
    let gossip = state.relay.gossip.telemetry();
    let local_tip_height = state.runtime.tip_height();
    let max_known_tip_height = relay_max_known_tip_height(state);
    RelayServerTelemetrySnapshot {
        timestamp_unix_sec: now_unix_sec,
        active_peers,
        tip_height: local_tip_height,
        utxo_count: state.runtime.utxo_len(),
        cumulative_work: state.runtime.cumulative_work().to_str_radix(10),
        network_hashrate_hps: estimate_network_hashrate_hps(&state.runtime),
        max_known_tip_height,
        global_sync_lag_blocks: max_known_tip_height.saturating_sub(local_tip_height),
        tip_hash: state.runtime.tip_hash().to_hex(),
        mempool_len: state.relay.mempool.len(),
        orphan_pool_len: state.relay.orphan_pool.len(),
        mempool_inserted_total: mem.accepted_total,
        mempool_replaced_total: mem.replaced_total,
        mempool_removed_by_replacement_total: mem.removed_by_replacement_total,
        mempool_rejected_conflict_total: mem.rejected_conflict_total,
        orphan_accepted_total: orphan.accepted_total,
        orphan_evicted_total: orphan.evicted_total,
        orphan_expired_total: orphan.expired_total,
        orphan_promoted_total: orphan.promoted_total,
        gossip_replacement_rate_limited_total: gossip.replacement_rate_limited_total,
    }
}

fn append_relay_telemetry_snapshot(
    path: &Path,
    snapshot: &RelayServerTelemetrySnapshot,
) -> Result<(), NodeError> {
    if let Some(parent) = nonempty_parent_dir(path) {
        fs::create_dir_all(parent).map_err(|e| {
            NodeError::Runtime(format!(
                "cannot create relay telemetry directory {}: {e}",
                parent.display()
            ))
        })?;
    }
    let mut file = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .map_err(|e| {
            NodeError::Runtime(format!(
                "cannot open relay telemetry output {}: {e}",
                path.display()
            ))
        })?;
    let line = serde_json::to_string(snapshot)
        .map_err(|e| NodeError::Runtime(format!("cannot encode relay telemetry json: {e}")))?;
    file.write_all(line.as_bytes()).map_err(|e| {
        NodeError::Runtime(format!(
            "cannot write relay telemetry output {}: {e}",
            path.display()
        ))
    })?;
    file.write_all(b"\n").map_err(|e| {
        NodeError::Runtime(format!(
            "cannot finalize relay telemetry output {}: {e}",
            path.display()
        ))
    })?;
    Ok(())
}

fn append_jsonl_record<T: Serialize>(
    path: &Path,
    record: &T,
    context: &str,
) -> Result<(), NodeError> {
    if let Some(parent) = nonempty_parent_dir(path) {
        fs::create_dir_all(parent).map_err(|e| {
            NodeError::Runtime(format!(
                "cannot create {} telemetry directory {}: {e}",
                context,
                parent.display()
            ))
        })?;
    }
    let mut file = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .map_err(|e| {
            NodeError::Runtime(format!(
                "cannot open {} telemetry output {}: {e}",
                context,
                path.display()
            ))
        })?;
    let line = serde_json::to_string(record).map_err(|e| {
        NodeError::Runtime(format!("cannot encode {} telemetry json: {e}", context))
    })?;
    file.write_all(line.as_bytes()).map_err(|e| {
        NodeError::Runtime(format!(
            "cannot write {} telemetry output {}: {e}",
            context,
            path.display()
        ))
    })?;
    file.write_all(b"\n").map_err(|e| {
        NodeError::Runtime(format!(
            "cannot finalize {} telemetry output {}: {e}",
            context,
            path.display()
        ))
    })?;
    Ok(())
}

fn append_role_service_telemetry(
    path: &Path,
    role: &str,
    requests_total: u64,
    success_total: u64,
    error_total: u64,
) -> Result<(), NodeError> {
    let snapshot = RoleServiceTelemetry {
        timestamp_unix_sec: current_unix_sec()?,
        role: role.to_owned(),
        requests_total,
        success_total,
        error_total,
    };
    append_jsonl_record(path, &snapshot, "role-service")
}

fn compact_short_txid(txid: Hash256) -> u64 {
    let mut short = [0u8; 8];
    short.copy_from_slice(&txid.0[..8]);
    u64::from_be_bytes(short)
}

fn relay_compact_block_from_block(block: &scam_core::Block) -> CompactBlock {
    let prefilled = block
        .transactions
        .first()
        .map(|tx| {
            vec![PrefilledTxn {
                index: 0,
                tx: tx.clone(),
            }]
        })
        .unwrap_or_default();
    let short_txids = block
        .transactions
        .iter()
        .skip(1)
        .map(|tx| compact_short_txid(tx.txid()))
        .collect::<Vec<_>>();
    CompactBlock {
        header: block.header.clone(),
        tx_count: block.transactions.len() as u32,
        short_txids,
        prefilled,
    }
}

fn relay_lookup_mempool_tx_by_short_txid(
    mempool: &Mempool,
    short_txid: u64,
) -> Option<Transaction> {
    mempool
        .txids_by_feerate_desc()
        .into_iter()
        .find_map(|txid| {
            if compact_short_txid(txid) == short_txid {
                mempool.get(&txid).cloned()
            } else {
                None
            }
        })
}

fn relay_reconstruct_compact_transactions(
    mempool: &Mempool,
    compact: &CompactBlock,
) -> Result<(Vec<Option<Transaction>>, Vec<u32>), NodeError> {
    let tx_count = compact.tx_count as usize;
    if tx_count == 0 {
        return Err(NodeError::Runtime(
            "compact block has zero transaction count".to_owned(),
        ));
    }

    let mut transactions = vec![None; tx_count];
    for entry in &compact.prefilled {
        let index = entry.index as usize;
        if index >= tx_count {
            return Err(NodeError::Runtime(format!(
                "compact block prefilled index {} out of bounds for tx_count {}",
                entry.index, tx_count
            )));
        }
        transactions[index] = Some(entry.tx.clone());
    }

    let mut short_iter = compact.short_txids.iter().copied();
    let mut missing = Vec::<u32>::new();
    for (index, slot) in transactions.iter_mut().enumerate() {
        if slot.is_some() {
            continue;
        }
        let Some(short_txid) = short_iter.next() else {
            return Err(NodeError::Runtime(
                "compact block short txid list is shorter than required".to_owned(),
            ));
        };
        match relay_lookup_mempool_tx_by_short_txid(mempool, short_txid) {
            Some(tx) => *slot = Some(tx),
            None => missing.push(index as u32),
        }
    }
    if short_iter.next().is_some() {
        return Err(NodeError::Runtime(
            "compact block short txid list is longer than required".to_owned(),
        ));
    }
    Ok((transactions, missing))
}

fn relay_try_build_block_from_compact(
    header: &scam_core::BlockHeader,
    transactions: &[Option<Transaction>],
) -> Option<scam_core::Block> {
    if transactions.iter().any(Option::is_none) {
        return None;
    }
    Some(scam_core::Block {
        header: header.clone(),
        transactions: transactions
            .iter()
            .filter_map(Clone::clone)
            .collect::<Vec<_>>(),
    })
}

fn relay_compact_announcement_enabled(state: &RelayServerState, peer_id: u64) -> bool {
    state
        .peer_compact_pref
        .get(&peer_id)
        .copied()
        .unwrap_or(false)
}

fn relay_inventory_messages_for_peer(
    state: &RelayServerState,
    peer_id: u64,
    items: Vec<InventoryItem>,
) -> Vec<WireMessage> {
    if !relay_compact_announcement_enabled(state, peer_id) {
        return vec![WireMessage::Inv { items }];
    }
    let mut out = Vec::<WireMessage>::new();
    let mut pending = Vec::<InventoryItem>::new();
    for item in items {
        match item {
            InventoryItem::Block(hash) => {
                if !pending.is_empty() {
                    out.push(WireMessage::Inv {
                        items: std::mem::take(&mut pending),
                    });
                }
                if let Some(block) = state.runtime.block_by_hash(&hash) {
                    out.push(WireMessage::CmpctBlock {
                        block: relay_compact_block_from_block(block),
                    });
                } else {
                    pending.push(InventoryItem::Block(hash));
                }
            }
            other => pending.push(other),
        }
    }
    if !pending.is_empty() {
        out.push(WireMessage::Inv { items: pending });
    }
    out
}

fn relay_messages_for_peer(
    state: &RelayServerState,
    peer_id: u64,
    messages: Vec<WireMessage>,
) -> Vec<WireMessage> {
    let mut out = Vec::<WireMessage>::new();
    for message in messages {
        match message {
            WireMessage::Inv { items } => {
                out.extend(relay_inventory_messages_for_peer(state, peer_id, items));
            }
            other => out.push(other),
        }
    }
    out
}

fn relay_gossip_outbound_for_peer(
    state: &RelayServerState,
    peer_id: u64,
    outbound: Vec<scam_p2p::OutboundMessage>,
) -> Vec<WireMessage> {
    let mut out = Vec::<WireMessage>::new();
    for msg in outbound.into_iter().filter(|msg| msg.peer_id == peer_id) {
        match msg.message {
            WireMessage::Inv { items } => {
                out.extend(relay_inventory_messages_for_peer(state, peer_id, items));
            }
            other => out.push(other),
        }
    }
    out
}

fn relay_timeout_streak_reached_limit(timeout_streak: u32) -> bool {
    timeout_streak >= RELAY_MAX_CONSECUTIVE_READ_TIMEOUTS.max(1)
}

fn relay_async_read_poll_interval_ms(read_timeout_sec: u64) -> u64 {
    let total_ms = read_timeout_sec.max(1).saturating_mul(1_000);
    let poll_ms = env_nonzero_u64("SCAM_RELAY_ASYNC_READ_POLL_MS")
        .unwrap_or(RELAY_ASYNC_READ_POLL_INTERVAL_MS);
    poll_ms.min(total_ms).max(1)
}

fn relay_async_timeout_streak_limit(read_timeout_sec: u64, poll_interval_ms: u64) -> u32 {
    let total_ms = read_timeout_sec.max(1).saturating_mul(1_000);
    let legacy_budget_ms = total_ms.saturating_mul(RELAY_MAX_CONSECUTIVE_READ_TIMEOUTS as u64);
    let per_poll = poll_interval_ms.max(1);
    let limit = (legacy_budget_ms.saturating_add(per_poll).saturating_sub(1)) / per_poll;
    limit.clamp(1, u32::MAX as u64) as u32
}

fn relay_startup_send_failed(startup_sent: bool) -> bool {
    !startup_sent
}

fn relay_has_periodic_outbound(periodic_outbound: &[WireMessage]) -> bool {
    !periodic_outbound.is_empty()
}

fn relay_should_abort_after_startup_send(mode: RelayPeerSessionMode, startup_sent: bool) -> bool {
    match mode {
        RelayPeerSessionMode::Outbound => relay_startup_send_failed(startup_sent),
        RelayPeerSessionMode::Inbound => false,
    }
}

fn should_persist_peer_reputation(delta: RuntimePeerReputation) -> bool {
    delta.replacement_rate_limited_total > 0 || delta.protocol_violation_total > 0
}

fn merge_outbound_targets(
    anchor_targets: Vec<String>,
    selected_targets: Vec<String>,
    max_outbound_peers: usize,
) -> Vec<String> {
    let mut merged = Vec::<String>::new();
    let mut seen = HashSet::<String>::new();
    let max_outbound_peers = max_outbound_peers.max(1);
    for target in anchor_targets.into_iter().chain(selected_targets) {
        if target.trim().is_empty() {
            continue;
        }
        if seen.insert(target.clone()) {
            merged.push(target);
        }
        if merged.len() >= max_outbound_peers {
            break;
        }
    }
    merged
}

fn relay_parent_request_cache_cleanup(state: &mut RelayServerState, now_unix_sec: u64) {
    state.pending_parent_tx_requests.retain(|_, requested_at| {
        now_unix_sec.saturating_sub(*requested_at) < RELAY_PARENT_REQUEST_TTL_SEC
    });
}

fn relay_parent_getdata_for_missing_outpoints(
    state: &mut RelayServerState,
    missing: &[OutPoint],
    now_unix_sec: u64,
) -> Result<Vec<InventoryItem>, NodeError> {
    relay_parent_request_cache_cleanup(state, now_unix_sec);
    let mut unique_txids = missing
        .iter()
        .map(|outpoint| outpoint.txid)
        .collect::<Vec<_>>();
    unique_txids.sort_unstable();
    unique_txids.dedup();

    if unique_txids.len() > RELAY_MAX_ORPHAN_PARENT_REQUESTS {
        return Err(NodeError::Runtime(format!(
            "orphan transaction references too many unknown parents: got={}, limit={}",
            unique_txids.len(),
            RELAY_MAX_ORPHAN_PARENT_REQUESTS
        )));
    }

    let mut items = Vec::<InventoryItem>::new();
    for txid in unique_txids {
        if state.pending_parent_tx_requests.contains_key(&txid) {
            continue;
        }
        state.pending_parent_tx_requests.insert(txid, now_unix_sec);
        items.push(InventoryItem::Tx(txid));
    }
    Ok(items)
}

fn load_relay_outbound_feeler_target(
    peers_dir: &Path,
    cfg: &ChainConfig,
    bind_addr: &str,
    excluded_targets: &HashSet<String>,
) -> Result<Option<String>, NodeError> {
    let (peers_db_path, legacy_txt_path) = peer_book_paths(peers_dir, &cfg.network_id);
    let mut peer_book = match load_with_retry(10, 15, is_peer_book_db_lock_conflict, || {
        load_or_init_peer_book(&cfg.network_id, &peers_db_path, &legacy_txt_path)
    })? {
        Some(book) => book,
        None => return Ok(None),
    };
    sort_and_dedup_peer_book(&mut peer_book);
    let network_policy = RelayNetworkPolicy::from_env();
    let mut candidates = peer_book
        .peers
        .into_iter()
        .filter(|peer| !excluded_targets.contains(&peer.address))
        .filter(|peer| !relay_target_matches_bind(bind_addr, &peer.address))
        .filter(|peer| relay_target_allowed_by_policy(&peer.address, &network_policy))
        .collect::<Vec<_>>();
    candidates.sort_unstable_by(|a, b| {
        a.last_seen_unix_sec
            .cmp(&b.last_seen_unix_sec)
            .then_with(|| a.ban_score.cmp(&b.ban_score))
            .then_with(|| a.address.cmp(&b.address))
    });
    Ok(candidates.into_iter().next().map(|peer| peer.address))
}

fn relay_known_peer_addresses(state: &RelayServerState, max_items: usize) -> Vec<PeerAddress> {
    state
        .known_peer_addresses
        .iter()
        .take(max_items)
        .cloned()
        .collect::<Vec<_>>()
}

fn relay_queue_peer_book_update(state: &mut RelayServerState, entry: PeerAddress) {
    if entry.address.trim().is_empty() {
        return;
    }
    if parse_relay_target_endpoint(&entry.address).is_none() {
        return;
    }
    if let Some(existing) = state
        .pending_peer_book_updates
        .iter_mut()
        .find(|known| known.address == entry.address)
    {
        existing.last_seen_unix_sec = existing.last_seen_unix_sec.max(entry.last_seen_unix_sec);
        existing.services |= entry.services;
        return;
    }
    state.pending_peer_book_updates.push(entry);
    if state.pending_peer_book_updates.len() <= RELAY_MAX_PENDING_PEER_BOOK_UPDATES {
        return;
    }
    state
        .pending_peer_book_updates
        .sort_unstable_by(|a, b| a.address.cmp(&b.address));
    state
        .pending_peer_book_updates
        .dedup_by(|a, b| a.address == b.address);
    let overflow = state
        .pending_peer_book_updates
        .len()
        .saturating_sub(RELAY_MAX_PENDING_PEER_BOOK_UPDATES);
    if overflow == 0 {
        return;
    }
    state.pending_peer_book_updates.drain(0..overflow);
}

fn relay_merge_known_peer_addresses(state: &mut RelayServerState, incoming: &[PeerAddress]) {
    if incoming.is_empty() {
        return;
    }
    let mut by_addr = HashMap::<String, PeerAddress>::new();
    for entry in &state.known_peer_addresses {
        by_addr.insert(entry.address.clone(), entry.clone());
    }
    for entry in incoming {
        if entry.address.trim().is_empty() {
            continue;
        }
        if parse_relay_target_endpoint(&entry.address).is_none() {
            continue;
        }
        by_addr
            .entry(entry.address.clone())
            .and_modify(|existing| {
                let before_seen = existing.last_seen_unix_sec;
                let before_services = existing.services;
                existing.last_seen_unix_sec =
                    existing.last_seen_unix_sec.max(entry.last_seen_unix_sec);
                existing.services |= entry.services;
                if existing.last_seen_unix_sec != before_seen
                    || existing.services != before_services
                {
                    relay_queue_peer_book_update(state, existing.clone());
                }
            })
            .or_insert_with(|| {
                relay_queue_peer_book_update(state, entry.clone());
                entry.clone()
            });
    }
    let mut merged = by_addr.into_values().collect::<Vec<_>>();
    merged.sort_unstable_by(|a, b| a.address.cmp(&b.address));
    merged.truncate(2_000);
    state.known_peer_addresses = merged;
}

fn relay_persist_peer_book_updates(
    store: &PeerBookStore,
    updates: &[PeerAddress],
) -> Result<(), NodeError> {
    if updates.is_empty() {
        return Ok(());
    }
    let now_unix_sec = current_unix_sec().unwrap_or(0);
    let mut unique_updates = updates
        .iter()
        .filter(|entry| !entry.address.trim().is_empty())
        .filter(|entry| parse_relay_target_endpoint(&entry.address).is_some())
        .cloned()
        .collect::<Vec<_>>();
    if unique_updates.is_empty() {
        return Ok(());
    }
    unique_updates.sort_unstable_by(|a, b| a.address.cmp(&b.address));
    unique_updates.dedup_by(|a, b| a.address == b.address);

    let mut peer_book = match load_with_retry(8, 10, is_peer_book_db_lock_conflict, || {
        load_or_init_peer_book(
            &store.network_id,
            &store.peers_db_path,
            &store.legacy_txt_path,
        )
    })? {
        Some(book) => book,
        None => return Ok(()),
    };

    let mut changed = false;
    for entry in unique_updates {
        if let Some(existing) = find_peer_record_mut(&mut peer_book, &entry.address) {
            let next_last_seen = existing
                .last_seen_unix_sec
                .max(entry.last_seen_unix_sec)
                .max(now_unix_sec);
            if next_last_seen != existing.last_seen_unix_sec {
                existing.last_seen_unix_sec = next_last_seen;
                changed = true;
            }
            let next_ban = existing.ban_score.saturating_sub(1);
            if next_ban != existing.ban_score {
                existing.ban_score = next_ban;
                changed = true;
            }
            continue;
        }
        peer_book.peers.push(PeerAddressRecord {
            address: entry.address,
            last_seen_unix_sec: entry.last_seen_unix_sec.max(now_unix_sec),
            ban_score: 0,
        });
        changed = true;
    }

    if !changed {
        return Ok(());
    }
    sort_and_dedup_peer_book(&mut peer_book);
    persist_with_retry(
        8,
        10,
        is_peer_book_db_lock_conflict,
        "peer book persist failed for unknown reason",
        || save_peer_book_db(&store.peers_db_path, &peer_book).map_err(NodeError::from),
    )
}

fn relay_flush_pending_peer_book_updates(
    state: &Arc<Mutex<RelayServerState>>,
) -> Result<(), NodeError> {
    let (store, updates) = {
        let mut guard = state
            .lock()
            .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
        if guard.pending_peer_book_updates.is_empty() {
            return Ok(());
        }
        let updates = std::mem::take(&mut guard.pending_peer_book_updates);
        (guard.peer_book_store.clone(), updates)
    };
    let Some(store) = store else {
        return Ok(());
    };
    relay_persist_peer_book_updates(&store, &updates)
}

fn relay_register_connected_peer_address(state: &mut RelayServerState, address: &str, now: u64) {
    if address.trim().is_empty() {
        return;
    }
    relay_merge_known_peer_addresses(
        state,
        &[PeerAddress {
            address: address.to_owned(),
            services: 1,
            last_seen_unix_sec: now,
        }],
    );
}

fn relay_submit_incoming_block(
    state: &mut RelayServerState,
    block: scam_core::Block,
    now_unix_sec: u64,
) -> Result<Vec<WireMessage>, NodeError> {
    let block_hash = block.header.block_hash();
    state.pending_compact_blocks.remove(&block_hash);
    let chain_before = state.runtime.block_hashes().to_vec();
    match state.runtime.submit_block(block.clone()) {
        Ok(_) => {
            let chain_after = state.runtime.block_hashes().to_vec();
            relay_apply_main_chain_transition(state, &chain_before, &chain_after, now_unix_sec);
            relay_forget_pending_orphan_block(state, block_hash);
            relay_try_apply_pending_orphans(state, now_unix_sec);
            Ok(Vec::new())
        }
        Err(ChainError::UnknownParent { parent, .. }) => {
            relay_store_pending_orphan_block(state, block);
            Ok(relay_recovery_messages_for_unknown_parent(
                state,
                parent,
                now_unix_sec,
            ))
        }
        Err(err) => Err(NodeError::Chain(err)),
    }
}

fn relay_collect_getdata_from_memory(
    state: &RelayServerState,
    items: Vec<InventoryItem>,
) -> (Vec<WireMessage>, Vec<Hash256>, Vec<InventoryItem>) {
    let mut out = Vec::<WireMessage>::new();
    let mut missing_block_hashes = Vec::<Hash256>::new();
    let mut not_found = Vec::<InventoryItem>::new();

    for item in items {
        match item {
            InventoryItem::Tx(txid) => {
                if let Some(tx) = state.relay.mempool.get(&txid).cloned() {
                    out.push(WireMessage::Tx { tx });
                } else {
                    not_found.push(InventoryItem::Tx(txid));
                }
            }
            InventoryItem::Block(hash) => {
                if let Some(block) = state.runtime.block_by_hash(&hash).cloned() {
                    out.push(WireMessage::Block { block });
                } else {
                    missing_block_hashes.push(hash);
                }
            }
        }
    }

    (out, missing_block_hashes, not_found)
}

enum RelayArchiveLookup {
    Found(scam_core::Block),
    Missing,
    Busy,
}

fn relay_archive_lookup_from_result(
    hash: Hash256,
    looked_up: Result<Option<Option<scam_core::Block>>, NodeError>,
) -> Result<RelayArchiveLookup, NodeError> {
    match looked_up {
        Ok(Some(Some(block))) => Ok(RelayArchiveLookup::Found(block)),
        Ok(Some(None)) | Ok(None) => Ok(RelayArchiveLookup::Missing),
        Err(err) if is_runtime_db_lock_conflict(&err) => {
            // Under relay/rpc concurrency this can be transient; don't poison the session
            // and don't emit NotFound for a potentially existing block.
            eprintln!(
                "warning: relay archive lookup lock contention for block {} (serving soft-miss)",
                hash
            );
            Ok(RelayArchiveLookup::Busy)
        }
        Err(err) => Err(err),
    }
}

fn relay_archive_lookup_block(
    archive_db_path: &Path,
    hash: Hash256,
) -> Result<RelayArchiveLookup, NodeError> {
    let looked_up = load_with_retry(10, 10, is_runtime_db_lock_conflict, || {
        load_block_by_hash_db(archive_db_path, hash).map_err(NodeError::from)
    });
    relay_archive_lookup_from_result(hash, looked_up)
}

fn relay_gossip_error_is_non_fatal(err: &GossipError) -> bool {
    matches!(err, GossipError::Recon(detail)
        if detail.contains("unknown reconciliation round salt=")
            || detail.contains("received sketch for unknown round salt=")
            || detail.contains("reqsketchext for non-responder round salt="))
}

fn relay_handle_gossip_message(
    state: &mut RelayServerState,
    peer_id: u64,
    message: WireMessage,
) -> Result<Vec<WireMessage>, NodeError> {
    match state.relay.gossip.on_message(peer_id, message) {
        Ok(outbound) => Ok(relay_gossip_outbound_for_peer(state, peer_id, outbound)),
        Err(err) if relay_gossip_error_is_non_fatal(&err) => {
            eprintln!("warning: ignoring non-fatal relay recon race for peer {peer_id}: {err}");
            Ok(Vec::new())
        }
        Err(err) => Err(NodeError::Gossip(err)),
    }
}

fn process_relay_wire_message_with_archive(
    state: &mut RelayServerState,
    peer_id: u64,
    message: WireMessage,
    now_unix_sec: u64,
    archive_db_path: Option<&Path>,
) -> Result<Vec<WireMessage>, NodeError> {
    match message {
        WireMessage::GetData { items } => {
            let (mut out, missing_block_hashes, mut not_found) =
                relay_collect_getdata_from_memory(state, items);
            for hash in missing_block_hashes {
                let archive_lookup = match archive_db_path {
                    Some(path) => relay_archive_lookup_block(path, hash)?,
                    None => RelayArchiveLookup::Missing,
                };
                match archive_lookup {
                    RelayArchiveLookup::Found(block) => out.push(WireMessage::Block { block }),
                    RelayArchiveLookup::Missing => not_found.push(InventoryItem::Block(hash)),
                    RelayArchiveLookup::Busy => {}
                }
            }
            if has_inventory_delta_changes(0, not_found.len()) {
                out.push(WireMessage::NotFound { items: not_found });
            }
            Ok(out)
        }
        other => process_relay_wire_message_inner(state, peer_id, other, now_unix_sec),
    }
}

#[cfg(test)]
fn process_relay_wire_message(
    state: &mut RelayServerState,
    peer_id: u64,
    message: WireMessage,
    now_unix_sec: u64,
) -> Result<Vec<WireMessage>, NodeError> {
    process_relay_wire_message_with_archive(state, peer_id, message, now_unix_sec, None)
}

fn relay_mark_protocol_violation(state: &mut RelayServerState, peer_id: u64, _now_unix_sec: u64) {
    let _ = state
        .relay
        .gossip
        .penalize_peer(peer_id, RELAY_PROTOCOL_PENALTY);
    let entry = state.peer_runtime_reputation.entry(peer_id).or_default();
    entry.protocol_violation_total = entry.protocol_violation_total.saturating_add(1);
    entry.last_protocol_violation_unix_sec = _now_unix_sec;
}

fn relay_protocol_violation(
    state: &mut RelayServerState,
    peer_id: u64,
    now_unix_sec: u64,
    detail: impl Into<String>,
) -> NodeError {
    relay_mark_protocol_violation(state, peer_id, now_unix_sec);
    NodeError::Runtime(detail.into())
}

fn relay_missing_blocks_from_headers(
    state: &RelayServerState,
    headers: &[scam_core::BlockHeader],
) -> Result<(Vec<InventoryItem>, bool), NodeError> {
    if headers.get(RELAY_MAX_HEADERS_PER_ANNOUNCEMENT).is_some() {
        return Err(NodeError::Runtime(format!(
            "headers announcement exceeds limit: got={}, limit={}",
            headers.len(),
            RELAY_MAX_HEADERS_PER_ANNOUNCEMENT
        )));
    }
    if headers.is_empty() {
        return Ok((Vec::new(), false));
    }

    let mut seen = HashSet::<Hash256>::with_capacity(headers.len());
    let mut announced = HashSet::<Hash256>::with_capacity(headers.len());
    let mut missing = Vec::<InventoryItem>::new();

    for (index, header) in headers.iter().enumerate() {
        if !scam_core::header_meets_pow(header) {
            return Err(NodeError::Runtime(format!(
                "headers announcement contains invalid pow at index {}",
                index
            )));
        }
        let hash = header.block_hash();
        if !seen.insert(hash) {
            return Err(NodeError::Runtime(format!(
                "headers announcement contains duplicate hash {}",
                hash
            )));
        }
        if state.runtime.header_by_hash(&header.prev_block).is_none()
            && !announced.contains(&header.prev_block)
        {
            return Ok((missing, true));
        }
        announced.insert(hash);
        if state.runtime.block_by_hash(&hash).is_none() {
            missing.push(InventoryItem::Block(hash));
        }
    }

    Ok((missing, false))
}

async fn process_relay_getdata_with_archive_async(
    state: &Arc<Mutex<RelayServerState>>,
    items: Vec<InventoryItem>,
    runtime_db_path: &Path,
) -> Result<Vec<WireMessage>, NodeError> {
    let (mut out, missing_block_hashes, mut not_found) = {
        let guard = state
            .lock()
            .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
        relay_collect_getdata_from_memory(&guard, items)
    };

    if !missing_block_hashes.is_empty() {
        let runtime_db_path = runtime_db_path.to_path_buf();
        let looked_up = tokio::task::spawn_blocking(move || {
            let mut blocks = Vec::<(Hash256, RelayArchiveLookup)>::new();
            for hash in missing_block_hashes {
                let lookup = relay_archive_lookup_block(&runtime_db_path, hash)?;
                blocks.push((hash, lookup));
            }
            Ok::<Vec<(Hash256, RelayArchiveLookup)>, NodeError>(blocks)
        })
        .await
        .map_err(|err| NodeError::Runtime(format!("relay archive lookup task failed: {err}")))??;

        for (hash, lookup) in looked_up {
            match lookup {
                RelayArchiveLookup::Found(block) => out.push(WireMessage::Block { block }),
                RelayArchiveLookup::Missing => not_found.push(InventoryItem::Block(hash)),
                RelayArchiveLookup::Busy => {}
            }
        }
    }

    if has_inventory_delta_changes(0, not_found.len()) {
        out.push(WireMessage::NotFound { items: not_found });
    }
    Ok(out)
}

fn process_relay_wire_message_inner(
    state: &mut RelayServerState,
    peer_id: u64,
    message: WireMessage,
    now_unix_sec: u64,
) -> Result<Vec<WireMessage>, NodeError> {
    match message {
        WireMessage::Ping { nonce } => Ok(vec![WireMessage::Pong { nonce }]),
        WireMessage::Version { .. } => {
            let recon_offer = state.relay.gossip.build_send_recon(peer_id)?;
            Ok(vec![
                WireMessage::Verack,
                recon_offer,
                WireMessage::SendCmpct {
                    high_bandwidth: false,
                    version: 1,
                },
                WireMessage::GetAddr,
            ])
        }
        WireMessage::Verack | WireMessage::Pong { .. } => Ok(Vec::new()),
        WireMessage::GetAddr => Ok(vec![WireMessage::Addr {
            peers: relay_known_peer_addresses(state, 250),
        }]),
        WireMessage::Addr { peers } => {
            if peers.len() > RELAY_MAX_ADDR_ITEMS {
                return Err(relay_protocol_violation(
                    state,
                    peer_id,
                    now_unix_sec,
                    format!(
                        "addr message exceeds limit: got={}, limit={}",
                        peers.len(),
                        RELAY_MAX_ADDR_ITEMS
                    ),
                ));
            }
            relay_merge_known_peer_addresses(state, &peers);
            Ok(Vec::new())
        }
        WireMessage::SendCmpct {
            high_bandwidth,
            version,
        } => {
            let enabled = high_bandwidth && version >= 1;
            state.peer_compact_pref.insert(peer_id, enabled);
            Ok(Vec::new())
        }
        WireMessage::GetHeaders { locator, stop } => {
            if locator.len() > RELAY_MAX_LOCATOR_ITEMS {
                return Err(relay_protocol_violation(
                    state,
                    peer_id,
                    now_unix_sec,
                    format!(
                        "getheaders locator exceeds limit: got={}, limit={}",
                        locator.len(),
                        RELAY_MAX_LOCATOR_ITEMS
                    ),
                ));
            }
            let mut headers_by_hash = HashMap::new();
            for hash in state.runtime.block_hashes() {
                if let Some(header) = state.runtime.header_by_hash(hash) {
                    headers_by_hash.insert(*hash, header.clone());
                }
            }
            let headers = select_headers_for_peer(
                state.runtime.block_hashes(),
                &headers_by_hash,
                &locator,
                stop,
                2_000,
            );
            Ok(vec![WireMessage::Headers { headers }])
        }
        WireMessage::GetBlocks { locator, stop } => {
            if locator.len() > RELAY_MAX_LOCATOR_ITEMS {
                return Err(relay_protocol_violation(
                    state,
                    peer_id,
                    now_unix_sec,
                    format!(
                        "getblocks locator exceeds limit: got={}, limit={}",
                        locator.len(),
                        RELAY_MAX_LOCATOR_ITEMS
                    ),
                ));
            }
            let hashes =
                select_block_hashes_for_peer(state.runtime.block_hashes(), &locator, stop, 2_000);
            let items = hashes.into_iter().map(InventoryItem::Block).collect();
            Ok(vec![WireMessage::Inv { items }])
        }
        WireMessage::Headers { headers } => {
            let (missing, has_parent_gap) = relay_missing_blocks_from_headers(state, &headers)
                .map_err(|err| {
                    relay_protocol_violation(
                        state,
                        peer_id,
                        now_unix_sec,
                        format!("invalid headers announcement: {err}"),
                    )
                })?;
            if let Some(announced_tip_height) =
                relay_estimate_headers_tip_height(&state.runtime, &headers)
            {
                relay_record_peer_tip_height(state, peer_id, announced_tip_height);
            } else if has_parent_gap {
                // Parent gap means peer is likely ahead of our local view.
                let local_tip = state.runtime.tip_height();
                relay_record_peer_tip_height(state, peer_id, local_tip.saturating_add(1));
            }
            let mut out = Vec::new();
            if !missing.is_empty() {
                out.push(WireMessage::GetData { items: missing });
            }
            if has_parent_gap
                && let Some(get_headers) =
                    relay_maybe_request_headers_catchup(state, peer_id, now_unix_sec)
            {
                out.push(get_headers);
                if let Some(get_blocks) =
                    relay_maybe_request_blocks_catchup(state, peer_id, now_unix_sec)
                {
                    out.push(get_blocks);
                }
            }
            Ok(out)
        }
        WireMessage::GetData { items } => {
            let (mut out, missing_block_hashes, mut not_found) =
                relay_collect_getdata_from_memory(state, items);
            for hash in missing_block_hashes {
                not_found.push(InventoryItem::Block(hash));
            }
            if has_inventory_delta_changes(0, not_found.len()) {
                out.push(WireMessage::NotFound { items: not_found });
            }
            Ok(out)
        }
        WireMessage::Inv { items } => {
            let maybe_headers =
                relay_maybe_request_headers_on_block_inv(state, peer_id, &items, now_unix_sec);
            let maybe_blocks =
                relay_maybe_request_blocks_on_block_inv(state, peer_id, &items, now_unix_sec);
            let mut out = relay_handle_gossip_message(state, peer_id, WireMessage::Inv { items })?;
            if let Some(get_headers) = maybe_headers {
                out.push(get_headers);
            }
            if let Some(get_blocks) = maybe_blocks {
                out.push(get_blocks);
            }
            Ok(out)
        }
        WireMessage::SendRecon {
            enabled,
            version,
            short_id_bits,
            implementation,
            salt,
            max_sketch_items,
            max_diff_items,
        } => relay_handle_gossip_message(
            state,
            peer_id,
            WireMessage::SendRecon {
                enabled,
                version,
                short_id_bits,
                implementation,
                salt,
                max_sketch_items,
                max_diff_items,
            },
        ),
        WireMessage::ReqRecon { salt, set_size } => {
            relay_handle_gossip_message(state, peer_id, WireMessage::ReqRecon { salt, set_size })
        }
        WireMessage::Sketch {
            salt,
            bits,
            capacity,
            implementation,
            bytes,
        } => relay_handle_gossip_message(
            state,
            peer_id,
            WireMessage::Sketch {
                salt,
                bits,
                capacity,
                implementation,
                bytes,
            },
        ),
        WireMessage::ReqSketchExt { salt, capacity } => relay_handle_gossip_message(
            state,
            peer_id,
            WireMessage::ReqSketchExt { salt, capacity },
        ),
        WireMessage::ReqTx { salt, short_ids } => {
            relay_handle_gossip_message(state, peer_id, WireMessage::ReqTx { salt, short_ids })
        }
        WireMessage::ReconcileDiff {
            salt,
            announce_txids,
            request_txids,
        } => relay_handle_gossip_message(
            state,
            peer_id,
            WireMessage::ReconcileDiff {
                salt,
                announce_txids,
                request_txids,
            },
        ),
        WireMessage::Tx { tx } => {
            let txid = tx.txid();
            relay_parent_request_cache_cleanup(state, now_unix_sec);
            state.pending_parent_tx_requests.remove(&txid);
            let fee_hint = relay_fee_hint(&state.runtime, &state.relay.mempool, &tx);
            let missing_outpoints =
                detect_missing_outpoints(&state.runtime, &state.relay.mempool, &tx);
            match admit_peer_tx_into_relay(
                &mut state.relay,
                &state.runtime,
                peer_id,
                tx,
                fee_hint,
                now_unix_sec,
            ) {
                Ok(()) => {
                    if !missing_outpoints.is_empty() {
                        let parents = relay_parent_getdata_for_missing_outpoints(
                            state,
                            &missing_outpoints,
                            now_unix_sec,
                        )
                        .map_err(|err| {
                            relay_protocol_violation(
                                state,
                                peer_id,
                                now_unix_sec,
                                format!("invalid orphan parent set: {err}"),
                            )
                        })?;
                        if parents.is_empty() {
                            return Ok(Vec::new());
                        }
                        return Ok(vec![WireMessage::GetData { items: parents }]);
                    }
                    Ok(vec![WireMessage::Inv {
                        items: vec![InventoryItem::Tx(txid)],
                    }])
                }
                Err(NodeError::Gossip(GossipError::ReplacementRateLimited { .. })) => {
                    relay_mark_peer_replacement_rate_limited(state, peer_id, now_unix_sec);
                    Ok(vec![WireMessage::NotFound {
                        items: vec![InventoryItem::Tx(txid)],
                    }])
                }
                Err(NodeError::Mempool(MempoolError::FeeTooLow { .. })) => Ok(Vec::new()),
                Err(err) => Err(err),
            }
        }
        WireMessage::CmpctBlock { block } => {
            let block_hash = block.header.block_hash();
            let (transactions, missing_indexes) =
                relay_reconstruct_compact_transactions(&state.relay.mempool, &block)?;
            if missing_indexes.is_empty() {
                let block = relay_try_build_block_from_compact(&block.header, &transactions)
                    .ok_or_else(|| {
                        NodeError::Runtime(
                            "compact block reconstruction expected all transactions".to_owned(),
                        )
                    })?;
                return relay_submit_incoming_block(state, block, now_unix_sec);
            }
            state.pending_compact_blocks.insert(
                block_hash,
                PendingCompactBlock {
                    header: block.header,
                    tx_count: transactions.len(),
                    transactions,
                    missing_indexes: missing_indexes.clone(),
                },
            );
            Ok(vec![WireMessage::GetBlockTxn {
                block_hash,
                indexes: missing_indexes,
            }])
        }
        WireMessage::GetBlockTxn {
            block_hash,
            indexes,
        } => {
            if indexes.get(RELAY_MAX_GETBLOCKTXN_INDEXES).is_some() {
                return Err(relay_protocol_violation(
                    state,
                    peer_id,
                    now_unix_sec,
                    format!(
                        "getblocktxn indexes exceed limit: got={}, limit={}",
                        indexes.len(),
                        RELAY_MAX_GETBLOCKTXN_INDEXES
                    ),
                ));
            }
            let Some(block) = state.runtime.block_by_hash(&block_hash) else {
                return Ok(vec![WireMessage::NotFound {
                    items: vec![InventoryItem::Block(block_hash)],
                }]);
            };
            let mut transactions = Vec::<Transaction>::new();
            for index in indexes {
                let idx = index as usize;
                if idx >= block.transactions.len() {
                    return Err(NodeError::Runtime(format!(
                        "getblocktxn index {} out of bounds for block {} tx_count={}",
                        index,
                        block_hash,
                        block.transactions.len()
                    )));
                }
                transactions.push(block.transactions[idx].clone());
            }
            Ok(vec![WireMessage::BlockTxn {
                block_hash,
                transactions,
            }])
        }
        WireMessage::BlockTxn {
            block_hash,
            transactions,
        } => {
            let Some(mut pending) = state.pending_compact_blocks.remove(&block_hash) else {
                return Ok(Vec::new());
            };
            if pending.tx_count != pending.transactions.len() {
                return Err(NodeError::Runtime(format!(
                    "pending compact block {} has inconsistent transaction slots",
                    block_hash
                )));
            }
            if transactions.len() != pending.missing_indexes.len() {
                return Err(NodeError::Runtime(format!(
                    "blocktxn transaction count {} does not match expected missing indexes {} for {}",
                    transactions.len(),
                    pending.missing_indexes.len(),
                    block_hash
                )));
            }
            for (index, tx) in pending
                .missing_indexes
                .iter()
                .copied()
                .zip(transactions.into_iter())
            {
                let idx = index as usize;
                if idx >= pending.transactions.len() {
                    return Err(NodeError::Runtime(format!(
                        "blocktxn index {} out of bounds for {}",
                        index, block_hash
                    )));
                }
                pending.transactions[idx] = Some(tx);
            }
            let Some(block) =
                relay_try_build_block_from_compact(&pending.header, &pending.transactions)
            else {
                return Err(NodeError::Runtime(format!(
                    "blocktxn still missing transactions for {}",
                    block_hash
                )));
            };
            relay_submit_incoming_block(state, block, now_unix_sec)
        }
        WireMessage::Block { block } => {
            let out = relay_submit_incoming_block(state, block, now_unix_sec)?;
            relay_record_peer_tip_height(state, peer_id, state.runtime.tip_height());
            Ok(out)
        }
        WireMessage::NotFound { .. } => Ok(Vec::new()),
    }
}

fn push_inv_batches(out: &mut Vec<WireMessage>, items: Vec<InventoryItem>, max_inv_items: usize) {
    if items.is_empty() || max_inv_items == 0 {
        return;
    }
    for chunk in items.chunks(max_inv_items) {
        out.push(WireMessage::Inv {
            items: chunk.to_vec(),
        });
    }
}

fn relay_proactive_inventory_messages(
    state: &RelayServerState,
    last_tip_announced: &mut Option<Hash256>,
    announced_txids: &mut HashSet<Hash256>,
    max_inv_items: usize,
) -> Vec<WireMessage> {
    let mut out = Vec::<WireMessage>::new();
    let tip = state.runtime.tip_hash();
    if *last_tip_announced != Some(tip) {
        if let Some(previous_tip) = *last_tip_announced
            && previous_tip != tip
        {
            let locator = [previous_tip];
            let mut headers_by_hash = HashMap::new();
            for hash in state.runtime.block_hashes() {
                if let Some(header) = state.runtime.header_by_hash(hash) {
                    headers_by_hash.insert(*hash, header.clone());
                }
            }
            let headers = select_headers_for_peer(
                state.runtime.block_hashes(),
                &headers_by_hash,
                &locator,
                None,
                RELAY_MAX_HEADERS_PER_ANNOUNCEMENT,
            );
            if !headers.is_empty() {
                out.push(WireMessage::Headers { headers });
            }
        }
        push_inv_batches(&mut out, vec![InventoryItem::Block(tip)], max_inv_items);
        *last_tip_announced = Some(tip);
    }

    let current_txids = state.relay.mempool.txids_by_feerate_desc();
    let current_set = current_txids.iter().copied().collect::<HashSet<_>>();
    announced_txids.retain(|txid| current_set.contains(txid));
    let mut new_items = Vec::<InventoryItem>::new();
    for txid in current_txids {
        if announced_txids.insert(txid) {
            new_items.push(InventoryItem::Tx(txid));
        }
    }
    push_inv_batches(&mut out, new_items, max_inv_items);
    out
}

fn relay_mark_peer_replacement_rate_limited(
    state: &mut RelayServerState,
    peer_id: u64,
    now_unix_sec: u64,
) {
    let entry = state.peer_runtime_reputation.entry(peer_id).or_default();
    entry.replacement_rate_limited_total = entry.replacement_rate_limited_total.saturating_add(1);
    entry.last_replacement_rate_limited_unix_sec = now_unix_sec;
}

fn relay_take_peer_runtime_reputation(
    state: &mut RelayServerState,
    peer_id: u64,
) -> RuntimePeerReputation {
    state
        .peer_runtime_reputation
        .remove(&peer_id)
        .unwrap_or_default()
}

#[derive(Clone, Copy)]
enum RelayPeerSessionMode {
    Inbound,
    Outbound,
}

#[cfg_attr(not(test), allow(dead_code))]
fn load_relay_outbound_targets(
    peers_dir: &Path,
    network_name: &str,
) -> Result<Vec<String>, NodeError> {
    let (peers_db_path, legacy_txt_path) = peer_book_paths(peers_dir, network_name);
    let mut peer_book = match load_with_retry(10, 15, is_peer_book_db_lock_conflict, || {
        load_or_init_peer_book(network_name, &peers_db_path, &legacy_txt_path)
    })? {
        Some(book) => book,
        None => return Ok(Vec::new()),
    };
    sort_and_dedup_peer_book(&mut peer_book);
    Ok(peer_book
        .peers
        .into_iter()
        .map(|peer| peer.address)
        .collect::<Vec<_>>())
}

fn load_relay_known_peer_addresses(
    peers_dir: &Path,
    network_name: &str,
) -> Result<Vec<PeerAddress>, NodeError> {
    let (peers_db_path, legacy_txt_path) = peer_book_paths(peers_dir, network_name);
    let mut peer_book = match load_with_retry(10, 15, is_peer_book_db_lock_conflict, || {
        load_or_init_peer_book(network_name, &peers_db_path, &legacy_txt_path)
    })? {
        Some(book) => book,
        None => return Ok(Vec::new()),
    };
    sort_and_dedup_peer_book(&mut peer_book);
    let mut peers = peer_book
        .peers
        .into_iter()
        .filter(|record| !record.address.trim().is_empty())
        .map(|record| PeerAddress {
            address: record.address,
            services: 1,
            last_seen_unix_sec: record.last_seen_unix_sec,
        })
        .collect::<Vec<_>>();
    peers.sort_unstable_by(|a, b| a.address.cmp(&b.address));
    peers.truncate(2_000);
    Ok(peers)
}

fn load_relay_outbound_targets_selected(
    peers_dir: &Path,
    cfg: &ChainConfig,
    max_peers: usize,
    rotate_after_sec: u64,
    selector_identity: &str,
) -> Result<Vec<String>, NodeError> {
    let (peers_db_path, legacy_txt_path) = peer_book_paths(peers_dir, &cfg.network_id);
    let mut peer_book = match load_with_retry(10, 15, is_peer_book_db_lock_conflict, || {
        load_or_init_peer_book(&cfg.network_id, &peers_db_path, &legacy_txt_path)
    })? {
        Some(book) => book,
        None => return Ok(Vec::new()),
    };
    sort_and_dedup_peer_book(&mut peer_book);
    let now = current_unix_sec()?;
    let reputation_store = PeerReputationStore::from_peers_dir(peers_dir, &cfg.network_id);
    let reputation_weights =
        load_peer_reputation_weights(&reputation_store, now).unwrap_or_else(|err| {
            eprintln!(
                "warning: cannot load peer reputation from {}: {err}",
                reputation_store.path.display()
            );
            HashMap::new()
        });
    let network_policy = RelayNetworkPolicy::from_env();
    let mut candidates = Vec::<PeerCandidate>::new();
    let mut domain_candidates = Vec::<(String, u64, u32)>::new();
    for peer in peer_book.peers {
        if !relay_target_allowed_by_policy(&peer.address, &network_policy) {
            continue;
        }
        let reputation_penalty = reputation_weights.get(&peer.address).copied().unwrap_or(0);
        let failure_count = peer
            .ban_score
            .saturating_add(reputation_penalty)
            .saturating_mul(32)
            .saturating_add(relay_outbound_selector_jitter(
                selector_identity,
                &peer.address,
            ));
        if let Ok(addr) = peer.address.parse::<SocketAddr>() {
            candidates.push(PeerCandidate {
                addr,
                last_connected_unix_sec: peer.last_seen_unix_sec,
                failure_count,
            });
        } else {
            domain_candidates.push((peer.address, peer.last_seen_unix_sec, failure_count));
        }
    }
    if candidates.is_empty() && domain_candidates.is_empty() {
        return Ok(Vec::new());
    }
    let mut selected = select_outbound_peers(&candidates, max_peers, rotate_after_sec, now)
        .into_iter()
        .map(|addr| addr.to_string())
        .collect::<Vec<_>>();
    let selected_socket = selected
        .iter()
        .filter_map(|value| value.parse::<SocketAddr>().ok())
        .collect::<Vec<_>>();
    let bucket_secret = load_or_init_peer_bucket_secret(peers_dir, &cfg.network_id).unwrap_or_else(|err| {
        eprintln!(
            "warning: failed to load peer bucket secret for {}: {err}; using deterministic fallback",
            cfg.network_id
        );
        [0u8; 32]
    });
    selected = apply_bucket_cap_with_secret(
        selected_socket,
        cfg.p2p_max_outbound_per_bucket,
        &bucket_secret,
    )
    .into_iter()
    .map(|addr| addr.to_string())
    .collect::<Vec<_>>();

    domain_candidates.sort_unstable_by(|a, b| {
        a.2.cmp(&b.2)
            .then_with(|| b.1.cmp(&a.1))
            .then_with(|| a.0.cmp(&b.0))
    });
    let mut seen = selected.iter().cloned().collect::<HashSet<_>>();
    for (target, _, _) in domain_candidates {
        if selected.len() == max_peers {
            break;
        }
        if seen.insert(target.clone()) {
            selected.push(target);
        }
    }

    Ok(selected)
}

fn relay_outbound_selector_jitter(selector_identity: &str, candidate: &str) -> u32 {
    let mut mixed = String::with_capacity(selector_identity.len() + candidate.len() + 1);
    mixed.push_str(selector_identity);
    mixed.push('|');
    mixed.push_str(candidate);
    let hash = scam_core::hash::hash256(mixed.as_bytes());
    (u16::from_be_bytes([hash.0[0], hash.0[1]]) % 31) as u32
}

fn relay_target_matches_bind(bind_addr: &str, target: &str) -> bool {
    if bind_addr == target {
        return true;
    }
    let bind = match bind_addr.parse::<SocketAddr>() {
        Ok(bind) => bind,
        Err(_) => return false,
    };
    let peer = match target.parse::<SocketAddr>() {
        Ok(peer) => peer,
        Err(_) => return false,
    };
    if bind.port() != peer.port() {
        return false;
    }
    if bind.ip() == peer.ip() {
        return true;
    }
    bind.ip().is_unspecified() && peer.ip().is_loopback()
}

fn relay_disconnect_reason(err: &NodeError) -> &'static str {
    match err {
        NodeError::Chain(ChainError::UnknownParent { .. }) => "unknown-parent",
        NodeError::Transport(TransportError::InvalidMagic { .. }) => "invalid-magic",
        NodeError::Transport(TransportError::MessageTooLarge { .. }) => "message-too-large",
        NodeError::Transport(TransportError::UnexpectedMessage { .. }) => "unexpected-message",
        NodeError::Transport(TransportError::UnexpectedInventoryItem { .. }) => {
            "unexpected-inventory"
        }
        NodeError::Transport(TransportError::Wire(_)) => "wire-error",
        NodeError::Transport(TransportError::Io(io_err))
            if matches!(io_err.kind(), std::io::ErrorKind::TimedOut) =>
        {
            "io-timeout"
        }
        NodeError::Transport(TransportError::Io(io_err))
            if matches!(
                io_err.kind(),
                std::io::ErrorKind::ConnectionReset
                    | std::io::ErrorKind::ConnectionAborted
                    | std::io::ErrorKind::BrokenPipe
                    | std::io::ErrorKind::NotConnected
            ) =>
        {
            "io-closed"
        }
        NodeError::Transport(TransportError::Io(_)) => "io-error",
        NodeError::Runtime(msg) if msg.contains("network mismatch") => "network-mismatch",
        NodeError::Runtime(msg) if msg.contains("relay state mutex poisoned") => "state-poisoned",
        _ => "internal-error",
    }
}

fn relay_session_error_is_fatal(err: &NodeError) -> bool {
    matches!(
        relay_disconnect_reason(err),
        "internal-error" | "state-poisoned" | "network-mismatch"
    )
}

#[allow(clippy::too_many_arguments)]
#[cfg_attr(not(test), allow(dead_code))]
fn run_relay_outbound_worker(
    target: String,
    bind_addr: String,
    stop_flag: Arc<AtomicBool>,
    next_peer_id: Arc<AtomicU64>,
    state: Arc<Mutex<RelayServerState>>,
    active_peers: Arc<Mutex<usize>>,
    cfg: ChainConfig,
    runtime_db_path: PathBuf,
    mempool_db_path: PathBuf,
    max_inv_items: usize,
    read_limit: u32,
    read_timeout_sec: u64,
    write_timeout_sec: u64,
    redial_sec: u64,
    peer_reputation_store: Option<PeerReputationStore>,
) {
    if target.trim().is_empty() {
        return;
    }
    let anchor_store = peer_reputation_store
        .as_ref()
        .map(PeerAnchorStore::from_reputation_store);
    if relay_target_matches_bind(&bind_addr, &target) {
        return;
    }
    let redial_sec = redial_sec.max(1);
    let mut failure_streak = 0u32;
    relay_mark_outbound_worker_start(&state);
    let initial_delay = relay_outbound_initial_delay(&target, &bind_addr);
    if initial_delay > Duration::from_millis(0) {
        thread::sleep(initial_delay);
    }
    loop {
        if stop_flag.load(Ordering::Relaxed) {
            break;
        }
        let mut stream = match TcpStream::connect(&target) {
            Ok(stream) => stream,
            Err(err) => {
                eprintln!("warning: outbound relay connect to {target} failed: {err}");
                if let Some(store) = anchor_store.as_ref() {
                    let now_unix_sec = current_unix_sec().unwrap_or(0);
                    let _ = update_peer_anchor_store_attempt(store, &target, now_unix_sec, false);
                }
                failure_streak =
                    relay_outbound_next_failure_streak_from_connect_error(failure_streak, &err);
                let now_nanos = SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|duration| duration.as_nanos() as u64)
                    .unwrap_or(0);
                thread::sleep(relay_outbound_backoff_delay(
                    &target,
                    redial_sec,
                    failure_streak,
                    now_nanos,
                ));
                continue;
            }
        };
        if let Err(err) = configure_stream_timeouts_with_ops(
            |duration| stream.set_read_timeout(duration),
            |duration| stream.set_write_timeout(duration),
            Duration::from_secs(read_timeout_sec.max(1)),
            Duration::from_secs(write_timeout_sec.max(1)),
        ) {
            eprintln!("warning: outbound relay timeout config for {target} failed: {err}");
            failure_streak = failure_streak.saturating_add(1);
            let now_nanos = SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|duration| duration.as_nanos() as u64)
                .unwrap_or(0);
            thread::sleep(relay_outbound_backoff_delay(
                &target,
                redial_sec,
                failure_streak,
                now_nanos,
            ));
            continue;
        }
        let peer_id = next_peer_id
            .fetch_add(1, Ordering::Relaxed)
            .saturating_add(1);
        if let Err(err) = run_relay_peer_session(
            &mut stream,
            RelayPeerSessionMode::Outbound,
            peer_id,
            &state,
            &active_peers,
            &stop_flag,
            &cfg,
            &runtime_db_path,
            &mempool_db_path,
            max_inv_items,
            read_limit,
            Some(target.as_str()),
            peer_reputation_store.as_ref(),
        ) {
            if stop_flag.load(Ordering::Relaxed) {
                break;
            }
            eprintln!(
                "warning: outbound relay session with {target} ended: reason={} detail={err}",
                relay_disconnect_reason(&err)
            );
            if let Some(store) = anchor_store.as_ref() {
                let now_unix_sec = current_unix_sec().unwrap_or(0);
                let _ = update_peer_anchor_store_attempt(store, &target, now_unix_sec, false);
            }
            failure_streak =
                relay_outbound_next_failure_streak_from_session_error(failure_streak, &err);
        } else {
            failure_streak = 0;
        }
        let now_nanos = SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|duration| duration.as_nanos() as u64)
            .unwrap_or(0);
        thread::sleep(relay_outbound_backoff_delay(
            &target,
            redial_sec,
            failure_streak,
            now_nanos,
        ));
    }
}

#[allow(clippy::too_many_arguments)]
#[cfg_attr(not(test), allow(dead_code))]
fn run_relay_outbound_supervisor(
    stop_flag: Arc<AtomicBool>,
    peers_dir: PathBuf,
    bind_addr: String,
    next_peer_id: Arc<AtomicU64>,
    state: Arc<Mutex<RelayServerState>>,
    active_peers: Arc<Mutex<usize>>,
    cfg: ChainConfig,
    runtime_db_path: PathBuf,
    mempool_db_path: PathBuf,
    max_inv_items: usize,
    read_limit: u32,
    read_timeout_sec: u64,
    write_timeout_sec: u64,
    redial_sec: u64,
    rotate_after_sec: u64,
    peer_reputation_store: Option<PeerReputationStore>,
) {
    let redial_delay = Duration::from_secs(redial_sec.max(1));
    let max_outbound_peers = relay_outbound_max_peers();
    let spawn_burst = relay_outbound_spawn_burst();
    let mut workers = HashMap::<String, thread::JoinHandle<()>>::new();

    loop {
        if stop_flag.load(Ordering::Relaxed) {
            break;
        }
        let mut finished = Vec::<String>::new();
        for (target, handle) in &workers {
            if handle.is_finished() {
                finished.push(target.clone());
            }
        }
        for target in finished {
            if let Some(handle) = workers.remove(&target)
                && handle.join().is_err()
            {
                eprintln!("warning: outbound relay worker thread panicked for {target}");
            }
        }

        match load_relay_outbound_targets_selected(
            &peers_dir,
            &cfg,
            max_outbound_peers,
            rotate_after_sec,
            &bind_addr,
        ) {
            Ok(targets) => {
                let mut spawned_this_round = 0usize;
                for target in targets {
                    if workers.contains_key(&target) {
                        continue;
                    }
                    if relay_target_matches_bind(&bind_addr, &target) {
                        continue;
                    }
                    if spawned_this_round >= spawn_burst {
                        break;
                    }
                    let stop_clone = stop_flag.clone();
                    let next_peer_clone = next_peer_id.clone();
                    let state_clone = state.clone();
                    let active_clone = active_peers.clone();
                    let cfg_clone = cfg.clone();
                    let runtime_db_path_clone = runtime_db_path.clone();
                    let mempool_db_path_clone = mempool_db_path.clone();
                    let bind_addr_clone = bind_addr.clone();
                    let target_clone = target.clone();
                    let reputation_store_clone = peer_reputation_store.clone();
                    workers.insert(
                        target,
                        thread::spawn(move || {
                            run_relay_outbound_worker(
                                target_clone,
                                bind_addr_clone,
                                stop_clone,
                                next_peer_clone,
                                state_clone,
                                active_clone,
                                cfg_clone,
                                runtime_db_path_clone,
                                mempool_db_path_clone,
                                max_inv_items,
                                read_limit,
                                read_timeout_sec,
                                write_timeout_sec,
                                redial_sec,
                                reputation_store_clone,
                            );
                        }),
                    );
                    spawned_this_round = spawned_this_round.saturating_add(1);
                }
            }
            Err(err) => eprintln!(
                "warning: outbound relay peer-book reload failed ({}): {err}",
                peers_dir.display()
            ),
        }
        thread::sleep(redial_delay);
    }

    for (target, handle) in workers {
        if handle.join().is_err() {
            eprintln!("warning: outbound relay worker thread panicked for {target}");
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn run_relay_outbound_worker_async(
    target: String,
    bind_addr: String,
    stop_flag: Arc<AtomicBool>,
    next_peer_id: Arc<AtomicU64>,
    state: Arc<Mutex<RelayServerState>>,
    active_peers: Arc<Mutex<usize>>,
    cfg: ChainConfig,
    runtime_db_path: PathBuf,
    mempool_db_path: PathBuf,
    max_inv_items: usize,
    read_limit: u32,
    read_timeout_sec: u64,
    write_timeout_sec: u64,
    redial_sec: u64,
    peer_reputation_store: Option<PeerReputationStore>,
) {
    relay_mark_outbound_worker_start(&state);
    let anchor_store = peer_reputation_store
        .as_ref()
        .map(PeerAnchorStore::from_reputation_store);
    let network_policy = RelayNetworkPolicy::from_env();
    if target.trim().is_empty() {
        return;
    }
    if relay_target_matches_bind(&bind_addr, &target) {
        return;
    }
    let redial_sec = redial_sec.max(1);
    let mut failure_streak = 0u32;
    let initial_delay = relay_outbound_initial_delay(&target, &bind_addr);
    if initial_delay > Duration::from_millis(0) {
        sleep(initial_delay).await;
    }
    loop {
        if stop_flag.load(Ordering::Relaxed) {
            break;
        }
        let mut stream = match relay_connect_target_async(&target, &network_policy).await {
            Ok(stream) => stream,
            Err(err) => {
                eprintln!("warning: outbound relay connect to {target} failed: {err}");
                if let Some(store) = anchor_store.as_ref() {
                    let now_unix_sec = current_unix_sec().unwrap_or(0);
                    let _ = update_peer_anchor_store_attempt(store, &target, now_unix_sec, false);
                }
                failure_streak =
                    relay_outbound_next_failure_streak_from_connect_failure(failure_streak, &err);
                let now_nanos = SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|duration| duration.as_nanos() as u64)
                    .unwrap_or(0);
                sleep(relay_outbound_backoff_delay(
                    &target,
                    redial_sec,
                    failure_streak,
                    now_nanos,
                ))
                .await;
                continue;
            }
        };
        let peer_id = next_peer_id
            .fetch_add(1, Ordering::Relaxed)
            .saturating_add(1);
        if let Err(err) = run_relay_peer_session_async(
            &mut stream,
            RelayPeerSessionMode::Outbound,
            peer_id,
            &state,
            &active_peers,
            &stop_flag,
            &cfg,
            &runtime_db_path,
            &mempool_db_path,
            max_inv_items,
            read_limit,
            read_timeout_sec,
            write_timeout_sec,
            Some(target.as_str()),
            peer_reputation_store.as_ref(),
        )
        .await
        {
            if stop_flag.load(Ordering::Relaxed) {
                break;
            }
            eprintln!(
                "warning: outbound relay session with {target} ended: reason={} detail={err}",
                relay_disconnect_reason(&err)
            );
            if let Some(store) = anchor_store.as_ref() {
                let now_unix_sec = current_unix_sec().unwrap_or(0);
                let _ = update_peer_anchor_store_attempt(store, &target, now_unix_sec, false);
            }
            failure_streak =
                relay_outbound_next_failure_streak_from_session_error(failure_streak, &err);
        } else {
            failure_streak = 0;
        }
        let now_nanos = SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|duration| duration.as_nanos() as u64)
            .unwrap_or(0);
        sleep(relay_outbound_backoff_delay(
            &target,
            redial_sec,
            failure_streak,
            now_nanos,
        ))
        .await;
    }
}

fn relay_tx_diffusion_delay_for_message(message: &WireMessage) -> Duration {
    let base_ms = RELAY_TX_DIFFUSION_BASE_MS.load(Ordering::Relaxed);
    let max_ms = RELAY_TX_DIFFUSION_MAX_MS.load(Ordering::Relaxed);
    let Some(first_txid) = relay_first_tx_inv_txid(message) else {
        return Duration::from_millis(0);
    };
    let now_nanos = SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_nanos() as u64)
        .unwrap_or(0);
    let seed = relay_tx_diffusion_seed(now_nanos, first_txid);
    Duration::from_millis(relay_tx_diffusion_delay_ms_from_seed(base_ms, max_ms, seed))
}

fn relay_tx_diffusion_seed(now_nanos: u64, txid: Hash256) -> u64 {
    let mut input = [0u8; 40];
    input[..8].copy_from_slice(&now_nanos.to_be_bytes());
    input[8..].copy_from_slice(&txid.0);
    let mixed = scam_core::hash::hash256(&input);
    u64::from_be_bytes(mixed.0[..8].try_into().unwrap_or([0; 8]))
}

fn relay_tx_diffusion_delay_ms_from_seed(base_ms: u64, max_ms: u64, mut seed: u64) -> u64 {
    if base_ms == 0 {
        return 0;
    }
    if max_ms == 0 {
        return 0;
    }
    if max_ms < base_ms {
        return 0;
    }
    // SplitMix64 mixing to derive a stable pseudorandom value.
    seed = seed.wrapping_add(0x9E3779B97F4A7C15);
    let mut z = seed;
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
    z = z ^ (z >> 31);
    let unit = ((z >> 11) as f64) / ((1u64 << 53) as f64);
    let u = (1.0 - unit).clamp(1e-9, 1.0);
    let sampled = (-u.ln()).mul_add(base_ms as f64, 0.0).round() as u64;
    sampled.clamp(base_ms, max_ms)
}

fn relay_first_tx_inv_txid(message: &WireMessage) -> Option<Hash256> {
    match message {
        WireMessage::Inv { items } => items.iter().find_map(|item| match item {
            InventoryItem::Tx(txid) => Some(*txid),
            InventoryItem::Block(_) => None,
        }),
        _ => None,
    }
}

fn relay_socks5_proxy_endpoint(policy: &RelayNetworkPolicy) -> Option<String> {
    policy
        .socks5_proxy
        .as_ref()
        .map(|proxy| proxy.trim().to_owned())
        .filter(|proxy| !proxy.is_empty())
}

fn relay_target_is_anonymous_network(endpoint: &RelayTargetEndpoint) -> bool {
    matches!(
        relay_target_network(endpoint),
        RelayTargetNetwork::Onion | RelayTargetNetwork::I2p
    )
}

#[cfg_attr(not(test), allow(dead_code))]
fn relay_socks5_connect_request(endpoint: &RelayTargetEndpoint) -> Result<Vec<u8>, NodeError> {
    let mut request = Vec::<u8>::new();
    request.extend_from_slice(&[0x05, 0x01, 0x00]);
    if let Ok(ip) = endpoint.host.parse::<IpAddr>() {
        match ip {
            IpAddr::V4(v4) => {
                request.push(0x01);
                request.extend_from_slice(&v4.octets());
            }
            IpAddr::V6(v6) => {
                request.push(0x04);
                request.extend_from_slice(&v6.octets());
            }
        }
    } else {
        let host_bytes = endpoint.host.as_bytes();
        if host_bytes.is_empty() || host_bytes.len() > 255 {
            return Err(NodeError::Runtime(format!(
                "invalid SOCKS5 host length for {}",
                endpoint.host
            )));
        }
        request.push(0x03);
        request.push(host_bytes.len() as u8);
        request.extend_from_slice(host_bytes);
    }
    request.extend_from_slice(&endpoint.port.to_be_bytes());
    Ok(request)
}

fn relay_target_parse_or_err(target: &str) -> Result<RelayTargetEndpoint, NodeError> {
    parse_relay_target_endpoint(target).ok_or_else(|| {
        NodeError::Runtime(format!(
            "invalid outbound relay target '{target}': expected <ip:port> or <host:port>"
        ))
    })
}

fn relay_validate_target_against_policy(
    target: &RelayTargetEndpoint,
    policy: &RelayNetworkPolicy,
) -> Result<(), NodeError> {
    match relay_target_network(target) {
        RelayTargetNetwork::Clearnet => {}
        RelayTargetNetwork::Onion => {
            if !policy.allow_onion || policy.socks5_proxy.is_none() {
                return Err(NodeError::Runtime(format!(
                    "relay target {}:{} requires onion + SOCKS5 policy enablement",
                    target.host, target.port
                )));
            }
        }
        RelayTargetNetwork::I2p => {
            if !policy.allow_i2p || policy.socks5_proxy.is_none() {
                return Err(NodeError::Runtime(format!(
                    "relay target {}:{} requires i2p + SOCKS5 policy enablement",
                    target.host, target.port
                )));
            }
        }
        RelayTargetNetwork::Cjdns => {
            if !policy.allow_cjdns {
                return Err(NodeError::Runtime(format!(
                    "relay target {}:{} requires cjdns policy enablement",
                    target.host, target.port
                )));
            }
        }
    }
    Ok(())
}

async fn relay_connect_target_async(
    target: &str,
    policy: &RelayNetworkPolicy,
) -> Result<tokio::net::TcpStream, NodeError> {
    let endpoint = relay_target_parse_or_err(target)?;
    relay_validate_target_against_policy(&endpoint, policy)?;
    let proxy = relay_socks5_proxy_endpoint(policy);
    if relay_target_is_anonymous_network(&endpoint) {
        let Some(proxy_target) = proxy else {
            return Err(NodeError::Runtime(format!(
                "target {}:{} requires SOCKS5 proxy",
                endpoint.host, endpoint.port
            )));
        };
        return relay_connect_via_socks5_async(&proxy_target, &endpoint).await;
    }
    if relay_target_network(&endpoint) == RelayTargetNetwork::Cjdns
        && relay_socks5_proxy_endpoint(policy).is_some()
    {
        // CJDNS addresses are expected to be directly reachable; keep direct dial semantics.
        return tokio::net::TcpStream::connect(target).await.map_err(|e| {
            NodeError::Runtime(format!("outbound cjdns connect to {target} failed: {e}"))
        });
    }
    tokio::net::TcpStream::connect(target)
        .await
        .map_err(|e| NodeError::Runtime(format!("outbound relay connect to {target} failed: {e}")))
}

async fn relay_connect_via_socks5_async(
    proxy_target: &str,
    endpoint: &RelayTargetEndpoint,
) -> Result<tokio::net::TcpStream, NodeError> {
    if endpoint.host.is_empty() {
        return Err(NodeError::Runtime(
            "SOCKS5 endpoint host must not be empty".to_owned(),
        ));
    }
    if endpoint.host.len() > 255 {
        return Err(NodeError::Runtime(format!(
            "invalid SOCKS5 host length for {}",
            endpoint.host
        )));
    }
    let stream = Socks5Stream::connect(proxy_target, (endpoint.host.as_str(), endpoint.port))
        .await
        .map_err(|e| {
            NodeError::Runtime(format!(
                "outbound relay SOCKS5 connect to {}:{} via proxy {proxy_target} failed: {e}",
                endpoint.host, endpoint.port
            ))
        })?;
    Ok(stream.into_inner())
}

async fn run_relay_outbound_feeler_probe_async(
    target: String,
    bind_addr: String,
    cfg: ChainConfig,
    timeout_sec: u64,
    anchor_store: Option<PeerAnchorStore>,
) {
    if target.trim().is_empty() {
        return;
    }
    if relay_target_matches_bind(&bind_addr, &target) {
        return;
    }

    let deadline = Duration::from_secs(timeout_sec.max(1));
    let now_unix_sec = current_unix_sec().unwrap_or(0);
    let network_policy = RelayNetworkPolicy::from_env();
    let connect_result = timeout(
        deadline,
        relay_connect_target_async(&target, &network_policy),
    )
    .await;
    let Ok(Ok(mut stream)) = connect_result else {
        if let Some(store) = anchor_store {
            let _ = update_peer_anchor_store_attempt(&store, &target, now_unix_sec, false);
        }
        return;
    };

    let framing = FramingConfig::default();
    let consensus_id = consensus_fingerprint(&cfg);
    let local_hello = LocalHandshake {
        protocol_version: 1,
        network_id: cfg.network_id.clone(),
        consensus_fingerprint: consensus_id.clone(),
        user_agent: "scam-node/relay-feeler".to_owned(),
        start_height: 0,
    };
    let handshake = timeout(
        deadline,
        client_handshake_async(&mut stream, &framing, &local_hello),
    )
    .await;
    let success = matches!(
        handshake,
        Ok(Ok(remote))
            if remote.network_id == cfg.network_id
                && remote.consensus_fingerprint == consensus_id
    );
    if let Some(store) = anchor_store {
        let _ = update_peer_anchor_store_attempt(&store, &target, now_unix_sec, success);
    }
}

fn relay_outbound_feeler_due(now_unix_sec: u64, last_feeler_unix_sec: u64) -> bool {
    now_unix_sec
        .saturating_sub(last_feeler_unix_sec)
        .checked_sub(RELAY_OUTBOUND_FEELER_INTERVAL_SEC)
        .is_some()
}

fn relay_outbound_rotate_after_sec() -> u64 {
    env_nonzero_u64("SCAM_RELAY_OUTBOUND_ROTATE_AFTER_SEC")
        .unwrap_or(RELAY_OUTBOUND_ROTATE_AFTER_SEC)
}

fn relay_outbound_max_peers() -> usize {
    env_nonzero_usize("SCAM_RELAY_OUTBOUND_MAX_PEERS").unwrap_or(RELAY_OUTBOUND_MAX_PEERS)
}

fn relay_outbound_spawn_burst() -> usize {
    env_nonzero_usize("SCAM_RELAY_OUTBOUND_SPAWN_BURST")
        .unwrap_or(RELAY_OUTBOUND_SPAWN_BURST)
        .min(256)
}

fn relay_outbound_max_backoff_sec() -> u64 {
    env_nonzero_u64("SCAM_RELAY_OUTBOUND_MAX_BACKOFF_SEC").unwrap_or(RELAY_OUTBOUND_MAX_BACKOFF_SEC)
}

fn relay_outbound_initial_jitter_ms() -> u64 {
    env_opt("SCAM_RELAY_OUTBOUND_INITIAL_JITTER_MS")
        .and_then(|raw| raw.parse::<u64>().ok())
        .unwrap_or(RELAY_OUTBOUND_INITIAL_JITTER_MS)
        .min(60_000)
}

fn relay_outbound_initial_delay(target: &str, bind_addr: &str) -> Duration {
    let max_jitter_ms = relay_outbound_initial_jitter_ms();
    if max_jitter_ms == 0 {
        return Duration::from_millis(0);
    }
    let mut entropy = Vec::with_capacity(target.len().saturating_add(bind_addr.len() + 1));
    entropy.extend_from_slice(bind_addr.as_bytes());
    entropy.push(b'|');
    entropy.extend_from_slice(target.as_bytes());
    let mixed = scam_core::hash::hash256(&entropy);
    let jitter_ms =
        u16::from_be_bytes([mixed.0[0], mixed.0[1]]) as u64 % max_jitter_ms.saturating_add(1);
    Duration::from_millis(jitter_ms)
}

fn relay_headers_catchup_interval_sec() -> u64 {
    env_nonzero_u64("SCAM_RELAY_HEADERS_CATCHUP_INTERVAL_SEC")
        .unwrap_or(RELAY_HEADERS_CATCHUP_INTERVAL_SEC)
}

fn relay_headers_probe_interval_sec() -> u64 {
    env_nonzero_u64("SCAM_RELAY_HEADERS_PROBE_INTERVAL_SEC")
        .unwrap_or(RELAY_HEADERS_PROBE_INTERVAL_SEC)
}

fn relay_headers_inv_trigger_interval_sec() -> u64 {
    env_nonzero_u64("SCAM_RELAY_HEADERS_INV_TRIGGER_INTERVAL_SEC")
        .unwrap_or(RELAY_HEADERS_INV_TRIGGER_INTERVAL_SEC)
}

fn relay_headers_aggressive_lag_threshold() -> u64 {
    env_nonzero_u64("SCAM_RELAY_HEADERS_AGGRESSIVE_LAG_THRESHOLD")
        .unwrap_or(RELAY_HEADERS_AGGRESSIVE_LAG_THRESHOLD)
}

fn relay_headers_aggressive_interval_sec() -> u64 {
    env_nonzero_u64("SCAM_RELAY_HEADERS_AGGRESSIVE_INTERVAL_SEC")
        .unwrap_or(RELAY_HEADERS_AGGRESSIVE_INTERVAL_SEC)
}

fn relay_blocks_catchup_interval_sec() -> u64 {
    env_nonzero_u64("SCAM_RELAY_BLOCKS_CATCHUP_INTERVAL_SEC")
        .unwrap_or(RELAY_BLOCKS_CATCHUP_INTERVAL_SEC)
}

fn relay_blocks_aggressive_interval_sec() -> u64 {
    env_nonzero_u64("SCAM_RELAY_BLOCKS_AGGRESSIVE_INTERVAL_SEC")
        .unwrap_or(RELAY_BLOCKS_AGGRESSIVE_INTERVAL_SEC)
}

fn relay_discovery_refresh_sec() -> u64 {
    env_nonzero_u64("SCAM_RELAY_DISCOVERY_REFRESH_SEC").unwrap_or(RELAY_DISCOVERY_REFRESH_SEC)
}

fn relay_discovery_refresh_jitter_sec() -> u64 {
    env_opt("SCAM_RELAY_DISCOVERY_REFRESH_JITTER_SEC")
        .and_then(|raw| raw.parse::<u64>().ok())
        .unwrap_or(RELAY_DISCOVERY_REFRESH_JITTER_SEC)
        .min(300)
}

fn relay_discovery_refresh_due(
    now_unix_sec: u64,
    last_discovery_request_unix_sec: u64,
    peer_id: u64,
) -> bool {
    let base = relay_discovery_refresh_sec();
    let jitter_cap = relay_discovery_refresh_jitter_sec();
    let jitter = if jitter_cap == 0 {
        0
    } else {
        peer_id % jitter_cap.saturating_add(1)
    };
    now_unix_sec.saturating_sub(last_discovery_request_unix_sec) >= base.saturating_add(jitter)
}

fn tokio_worker_threads_from_env(env_key: &str, default_cap: usize) -> usize {
    if let Some(raw) = env_opt(env_key)
        && let Ok(parsed) = raw.parse::<usize>()
        && parsed > 0
    {
        return parsed;
    }
    std::thread::available_parallelism()
        .map(|n| n.get().min(default_cap.max(2)).max(2))
        .unwrap_or(2)
}

fn relay_tokio_worker_threads() -> usize {
    tokio_worker_threads_from_env("SCAM_RELAY_TOKIO_WORKER_THREADS", 8)
}

fn stratum_tokio_worker_threads() -> usize {
    tokio_worker_threads_from_env("SCAM_STRATUM_TOKIO_WORKER_THREADS", 4)
}

fn relay_handshake_timeout_sec(read_timeout_sec: u64) -> u64 {
    env_opt("SCAM_RELAY_HANDSHAKE_TIMEOUT_SEC")
        .and_then(|raw| raw.parse::<u64>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(read_timeout_sec.max(10))
}

fn relay_outbound_next_failure_streak(streak: u32) -> u32 {
    streak.saturating_add(1)
}

fn relay_outbound_next_failure_streak_from_connect_error(streak: u32, err: &std::io::Error) -> u32 {
    let next = relay_outbound_next_failure_streak(streak);
    if matches!(
        err.kind(),
        std::io::ErrorKind::TimedOut
            | std::io::ErrorKind::ConnectionRefused
            | std::io::ErrorKind::ConnectionReset
            | std::io::ErrorKind::ConnectionAborted
            | std::io::ErrorKind::BrokenPipe
            | std::io::ErrorKind::NotConnected
    ) {
        return next.min(3);
    }
    next
}

fn relay_outbound_next_failure_streak_from_connect_failure(streak: u32, err: &NodeError) -> u32 {
    let next = relay_outbound_next_failure_streak(streak);
    match err {
        NodeError::Transport(TransportError::Io(io_err)) => {
            relay_outbound_next_failure_streak_from_connect_error(streak, io_err)
        }
        NodeError::Runtime(msg) => {
            let lowered = msg.to_ascii_lowercase();
            if lowered.contains("connection refused")
                || lowered.contains("timed out")
                || lowered.contains("connection reset")
                || lowered.contains("connection aborted")
                || lowered.contains("broken pipe")
                || lowered.contains("not connected")
            {
                next.min(3)
            } else {
                next
            }
        }
        _ => next,
    }
}

fn relay_outbound_next_failure_streak_from_session_error(streak: u32, err: &NodeError) -> u32 {
    let next = relay_outbound_next_failure_streak(streak);
    match relay_disconnect_reason(err) {
        "io-timeout" | "io-closed" => next.min(3),
        _ => next,
    }
}

fn relay_outbound_backoff_delay(
    target: &str,
    redial_sec: u64,
    failure_streak: u32,
    now_nanos: u64,
) -> Duration {
    let base = redial_sec.max(1);
    let max_backoff = relay_outbound_max_backoff_sec().max(base);
    let shift = failure_streak.saturating_sub(1).min(10);
    let exp_factor = 1u64 << shift;
    let delay_sec = base.saturating_mul(exp_factor).min(max_backoff);
    let mut entropy = Vec::with_capacity(target.len() + 8);
    entropy.extend_from_slice(target.as_bytes());
    entropy.extend_from_slice(&now_nanos.to_be_bytes());
    let mixed = scam_core::hash::hash256(&entropy);
    let jitter_ms = u16::from_be_bytes([mixed.0[0], mixed.0[1]]) as u64 % 300;
    Duration::from_millis(delay_sec.saturating_mul(1_000).saturating_add(jitter_ms))
}

fn relay_inbound_accept_window_sec() -> u64 {
    env_nonzero_u64("SCAM_RELAY_INBOUND_ACCEPT_WINDOW_SEC")
        .unwrap_or(RELAY_INBOUND_ACCEPT_WINDOW_SEC)
}

fn relay_inbound_accept_base_max_per_ip(max_active_sessions: usize) -> usize {
    env_nonzero_usize("SCAM_RELAY_INBOUND_ACCEPT_MAX_PER_IP").unwrap_or_else(|| {
        RELAY_INBOUND_ACCEPT_MAX_PER_IP
            .max(max_active_sessions.saturating_mul(4))
            .max(64)
    })
}

fn relay_inbound_accept_loopback_multiplier() -> usize {
    env_nonzero_usize("SCAM_RELAY_INBOUND_ACCEPT_LOOPBACK_MULTIPLIER")
        .unwrap_or(RELAY_INBOUND_ACCEPT_LOOPBACK_MULTIPLIER)
}

fn relay_inbound_accept_limit_for_ip(
    ip: IpAddr,
    base_limit: usize,
    max_active_sessions: usize,
) -> usize {
    if ip.is_loopback() {
        let multiplier = relay_inbound_accept_loopback_multiplier();
        return base_limit
            .saturating_mul(multiplier)
            .max(max_active_sessions.saturating_mul(multiplier))
            .max(128);
    }
    base_limit
}

fn relay_outbound_worker_rotation_due(
    now_unix_sec: u64,
    worker_started_unix_sec: u64,
    rotate_after_sec: u64,
) -> bool {
    now_unix_sec
        .saturating_sub(worker_started_unix_sec)
        .checked_sub(rotate_after_sec.max(1))
        .is_some()
}

#[allow(clippy::too_many_arguments)]
async fn run_relay_outbound_supervisor_async(
    stop_flag: Arc<AtomicBool>,
    peers_dir: PathBuf,
    bind_addr: String,
    next_peer_id: Arc<AtomicU64>,
    state: Arc<Mutex<RelayServerState>>,
    active_peers: Arc<Mutex<usize>>,
    cfg: ChainConfig,
    runtime_db_path: PathBuf,
    mempool_db_path: PathBuf,
    max_inv_items: usize,
    read_limit: u32,
    read_timeout_sec: u64,
    write_timeout_sec: u64,
    redial_sec: u64,
    rotate_after_sec: u64,
    peer_reputation_store: Option<PeerReputationStore>,
) {
    let redial_delay = Duration::from_secs(redial_sec.max(1));
    let max_outbound_peers = relay_outbound_max_peers();
    let spawn_burst = relay_outbound_spawn_burst();
    relay_mark_outbound_supervisor_start(&state);
    let mut workers = HashMap::<String, tokio::task::JoinHandle<()>>::new();
    let mut worker_targets = HashSet::<String>::new();
    let mut worker_started_unix_sec = HashMap::<String, u64>::new();
    let anchor_store = peer_reputation_store
        .as_ref()
        .map(PeerAnchorStore::from_reputation_store);
    let mut last_feeler_unix_sec = current_unix_sec().unwrap_or(0);

    loop {
        if stop_flag.load(Ordering::Relaxed) {
            break;
        }

        let mut finished = Vec::<String>::new();
        for (target, handle) in &workers {
            if handle.is_finished() {
                finished.push(target.clone());
            }
        }
        for target in finished {
            if let Some(handle) = workers.remove(&target) {
                match handle.await {
                    Ok(()) => {}
                    Err(err) => eprintln!("warning: outbound relay worker task failed: {err}"),
                }
                worker_targets.remove(&target);
                worker_started_unix_sec.remove(&target);
            }
        }

        let selected_targets = match load_relay_outbound_targets_selected(
            &peers_dir,
            &cfg,
            max_outbound_peers,
            rotate_after_sec,
            &bind_addr,
        ) {
            Ok(targets) => targets,
            Err(err) => {
                eprintln!(
                    "warning: outbound relay peer-book reload failed ({}): {err}",
                    peers_dir.display()
                );
                sleep(redial_delay).await;
                continue;
            }
        };
        let anchor_targets = match anchor_store.as_ref() {
            Some(store) => match load_peer_anchor_targets(store, RELAY_OUTBOUND_ANCHOR_TARGETS) {
                Ok(anchors) => anchors,
                Err(err) => {
                    eprintln!(
                        "warning: outbound relay anchor load failed ({}): {err}",
                        store.path.display()
                    );
                    Vec::new()
                }
            },
            None => Vec::new(),
        };
        let targets = merge_outbound_targets(anchor_targets, selected_targets, max_outbound_peers);

        let now_unix_sec = current_unix_sec().unwrap_or(0);
        if let Some((stale_target, _)) = worker_started_unix_sec
            .iter()
            .find(|(_, started_at)| {
                relay_outbound_worker_rotation_due(now_unix_sec, **started_at, rotate_after_sec)
            })
            .map(|(target, started_at)| (target.clone(), *started_at))
            && let Some(handle) = workers.remove(&stale_target)
        {
            handle.abort();
            let _ = handle.await;
            worker_targets.remove(&stale_target);
            worker_started_unix_sec.remove(&stale_target);
        }

        let mut spawned_this_round = 0usize;
        for target in targets {
            if worker_targets.contains(&target) {
                continue;
            }
            if relay_target_matches_bind(&bind_addr, &target) {
                continue;
            }
            if spawned_this_round >= spawn_burst {
                break;
            }
            let target_key = target.clone();
            worker_targets.insert(target_key.clone());
            let stop_clone = stop_flag.clone();
            let next_peer_clone = next_peer_id.clone();
            let state_clone = state.clone();
            let active_clone = active_peers.clone();
            let cfg_clone = cfg.clone();
            let runtime_db_path_clone = runtime_db_path.clone();
            let mempool_db_path_clone = mempool_db_path.clone();
            let bind_addr_clone = bind_addr.clone();
            let reputation_store_clone = peer_reputation_store.clone();
            workers.insert(
                target_key.clone(),
                tokio::spawn(async move {
                    run_relay_outbound_worker_async(
                        target,
                        bind_addr_clone,
                        stop_clone,
                        next_peer_clone,
                        state_clone,
                        active_clone,
                        cfg_clone,
                        runtime_db_path_clone,
                        mempool_db_path_clone,
                        max_inv_items,
                        read_limit,
                        read_timeout_sec,
                        write_timeout_sec,
                        redial_sec,
                        reputation_store_clone,
                    )
                    .await
                }),
            );
            worker_started_unix_sec.insert(target_key, now_unix_sec);
            spawned_this_round = spawned_this_round.saturating_add(1);
        }

        if relay_outbound_feeler_due(now_unix_sec, last_feeler_unix_sec) {
            let mut excluded = worker_targets.clone();
            excluded.insert(bind_addr.clone());
            match load_relay_outbound_feeler_target(&peers_dir, &cfg, &bind_addr, &excluded) {
                Ok(Some(feeler_target)) => {
                    last_feeler_unix_sec = now_unix_sec;
                    let bind_addr_clone = bind_addr.clone();
                    let cfg_clone = cfg.clone();
                    let anchor_store_clone = anchor_store.clone();
                    tokio::spawn(async move {
                        run_relay_outbound_feeler_probe_async(
                            feeler_target,
                            bind_addr_clone,
                            cfg_clone,
                            RELAY_OUTBOUND_FEELER_TIMEOUT_SEC,
                            anchor_store_clone,
                        )
                        .await;
                    });
                }
                Ok(None) => {}
                Err(err) => {
                    eprintln!(
                        "warning: outbound relay feeler candidate load failed ({}): {err}",
                        peers_dir.display()
                    );
                }
            }
        }

        sleep(redial_delay).await;
    }

    for (_target, worker) in workers {
        worker.abort();
        let _ = worker.await;
    }
}

fn relay_runtime_or_mempool_changed(
    tip_before: Hash256,
    tip_after: Hash256,
    mempool_before: u64,
    mempool_after: u64,
) -> (bool, bool) {
    (tip_after != tip_before, mempool_after != mempool_before)
}

fn relay_max_active_sessions(max_clients: u32) -> usize {
    if max_clients > 0 {
        max_clients as usize
    } else {
        512
    }
}

#[allow(clippy::too_many_arguments)]
#[cfg_attr(not(test), allow(dead_code))]
fn run_relay_peer_session<IO: Read + Write>(
    stream: &mut IO,
    mode: RelayPeerSessionMode,
    peer_id: u64,
    state: &Arc<Mutex<RelayServerState>>,
    active: &Arc<Mutex<usize>>,
    stop_flag: &Arc<AtomicBool>,
    cfg: &ChainConfig,
    runtime_db_path: &Path,
    mempool_db_path: &Path,
    max_inv_items: usize,
    read_limit: u32,
    peer_address: Option<&str>,
    peer_reputation_store: Option<&PeerReputationStore>,
) -> Result<(), NodeError> {
    let anchor_store = peer_reputation_store.map(PeerAnchorStore::from_reputation_store);
    let result = (|| -> Result<(), NodeError> {
        {
            let mut active_guard = active
                .lock()
                .map_err(|_| NodeError::Runtime("relay active peer mutex poisoned".to_owned()))?;
            *active_guard = active_guard.saturating_add(1);
        }

        let framing = FramingConfig::default();
        let consensus_id = consensus_fingerprint(cfg);
        let local_start_height = {
            let guard = state
                .lock()
                .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
            guard.runtime.tip_height()
        };
        let local_hello = LocalHandshake {
            protocol_version: 1,
            network_id: cfg.network_id.clone(),
            consensus_fingerprint: consensus_id.clone(),
            user_agent: "scam-node/relay-serve".to_owned(),
            start_height: local_start_height,
        };
        let remote = match mode {
            RelayPeerSessionMode::Inbound => server_handshake(stream, &framing, &local_hello)?,
            RelayPeerSessionMode::Outbound => client_handshake(stream, &framing, &local_hello)?,
        };
        ensure_relay_peer_network(&cfg.network_id, &remote.network_id)?;
        ensure_relay_peer_consensus(&consensus_id, &remote.consensus_fingerprint)?;
        if matches!(mode, RelayPeerSessionMode::Outbound)
            && let (Some(store), Some(address)) = (anchor_store.as_ref(), peer_address)
        {
            let now_unix_sec = current_unix_sec().unwrap_or(0);
            let _ = update_peer_anchor_store_attempt(store, address, now_unix_sec, true);
        }
        let send_recon = {
            let mut guard = state
                .lock()
                .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
            guard.relay.gossip.connect_peer(peer_id);
            guard.peer_compact_pref.insert(peer_id, false);
            relay_record_peer_tip_height(&mut guard, peer_id, remote.start_height);
            guard.peer_runtime_reputation.entry(peer_id).or_default();
            if matches!(mode, RelayPeerSessionMode::Outbound)
                && let Some(address) = peer_address
            {
                relay_register_connected_peer_address(
                    &mut guard,
                    address,
                    current_unix_sec().unwrap_or(0),
                );
            }
            guard.relay.gossip.build_send_recon(peer_id)?
        };

        let mut startup = vec![send_recon];
        if matches!(mode, RelayPeerSessionMode::Outbound) {
            let locator = {
                let guard = state
                    .lock()
                    .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                build_block_locator(guard.runtime.block_hashes())
            };
            startup.extend([
                WireMessage::SendCmpct {
                    high_bandwidth: true,
                    version: 1,
                },
                WireMessage::GetAddr,
                WireMessage::GetHeaders {
                    locator: locator.clone(),
                    stop: None,
                },
                WireMessage::GetBlocks {
                    locator,
                    stop: None,
                },
            ]);
        }
        let startup_sent = relay_send_messages_until_closed(stream, &startup, &framing)?;
        if relay_should_abort_after_startup_send(mode, startup_sent) {
            return Ok(());
        }

        let mut seen = 0u32;
        let mut runtime_db_seen_mtime = runtime_db_mtime(runtime_db_path);
        let mut mempool_db_seen_mtime = mempool_db_mtime(mempool_db_path);
        let mut last_tip_announced = None::<Hash256>;
        let mut announced_txids = HashSet::<Hash256>::new();
        let mut timeout_streak = 0u32;
        let mut last_discovery_request_unix_sec = current_unix_sec().unwrap_or(0);
        loop {
            if stop_flag.load(Ordering::Relaxed) {
                break;
            }
            if should_stop_after_seen_messages(read_limit, seen) {
                break;
            }
            let now_for_periodic = current_unix_sec().unwrap_or(0);
            let periodic_outbound = {
                let mut guard = state
                    .lock()
                    .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                let _ = refresh_relay_runtime_from_db_if_changed(
                    cfg,
                    &mut guard,
                    runtime_db_path,
                    &mut runtime_db_seen_mtime,
                    now_for_periodic,
                )?;
                refresh_mempool_from_db_if_changed(
                    cfg,
                    &mut guard.relay,
                    mempool_db_path,
                    &mut mempool_db_seen_mtime,
                )?;
                let mut periodic = relay_proactive_inventory_messages(
                    &guard,
                    &mut last_tip_announced,
                    &mut announced_txids,
                    max_inv_items,
                );
                let recon = guard
                    .relay
                    .gossip
                    .maybe_start_reconciliation(peer_id, now_for_periodic)?;
                periodic.extend(relay_gossip_outbound_for_peer(&guard, peer_id, recon));
                if let Some(get_headers) =
                    relay_maybe_request_headers_catchup(&mut guard, peer_id, now_for_periodic)
                {
                    periodic.push(get_headers);
                }
                if let Some(get_blocks) =
                    relay_maybe_request_blocks_catchup(&mut guard, peer_id, now_for_periodic)
                {
                    periodic.push(get_blocks);
                }
                if matches!(mode, RelayPeerSessionMode::Outbound)
                    && relay_discovery_refresh_due(
                        now_for_periodic,
                        last_discovery_request_unix_sec,
                        peer_id,
                    )
                {
                    periodic.push(WireMessage::GetAddr);
                    last_discovery_request_unix_sec = now_for_periodic;
                }
                relay_messages_for_peer(&guard, peer_id, periodic)
            };
            if relay_has_periodic_outbound(&periodic_outbound)
                && !relay_send_messages_until_closed(stream, &periodic_outbound, &framing)?
            {
                break;
            }

            let inbound = match map_relay_read_result(read_message(stream, &framing))? {
                RelayReadOutcome::Timeout => {
                    timeout_streak = timeout_streak.saturating_add(1);
                    if relay_timeout_streak_reached_limit(timeout_streak) {
                        break;
                    }
                    if stop_flag.load(Ordering::Relaxed) {
                        break;
                    }
                    continue;
                }
                RelayReadOutcome::Closed => break,
                RelayReadOutcome::Message(message) => {
                    timeout_streak = 0;
                    message
                }
            };

            seen = seen.saturating_add(1);
            let now = current_unix_sec()?;
            let (outbound, runtime_changed, mempool_changed) = {
                let mut guard = state
                    .lock()
                    .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                let tip_before = guard.runtime.tip_hash();
                let mempool_before = guard.relay.mempool.revision();
                let outbound = process_relay_wire_message_with_archive(
                    &mut guard,
                    peer_id,
                    inbound,
                    now,
                    Some(runtime_db_path),
                )?;
                let outbound = relay_messages_for_peer(&guard, peer_id, outbound);
                let tip_after = guard.runtime.tip_hash();
                let mempool_after = guard.relay.mempool.revision();
                let (runtime_changed, mempool_changed) = relay_runtime_or_mempool_changed(
                    tip_before,
                    tip_after,
                    mempool_before,
                    mempool_after,
                );
                (outbound, runtime_changed, mempool_changed)
            };
            if runtime_changed {
                let guard = state
                    .lock()
                    .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                persist_runtime_db_with_retry(&guard.runtime, runtime_db_path, 80, 25)?;
                runtime_db_seen_mtime = runtime_db_mtime(runtime_db_path);
            }
            if mempool_changed {
                let guard = state
                    .lock()
                    .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                persist_mempool_db_with_retry(cfg, &guard.relay.mempool, mempool_db_path, 80, 25)?;
                mempool_db_seen_mtime = mempool_db_mtime(mempool_db_path);
            }
            if let Err(err) = relay_flush_pending_peer_book_updates(state) {
                eprintln!("warning: cannot flush discovered peer addresses: {err}");
            }
            match relay_send_messages_until_closed(stream, &outbound, &framing)? {
                true => {}
                false => break,
            }
            let banned = {
                let guard = state
                    .lock()
                    .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                guard.relay.gossip.is_banned(peer_id)
            };
            if banned {
                break;
            }
        }
        if let Err(err) = relay_flush_pending_peer_book_updates(state) {
            eprintln!("warning: cannot flush discovered peer addresses: {err}");
        }
        Ok(())
    })();

    let mut peer_reputation_delta = RuntimePeerReputation::default();
    if let Ok(mut guard) = state.lock() {
        peer_reputation_delta = relay_take_peer_runtime_reputation(&mut guard, peer_id);
        guard.relay.gossip.disconnect_peer(peer_id);
        guard.peer_compact_pref.remove(&peer_id);
        relay_forget_peer_tip_height(&mut guard, peer_id);
    }
    if let Ok(mut active_guard) = active.lock() {
        *active_guard = active_guard.saturating_sub(1);
    }
    if result.is_err()
        && matches!(mode, RelayPeerSessionMode::Outbound)
        && let (Some(store), Some(address)) = (anchor_store.as_ref(), peer_address)
    {
        let now_unix_sec = current_unix_sec().unwrap_or(0);
        let _ = update_peer_anchor_store_attempt(store, address, now_unix_sec, false);
    }
    if let (Some(store), Some(address)) = (peer_reputation_store, peer_address)
        && should_persist_peer_reputation(peer_reputation_delta)
    {
        let now_unix_sec = current_unix_sec()
            .unwrap_or(peer_reputation_delta.last_replacement_rate_limited_unix_sec);
        if let Err(err) =
            update_peer_reputation_store(store, address, peer_reputation_delta, now_unix_sec)
        {
            eprintln!("warning: failed to persist peer reputation for {address}: {err}");
        }
    }
    result
}

#[allow(clippy::too_many_arguments)]
async fn run_relay_peer_session_async<S: AsyncRead + AsyncWrite + Unpin>(
    stream: &mut S,
    mode: RelayPeerSessionMode,
    peer_id: u64,
    state: &Arc<Mutex<RelayServerState>>,
    active: &Arc<Mutex<usize>>,
    stop_flag: &Arc<AtomicBool>,
    cfg: &ChainConfig,
    runtime_db_path: &Path,
    mempool_db_path: &Path,
    max_inv_items: usize,
    read_limit: u32,
    read_timeout_sec: u64,
    write_timeout_sec: u64,
    peer_address: Option<&str>,
    peer_reputation_store: Option<&PeerReputationStore>,
) -> Result<(), NodeError> {
    let anchor_store = peer_reputation_store.map(PeerAnchorStore::from_reputation_store);
    {
        let mut active_guard = active
            .lock()
            .map_err(|_| NodeError::Runtime("relay active peer mutex poisoned".to_owned()))?;
        *active_guard = active_guard.saturating_add(1);
    }

    let session_result = async {
        let framing = FramingConfig::default();
        let consensus_id = consensus_fingerprint(cfg);
        let local_start_height = {
            let guard = state
                .lock()
                .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
            guard.runtime.tip_height()
        };
        let local_hello = LocalHandshake {
            protocol_version: 1,
            network_id: cfg.network_id.clone(),
            consensus_fingerprint: consensus_id.clone(),
            user_agent: "scam-node/relay-serve".to_owned(),
            start_height: local_start_height,
        };
        let remote = relay_handshake_async_with_timeout(
            stream,
            mode,
            &framing,
            &local_hello,
            read_timeout_sec,
        )
        .await?;
        ensure_relay_peer_network(&cfg.network_id, &remote.network_id)?;
        ensure_relay_peer_consensus(&consensus_id, &remote.consensus_fingerprint)?;
        if matches!(mode, RelayPeerSessionMode::Outbound)
            && let (Some(store), Some(address)) = (anchor_store.as_ref(), peer_address)
        {
            let now_unix_sec = current_unix_sec().unwrap_or(0);
            let _ = update_peer_anchor_store_attempt(store, address, now_unix_sec, true);
        }
        let send_recon = {
            let mut guard = state
                .lock()
                .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
            guard.relay.gossip.connect_peer(peer_id);
            guard.peer_compact_pref.insert(peer_id, false);
            relay_record_peer_tip_height(&mut guard, peer_id, remote.start_height);
            guard.peer_runtime_reputation.entry(peer_id).or_default();
            if matches!(mode, RelayPeerSessionMode::Outbound)
                && let Some(address) = peer_address
            {
                relay_register_connected_peer_address(
                    &mut guard,
                    address,
                    current_unix_sec().unwrap_or(0),
                );
            }
            guard.relay.gossip.build_send_recon(peer_id)?
        };

        let mut first_sync = vec![send_recon];
        if matches!(mode, RelayPeerSessionMode::Outbound) {
            let locator = {
                let guard = state
                    .lock()
                    .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                build_block_locator(guard.runtime.block_hashes())
            };
            first_sync.extend([
                WireMessage::SendCmpct {
                    high_bandwidth: true,
                    version: 1,
                },
                WireMessage::GetAddr,
                WireMessage::GetHeaders {
                    locator: locator.clone(),
                    stop: None,
                },
                WireMessage::GetBlocks {
                    locator,
                    stop: None,
                },
            ]);
        }
        let startup_sent = relay_send_messages_until_closed_async(
            stream,
            &first_sync,
            &framing,
            write_timeout_sec,
        )
        .await?;
        if relay_should_abort_after_startup_send(mode, startup_sent) {
            return Ok(());
        }

        let mut seen = 0u32;
        let mut runtime_db_seen_mtime = runtime_db_mtime(runtime_db_path);
        let mut mempool_db_seen_mtime = mempool_db_mtime(mempool_db_path);
        let mut last_tip_announced = None::<Hash256>;
        let mut announced_txids = HashSet::<Hash256>::new();
        let mut timeout_streak = 0u32;
        let read_poll_interval_ms = relay_async_read_poll_interval_ms(read_timeout_sec);
        let timeout_streak_limit =
            relay_async_timeout_streak_limit(read_timeout_sec, read_poll_interval_ms);
        let mut last_discovery_request_unix_sec = current_unix_sec().unwrap_or(0);
        loop {
            if stop_flag.load(Ordering::Relaxed) {
                break;
            }
            if should_stop_after_seen_messages(read_limit, seen) {
                break;
            }
            let now_for_periodic = current_unix_sec().unwrap_or(0);
            let periodic_outbound = {
                let mut guard = state
                    .lock()
                    .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                let _ = refresh_relay_runtime_from_db_if_changed(
                    cfg,
                    &mut guard,
                    runtime_db_path,
                    &mut runtime_db_seen_mtime,
                    now_for_periodic,
                )?;
                refresh_mempool_from_db_if_changed(
                    cfg,
                    &mut guard.relay,
                    mempool_db_path,
                    &mut mempool_db_seen_mtime,
                )?;
                let mut periodic = relay_proactive_inventory_messages(
                    &guard,
                    &mut last_tip_announced,
                    &mut announced_txids,
                    max_inv_items,
                );
                let recon = guard
                    .relay
                    .gossip
                    .maybe_start_reconciliation(peer_id, now_for_periodic)?;
                periodic.extend(relay_gossip_outbound_for_peer(&guard, peer_id, recon));
                if let Some(get_headers) =
                    relay_maybe_request_headers_catchup(&mut guard, peer_id, now_for_periodic)
                {
                    periodic.push(get_headers);
                }
                if let Some(get_blocks) =
                    relay_maybe_request_blocks_catchup(&mut guard, peer_id, now_for_periodic)
                {
                    periodic.push(get_blocks);
                }
                if matches!(mode, RelayPeerSessionMode::Outbound)
                    && relay_discovery_refresh_due(
                        now_for_periodic,
                        last_discovery_request_unix_sec,
                        peer_id,
                    )
                {
                    periodic.push(WireMessage::GetAddr);
                    last_discovery_request_unix_sec = now_for_periodic;
                }
                relay_messages_for_peer(&guard, peer_id, periodic)
            };
            if relay_has_periodic_outbound(&periodic_outbound)
                && !relay_send_messages_until_closed_async(
                    stream,
                    &periodic_outbound,
                    &framing,
                    write_timeout_sec,
                )
                .await?
            {
                break;
            }

            let inbound = match relay_read_with_timeout_async(
                stream,
                &framing,
                read_timeout_sec,
                read_poll_interval_ms,
            )
            .await?
            {
                RelayReadOutcome::Timeout => {
                    timeout_streak = timeout_streak.saturating_add(1);
                    if timeout_streak >= timeout_streak_limit {
                        break;
                    }
                    if stop_flag.load(Ordering::Relaxed) {
                        break;
                    }
                    continue;
                }
                RelayReadOutcome::Closed => break,
                RelayReadOutcome::Message(message) => {
                    timeout_streak = 0;
                    message
                }
            };

            seen = seen.saturating_add(1);
            let now = current_unix_sec()?;
            let (outbound, runtime_changed, mempool_changed) = match inbound {
                WireMessage::GetData { items } => {
                    let outbound =
                        process_relay_getdata_with_archive_async(state, items, runtime_db_path)
                            .await?;
                    let outbound = {
                        let guard = state.lock().map_err(|_| {
                            NodeError::Runtime("relay state mutex poisoned".to_owned())
                        })?;
                        relay_messages_for_peer(&guard, peer_id, outbound)
                    };
                    (outbound, false, false)
                }
                inbound => {
                    let mut guard = state
                        .lock()
                        .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                    let tip_before = guard.runtime.tip_hash();
                    let mempool_before = guard.relay.mempool.revision();
                    let outbound = process_relay_wire_message_with_archive(
                        &mut guard,
                        peer_id,
                        inbound,
                        now,
                        Some(runtime_db_path),
                    )?;
                    let outbound = relay_messages_for_peer(&guard, peer_id, outbound);
                    let tip_after = guard.runtime.tip_hash();
                    let mempool_after = guard.relay.mempool.revision();
                    let (runtime_changed, mempool_changed) = relay_runtime_or_mempool_changed(
                        tip_before,
                        tip_after,
                        mempool_before,
                        mempool_after,
                    );
                    (outbound, runtime_changed, mempool_changed)
                }
            };

            if runtime_changed {
                let guard = state
                    .lock()
                    .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                persist_runtime_db_with_retry(&guard.runtime, runtime_db_path, 80, 25)?;
                runtime_db_seen_mtime = runtime_db_mtime(runtime_db_path);
            }
            if mempool_changed {
                let guard = state
                    .lock()
                    .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                persist_mempool_db_with_retry(cfg, &guard.relay.mempool, mempool_db_path, 80, 25)?;
                mempool_db_seen_mtime = mempool_db_mtime(mempool_db_path);
            }
            if let Err(err) = relay_flush_pending_peer_book_updates(state) {
                eprintln!("warning: cannot flush discovered peer addresses: {err}");
            }
            if !relay_send_messages_until_closed_async(
                stream,
                &outbound,
                &framing,
                write_timeout_sec,
            )
            .await?
            {
                break;
            }
            let banned = {
                let guard = state
                    .lock()
                    .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
                guard.relay.gossip.is_banned(peer_id)
            };
            if banned {
                break;
            }
        }

        if let Err(err) = relay_flush_pending_peer_book_updates(state) {
            eprintln!("warning: cannot flush discovered peer addresses: {err}");
        }
        Ok(())
    }
    .await;

    let mut peer_reputation_delta = RuntimePeerReputation::default();
    if let Ok(mut guard) = state.lock() {
        peer_reputation_delta = relay_take_peer_runtime_reputation(&mut guard, peer_id);
        guard.relay.gossip.disconnect_peer(peer_id);
        guard.peer_compact_pref.remove(&peer_id);
        relay_forget_peer_tip_height(&mut guard, peer_id);
    }
    if let Ok(mut active_guard) = active.lock() {
        *active_guard = active_guard.saturating_sub(1);
    }
    if session_result.is_err()
        && matches!(mode, RelayPeerSessionMode::Outbound)
        && let (Some(store), Some(address)) = (anchor_store.as_ref(), peer_address)
    {
        let now_unix_sec = current_unix_sec().unwrap_or(0);
        let _ = update_peer_anchor_store_attempt(store, address, now_unix_sec, false);
    }
    if let (Some(store), Some(address)) = (peer_reputation_store, peer_address)
        && should_persist_peer_reputation(peer_reputation_delta)
    {
        let now_unix_sec = current_unix_sec()
            .unwrap_or(peer_reputation_delta.last_replacement_rate_limited_unix_sec);
        if let Err(err) =
            update_peer_reputation_store(store, address, peer_reputation_delta, now_unix_sec)
        {
            eprintln!("warning: failed to persist peer reputation for {address}: {err}");
        }
    }
    session_result
}

async fn relay_handshake_async_with_timeout<S: AsyncRead + AsyncWrite + Unpin>(
    stream: &mut S,
    mode: RelayPeerSessionMode,
    framing: &FramingConfig,
    local_hello: &LocalHandshake,
    timeout_sec: u64,
) -> Result<RemoteHandshake, NodeError> {
    let handshake_timeout_sec = relay_handshake_timeout_sec(timeout_sec).max(1);
    let deadline = Duration::from_secs(handshake_timeout_sec);
    let handshake = async {
        match mode {
            RelayPeerSessionMode::Inbound => {
                server_handshake_async(stream, framing, local_hello).await
            }
            RelayPeerSessionMode::Outbound => {
                client_handshake_async(stream, framing, local_hello).await
            }
        }
    };
    match timeout(deadline, handshake).await {
        Ok(Ok(remote)) => Ok(remote),
        Ok(Err(err)) => Err(NodeError::Transport(err)),
        Err(_) => Err(NodeError::Transport(TransportError::Io(
            std::io::Error::new(
                std::io::ErrorKind::TimedOut,
                format!("relay handshake timed out after {}s", handshake_timeout_sec),
            ),
        ))),
    }
}

fn run_relay_serve(args: RelayServeArgs) -> Result<(), NodeError> {
    let config_path = args
        .config
        .unwrap_or_else(|| PathBuf::from(format!("config/{}.toml", args.network.as_str())));
    let cfg = load_chain_config(&config_path)?;
    let runtime_db_path = args
        .runtime_db
        .unwrap_or_else(|| default_runtime_db_path(args.network));
    let mempool_db_path = default_mempool_db_path(&runtime_db_path);
    let (runtime, source) = load_runtime_from_db_or_genesis(&cfg, &runtime_db_path)?;

    let max_inv_items = args.max_inv_items.unwrap_or(cfg.p2p_max_inv_items).max(1);
    let ban_threshold = args.ban_threshold.unwrap_or(cfg.p2p_ban_threshold).max(1);
    let read_timeout_sec = args.read_timeout_sec.max(1);
    let write_timeout_sec = args.write_timeout_sec.max(1);
    let replacement = ReplacementRateLimit {
        window_sec: args
            .replacement_window_sec
            .unwrap_or(cfg.p2p_replacement_window_sec)
            .max(1),
        max_replacements: args
            .replacement_max_per_peer
            .unwrap_or(cfg.p2p_replacement_max_per_peer)
            .max(1),
        penalty: args
            .replacement_penalty
            .unwrap_or(cfg.p2p_replacement_penalty)
            .max(1),
    };
    let tx_diffusion_base_ms = env_opt("SCAM_RELAY_TX_DIFFUSION_BASE_MS")
        .and_then(|raw| raw.parse::<u64>().ok())
        .unwrap_or(0);
    let tx_diffusion_max_ms = env_opt("SCAM_RELAY_TX_DIFFUSION_MAX_MS")
        .and_then(|raw| raw.parse::<u64>().ok())
        .unwrap_or(0);
    RELAY_TX_DIFFUSION_BASE_MS.store(tx_diffusion_base_ms, Ordering::Relaxed);
    RELAY_TX_DIFFUSION_MAX_MS.store(tx_diffusion_max_ms, Ordering::Relaxed);
    let network_policy = RelayNetworkPolicy::from_env();
    let mut startup_mempool = load_mempool_from_db_or_empty(&cfg, &mempool_db_path)?;
    let removed_confirmed_startup = cleanup_mempool_against_chain(&runtime, &mut startup_mempool);
    if should_persist_startup_mempool_cleanup(removed_confirmed_startup) {
        persist_mempool_db_with_retry(&cfg, &startup_mempool, &mempool_db_path, 80, 25)?;
        println!(
            "Mempool startup cleanup: removed {} already-confirmed tx(s)",
            removed_confirmed_startup
        );
    }
    let relay = RelayAdmissionState {
        mempool: startup_mempool,
        orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)?,
        gossip: GossipEngine::with_limits_and_replacement(
            max_inv_items,
            ban_threshold,
            replacement,
        )?,
    };
    let peer_book_store = PeerBookStore::from_peers_dir(&args.peers_dir, &cfg.network_id);
    let state = Arc::new(Mutex::new(
        RelayServerState::new(runtime, relay).with_peer_book_store(peer_book_store.clone()),
    ));
    let active_peers = Arc::new(Mutex::new(0usize));
    let next_peer_id = Arc::new(AtomicU64::new(0));
    match load_relay_known_peer_addresses(&args.peers_dir, &cfg.network_id) {
        Ok(known) => {
            if let Ok(mut guard) = state.lock() {
                guard.known_peer_addresses = known;
            }
        }
        Err(err) => {
            eprintln!(
                "warning: cannot preload known peer addresses from {}: {err}",
                args.peers_dir.display()
            );
        }
    }
    println!(
        "P2P relay serving on {} network={} source={} (tx mempool admission active)",
        args.bind, cfg.network_id, source
    );
    println!("Mempool DB: {}", mempool_db_path.display());
    println!(
        "Peer book: {}",
        args.peers_dir
            .join(format!("{}.redb", cfg.network_id))
            .display()
    );
    let peer_anchor_store = PeerAnchorStore::from_peers_dir(&args.peers_dir, &cfg.network_id);
    println!("Peer anchors: {}", peer_anchor_store.path.display());
    println!(
        "Relay policy: max_inv_items={} ban_threshold={} replacement_window={}s replacement_max_per_peer={} replacement_penalty={}",
        max_inv_items,
        ban_threshold,
        replacement.window_sec,
        replacement.max_replacements,
        replacement.penalty
    );
    println!(
        "Relay tx diffusion: base={}ms max={}ms",
        tx_diffusion_base_ms, tx_diffusion_max_ms
    );
    println!(
        "Relay anonymizing networks: onion={} i2p={} cjdns={} socks5_proxy={}",
        network_policy.allow_onion,
        network_policy.allow_i2p,
        network_policy.allow_cjdns,
        network_policy.socks5_proxy.as_deref().unwrap_or("disabled")
    );
    println!("I/O model: async tokio");
    {
        let guard = state
            .lock()
            .map_err(|_| NodeError::Runtime("relay state mutex poisoned".to_owned()))?;
        persist_mempool_db_with_retry(&cfg, &guard.relay.mempool, &mempool_db_path, 20, 25)?;
    }

    let stop_flag = Arc::new(AtomicBool::new(false));
    let peer_reputation_store =
        PeerReputationStore::from_peers_dir(&args.peers_dir, &cfg.network_id);
    let worker_threads = relay_tokio_worker_threads();
    let runtime = TokioRuntimeBuilder::new_multi_thread()
        .enable_all()
        .worker_threads(worker_threads)
        .build()
        .map_err(|e| NodeError::Runtime(format!("relay async runtime init failed: {e}")))?;

    let bind = args.bind.clone();
    let peers_dir = args.peers_dir.clone();
    let telemetry_out = args.telemetry_out.clone();
    let telemetry_every_sec = args.telemetry_every_sec.max(1);
    let outbound_connect = args.outbound_connect;
    let outbound_redial_sec = args.outbound_redial_sec.max(1);
    let outbound_rotate_after_sec = relay_outbound_rotate_after_sec();
    let outbound_max_peers = relay_outbound_max_peers();
    let max_clients = args.max_clients;
    let read_limit = args.max_messages_per_peer;
    let peer_reputation_store_for_runtime = peer_reputation_store.clone();
    let max_active_sessions = relay_max_active_sessions(max_clients);
    let inbound_accept_window_sec = relay_inbound_accept_window_sec();
    let inbound_accept_base_max_per_ip =
        relay_inbound_accept_base_max_per_ip(max_active_sessions.max(1));
    println!("Max concurrent sessions: {}", max_active_sessions);
    println!(
        "Inbound accept limiter: window={}s base_max_per_ip={} loopback_multiplier={}",
        inbound_accept_window_sec,
        inbound_accept_base_max_per_ip,
        relay_inbound_accept_loopback_multiplier()
    );
    println!("Tokio worker threads: {}", worker_threads);
    if outbound_connect {
        println!(
            "Outbound relay dialer: enabled (redial={}s rotate={}s max_peers={} max_backoff={}s)",
            outbound_redial_sec,
            outbound_rotate_after_sec,
            outbound_max_peers,
            relay_outbound_max_backoff_sec()
        );
    } else {
        println!("Outbound relay dialer: disabled");
    }

    runtime.block_on(async move {
        let listener = tokio::net::TcpListener::bind(&bind)
            .await
            .map_err(|e| NodeError::Runtime(format!("relay bind failed on {bind}: {e}")))?;
        let permits = Arc::new(Semaphore::new(max_active_sessions.max(1)));
        let mut workers = JoinSet::<Result<(), NodeError>>::new();
        let mut first_error = None::<NodeError>;

        let telemetry_handle = if let Some(path) = telemetry_out {
            let state_clone = state.clone();
            let active_clone = active_peers.clone();
            let stop_clone = stop_flag.clone();
            Some(tokio::spawn(async move {
                while relay_telemetry_thread_running(&stop_clone) {
                    sleep(Duration::from_secs(telemetry_every_sec)).await;
                    let now = match current_unix_sec() {
                        Ok(now) => now,
                        Err(_) => continue,
                    };
                    let peers = match active_clone.lock() {
                        Ok(guard) => *guard,
                        Err(_) => continue,
                    };
                    let snapshot = match state_clone.lock() {
                        Ok(guard) => relay_server_snapshot(&guard, peers, now),
                        Err(_) => continue,
                    };
                    let _ = append_relay_telemetry_snapshot(&path, &snapshot);
                }
            }))
        } else {
            None
        };

        let outbound_handle = if outbound_connect {
            let stop_clone = stop_flag.clone();
            let next_peer_clone = next_peer_id.clone();
            let state_clone = state.clone();
            let active_clone = active_peers.clone();
            let cfg_clone = cfg.clone();
            let runtime_db_path_clone = runtime_db_path.clone();
            let mempool_db_path_clone = mempool_db_path.clone();
            let peer_reputation_store_clone = peer_reputation_store_for_runtime.clone();
            Some(tokio::spawn(async move {
                run_relay_outbound_supervisor_async(
                    stop_clone,
                    peers_dir,
                    bind,
                    next_peer_clone,
                    state_clone,
                    active_clone,
                    cfg_clone,
                    runtime_db_path_clone,
                    mempool_db_path_clone,
                    max_inv_items,
                    read_limit,
                    read_timeout_sec,
                    write_timeout_sec,
                    outbound_redial_sec,
                    outbound_rotate_after_sec,
                    Some(peer_reputation_store_clone),
                )
                .await;
            }))
        } else {
            None
        };

        let mut served = 0u32;
        let mut inbound_accept_history = HashMap::<IpAddr, VecDeque<u64>>::new();
        loop {
            let accepted = listener
                .accept()
                .await
                .map_err(|e| NodeError::Runtime(format!("relay accept failed: {e}")));
            let (mut stream, peer_addr) = match accepted {
                Ok(accepted) => accepted,
                Err(err) => {
                    first_error = Some(err);
                    break;
                }
            };
            let now_unix_sec = current_unix_sec().unwrap_or(0);
            let per_ip_limit = relay_inbound_accept_limit_for_ip(
                peer_addr.ip(),
                inbound_accept_base_max_per_ip,
                max_active_sessions.max(1),
            );
            if relay_inbound_accept_rate_limited(
                &mut inbound_accept_history,
                peer_addr.ip(),
                now_unix_sec,
                inbound_accept_window_sec,
                per_ip_limit,
            ) {
                eprintln!(
                    "warning: dropping inbound relay connection from {} (accept-rate limit: {} per {}s)",
                    peer_addr.ip(),
                    per_ip_limit,
                    inbound_accept_window_sec
                );
                drop(stream);
                continue;
            }

            let permit = match permits.clone().try_acquire_owned() {
                Ok(permit) => permit,
                Err(_) => {
                    eprintln!(
                        "warning: dropping inbound relay connection (active={} max_active={})",
                        active_peers.lock().map(|g| *g).unwrap_or_default(),
                        max_active_sessions
                    );
                    drop(stream);
                    continue;
                }
            };

            let peer_id = next_peer_id
                .fetch_add(1, Ordering::Relaxed)
                .saturating_add(1);
            let state_clone = state.clone();
            let active_clone = active_peers.clone();
            let cfg_clone = cfg.clone();
            let runtime_db_path_clone = runtime_db_path.clone();
            let mempool_db_path_clone = mempool_db_path.clone();
            let stop_clone = stop_flag.clone();
            let max_inv_items_clone = max_inv_items;
            let peer_reputation_store_clone = peer_reputation_store_for_runtime.clone();
            let peer_addr_string = peer_addr.to_string();
            workers.spawn(async move {
                let _permit = permit;
                run_relay_peer_session_async(
                    &mut stream,
                    RelayPeerSessionMode::Inbound,
                    peer_id,
                    &state_clone,
                    &active_clone,
                    &stop_clone,
                    &cfg_clone,
                    &runtime_db_path_clone,
                    &mempool_db_path_clone,
                    max_inv_items_clone,
                    read_limit,
                    read_timeout_sec,
                    write_timeout_sec,
                    Some(peer_addr_string.as_str()),
                    Some(&peer_reputation_store_clone),
                )
                .await
            });

            served = served.saturating_add(1);
            if max_requests_limit_hit(max_clients, served) {
                break;
            }
        }

        if first_error.is_some() {
            // Accept-loop failure should trigger early shutdown for active sessions.
            stop_flag.store(true, Ordering::Relaxed);
        }

        while let Some(join_result) = workers.join_next().await {
            match join_result {
                Ok(Ok(())) => {}
                Ok(Err(err)) => {
                    if relay_session_error_is_fatal(&err) {
                        if first_error.is_none() {
                            first_error = Some(err);
                        }
                    } else {
                        eprintln!(
                            "warning: relay worker session ended: reason={} detail={err}",
                            relay_disconnect_reason(&err)
                        );
                    }
                }
                Err(err) => {
                    if first_error.is_none() {
                        first_error = Some(NodeError::Runtime(format!(
                            "relay worker task failed: {err}"
                        )));
                    }
                }
            }
        }
        // Normal max-clients exit should let workers finish organically first,
        // then stop background telemetry/outbound tasks.
        stop_flag.store(true, Ordering::Relaxed);
        if let Some(handle) = outbound_handle
            && let Err(err) = handle.await
            && first_error.is_none()
        {
            first_error = Some(NodeError::Runtime(format!(
                "outbound relay supervisor task failed: {err}"
            )));
        }
        if let Some(handle) = telemetry_handle {
            let _ = handle.await;
        }
        if let Some(err) = first_error {
            Err(err)
        } else {
            Ok(())
        }
    })
}

fn run_reindex_runtime(args: ReindexRuntimeArgs) -> Result<(), NodeError> {
    let config_path = args
        .config
        .unwrap_or_else(|| PathBuf::from(format!("config/{}.toml", args.network.as_str())));
    let cfg = load_chain_config(&config_path)?;
    let runtime_db_path = args
        .runtime_db
        .unwrap_or_else(|| default_runtime_db_path(args.network));

    if !runtime_db_path.exists() {
        return Err(NodeError::Runtime(format!(
            "runtime db does not exist: {}",
            runtime_db_path.display()
        )));
    }

    let archive = load_chain_archive_db(&runtime_db_path)?;
    if archive.network_id != cfg.network_id {
        return Err(NodeError::Runtime(format!(
            "runtime db network mismatch: db='{}', config='{}'",
            archive.network_id, cfg.network_id
        )));
    }

    let runtime = ChainRuntime::from_ordered_blocks(cfg.clone(), archive.blocks_by_height)?;
    persist_runtime_db(&runtime, &runtime_db_path)?;

    println!("Runtime reindex complete");
    println!("Network: {}", cfg.network_id);
    println!("Config: {}", config_path.display());
    println!("Runtime DB: {}", runtime_db_path.display());
    println!("Tip height: {}", runtime.tip_height());
    println!("Tip hash: {}", runtime.tip_hash());
    println!("UTXO count: {}", runtime.utxo_len());
    Ok(())
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct SoakSummary {
    rounds: u32,
    blocks_mined: u64,
    start_height: u64,
    end_height: u64,
    elapsed_sec: u64,
}

#[derive(Clone, Copy, Debug)]
struct SoakExecutionParams {
    rounds: u32,
    blocks_per_round: u32,
    interval_sec: u64,
    max_nonce: u64,
    miner_key_hash: [u8; 20],
    sleep_per_round_sec: u64,
}

const SOAK_FLOW_MNEMONIC: &str =
    "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about";

fn derive_soak_flow_keys() -> Result<(WalletKey, [u8; 20]), NodeError> {
    let mnemonic = WalletMnemonic::parse(SOAK_FLOW_MNEMONIC)?;
    let seed = mnemonic.to_seed("");
    let sender_key = derive_wallet_key(&seed, 0, 0)?;
    let recipient_key = derive_wallet_key(&seed, 0, 1)?;
    let recipient_key_hash20 = scam_core::hash160_blake3(&recipient_key.pubkey_compressed());
    Ok((sender_key, recipient_key_hash20))
}

struct RelayAdmissionState {
    mempool: Mempool,
    orphan_pool: OrphanPool,
    gossip: GossipEngine,
}

#[derive(Clone, Debug, Serialize)]
struct SoakTelemetrySnapshot {
    round: u32,
    unix_sec: u64,
    tip_height: u64,
    mempool_len: usize,
    orphan_pool_len: usize,
    mempool_accepted_total: u64,
    mempool_replaced_total: u64,
    mempool_removed_by_replacement_total: u64,
    mempool_evicted_total: u64,
    mempool_removed_by_block_total: u64,
    mempool_rejected_conflict_total: u64,
    orphan_accepted_total: u64,
    orphan_evicted_total: u64,
    orphan_expired_total: u64,
    orphan_promoted_total: u64,
    gossip_announced_txs_total: u64,
    gossip_removed_txs_total: u64,
    gossip_inbound_replacement_events_total: u64,
    gossip_replacement_rate_limited_total: u64,
}

fn append_soak_telemetry_snapshot(
    path: &Path,
    snapshot: &SoakTelemetrySnapshot,
) -> Result<(), NodeError> {
    if let Some(parent) = nonempty_parent_dir(path) {
        fs::create_dir_all(parent).map_err(|e| {
            NodeError::Runtime(format!(
                "cannot create telemetry directory {}: {e}",
                parent.display()
            ))
        })?;
    }
    let mut file = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)
        .map_err(|e| {
            NodeError::Runtime(format!(
                "cannot open telemetry output {}: {e}",
                path.display()
            ))
        })?;
    let line = serde_json::to_string(snapshot)
        .map_err(|e| NodeError::Runtime(format!("cannot encode telemetry json: {e}")))?;
    file.write_all(line.as_bytes()).map_err(|e| {
        NodeError::Runtime(format!(
            "cannot write telemetry output {}: {e}",
            path.display()
        ))
    })?;
    file.write_all(b"\n").map_err(|e| {
        NodeError::Runtime(format!(
            "cannot finalize telemetry output {}: {e}",
            path.display()
        ))
    })?;
    Ok(())
}

fn detect_missing_outpoints(
    runtime: &ChainRuntime,
    mempool: &Mempool,
    tx: &Transaction,
) -> Vec<OutPoint> {
    let mut missing = HashSet::<OutPoint>::new();
    for input in &tx.inputs {
        if runtime.utxo_set().contains_key(&input.prev_out) {
            continue;
        }
        if mempool.contains(&input.prev_out.txid) {
            continue;
        }
        missing.insert(input.prev_out.clone());
    }
    missing.into_iter().collect::<Vec<_>>()
}

fn admit_peer_tx_into_relay(
    relay: &mut RelayAdmissionState,
    runtime: &ChainRuntime,
    peer_id: u64,
    tx: Transaction,
    fee: u64,
    now_unix_sec: u64,
) -> Result<(), NodeError> {
    let mut pending = VecDeque::<(Transaction, u64)>::new();
    pending.push_back((tx, fee));

    while let Some((candidate_tx, candidate_fee)) = pending.pop_front() {
        let missing = detect_missing_outpoints(runtime, &relay.mempool, &candidate_tx);
        let effective_fee = tx_fee_from_known_prevouts(runtime, &relay.mempool, &candidate_tx)
            .unwrap_or(candidate_fee);
        if !missing.is_empty() {
            let _ = relay
                .orphan_pool
                .insert(candidate_tx, effective_fee, missing, now_unix_sec)?;
            continue;
        }

        let outcome = relay.mempool.insert_with_fee(candidate_tx, effective_fee)?;
        let inserted_txid = match outcome {
            InsertOutcome::Accepted { txid } => Some(txid),
            InsertOutcome::Replaced { inserted, .. } => Some(inserted),
            InsertOutcome::AcceptedWithEviction { inserted, .. } => Some(inserted),
            InsertOutcome::AlreadyPresent { .. }
            | InsertOutcome::RejectedConflictInsufficientFee { .. }
            | InsertOutcome::RejectedConflictInsufficientFeerate { .. } => None,
        };

        let delta = outcome.inventory_delta();
        if has_inventory_delta_changes(delta.announced_txids.len(), delta.removed_txids.len()) {
            let announced_txs = delta
                .announced_txids
                .iter()
                .filter_map(|txid| relay.mempool.get(txid).cloned())
                .collect::<Vec<_>>();
            let _ = relay.gossip.apply_mempool_inventory_delta_from_peer(
                peer_id,
                announced_txs,
                &delta.removed_txids,
                now_unix_sec,
            )?;
        }

        if let Some(txid) = inserted_txid
            && let Some(inserted_tx) = relay.mempool.get(&txid).cloned()
        {
            for vout in 0..inserted_tx.outputs.len() {
                let outpoint = OutPoint {
                    txid,
                    vout: vout as u32,
                };
                let ready = relay.orphan_pool.resolve_outpoint(&outpoint);
                for ready_orphan in ready {
                    pending.push_back((ready_orphan.tx, ready_orphan.fee));
                }
            }
        }
    }

    Ok(())
}

fn execute_soak_rounds<F>(
    runtime: &mut ChainRuntime,
    cfg: &ChainConfig,
    params: SoakExecutionParams,
    mut on_round_end: F,
) -> Result<SoakSummary, NodeError>
where
    F: FnMut(u32, &mut ChainRuntime) -> Result<(), NodeError>,
{
    let start_height = runtime.tip_height();
    let start = Instant::now();

    for round in 1..=params.rounds {
        let mining_params = MiningLoopParams {
            count: params.blocks_per_round,
            interval_sec: params.interval_sec,
            max_nonce: params.max_nonce,
            subsidy: cfg.block_subsidy,
            miner_key_hash: params.miner_key_hash,
            label_prefix: "soak",
            print_each: false,
        };
        mine_blocks_on_runtime(runtime, &mining_params)?;
        on_round_end(round, runtime)?;
        if params.sleep_per_round_sec != 0 {
            thread::sleep(Duration::from_secs(params.sleep_per_round_sec));
        }
    }

    let end_height = runtime.tip_height();
    Ok(SoakSummary {
        rounds: params.rounds,
        blocks_mined: end_height.saturating_sub(start_height),
        start_height,
        end_height,
        elapsed_sec: start.elapsed().as_secs(),
    })
}

fn run_soak(args: SoakArgs) -> Result<(), NodeError> {
    let config_path = args
        .config
        .unwrap_or_else(|| PathBuf::from(format!("config/{}.toml", args.network.as_str())));
    let cfg = load_chain_config(&config_path)?;
    let runtime_db_path = args
        .runtime_db
        .unwrap_or_else(|| default_runtime_db_path(args.network));
    let (mut runtime, source) = load_runtime_from_db_or_genesis(&cfg, &runtime_db_path)?;

    if args.txs_per_round != 0 && args.tx_amount == 0 {
        return Err(NodeError::Runtime(
            "tx_amount must be > 0 when txs_per_round is enabled".to_owned(),
        ));
    }
    if args.telemetry_every_rounds == 0 {
        return Err(NodeError::Runtime(
            "telemetry_every_rounds must be > 0".to_owned(),
        ));
    }
    if args.simulated_peers == 0 {
        return Err(NodeError::Runtime("simulated_peers must be > 0".to_owned()));
    }
    if args.replacement_window_sec == 0 {
        return Err(NodeError::Runtime(
            "replacement_window_sec must be > 0".to_owned(),
        ));
    }
    if args.replacement_max_per_peer == 0 {
        return Err(NodeError::Runtime(
            "replacement_max_per_peer must be > 0".to_owned(),
        ));
    }
    if args.replacement_penalty == 0 {
        return Err(NodeError::Runtime(
            "replacement_penalty must be > 0".to_owned(),
        ));
    }

    if let Some(path) = args.telemetry_out.as_ref() {
        if let Some(parent) = nonempty_parent_dir(path) {
            fs::create_dir_all(parent).map_err(|e| {
                NodeError::Runtime(format!(
                    "cannot create telemetry parent {}: {e}",
                    parent.display()
                ))
            })?;
        }
        fs::write(path, b"").map_err(|e| {
            NodeError::Runtime(format!(
                "cannot initialize telemetry output {}: {e}",
                path.display()
            ))
        })?;
    }

    let tx_flow_enabled = is_tx_flow_enabled(args.txs_per_round);
    let (soak_sender_key, soak_recipient_key_hash20, miner_key_hash) = if tx_flow_enabled {
        let (sender_key, recipient_key_hash20) = derive_soak_flow_keys()?;
        let miner_key_hash = scam_core::hash160_blake3(&sender_key.pubkey_compressed());
        (Some(sender_key), recipient_key_hash20, miner_key_hash)
    } else {
        (None, [0u8; 20], cfg.genesis_reward_key_hash20()?)
    };

    let mut relay_state = if tx_flow_enabled {
        let mut gossip = GossipEngine::with_limits_and_replacement(
            256,
            100,
            ReplacementRateLimit {
                window_sec: args.replacement_window_sec,
                max_replacements: args.replacement_max_per_peer,
                penalty: args.replacement_penalty,
            },
        )?;
        for peer_id in 1..=args.simulated_peers {
            gossip.connect_peer(peer_id as u64);
        }
        Some(RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)?,
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)?,
            gossip,
        })
    } else {
        None
    };

    let mut tx_blocks_mined = 0u64;
    let mut txs_included = 0u64;
    let mut rate_limited_events = 0u64;
    let persist_every_rounds = args.persist_every_rounds.max(1);
    let execution = SoakExecutionParams {
        rounds: args.rounds,
        blocks_per_round: args.blocks_per_round,
        interval_sec: args.interval_sec,
        max_nonce: args.max_nonce,
        miner_key_hash,
        sleep_per_round_sec: args.sleep_per_round_sec,
    };
    let summary = execute_soak_rounds(&mut runtime, &cfg, execution, |round, runtime| {
        let now_unix_sec = current_unix_sec()?;
        if tx_flow_enabled {
            let sender_key = soak_sender_key
                .as_ref()
                .expect("tx flow enabled means sender key is present");
            for tx_index in 0..args.txs_per_round {
                let recipient_key_hash20 =
                    soak_recipient_key_hash(tx_index, soak_recipient_key_hash20, miner_key_hash);
                let tx_fee = soak_tx_fee_for_index(args.tx_fee, tx_index);
                match build_signed_transfer_tx(
                    runtime,
                    &cfg.network_id,
                    sender_key,
                    recipient_key_hash20,
                    args.tx_amount,
                    tx_fee,
                ) {
                    Ok(signed) => {
                        let peer_id = soak_peer_id_for_round(round, tx_index, args.simulated_peers);
                        match admit_peer_tx_into_relay(
                            relay_state
                                .as_mut()
                                .expect("relay state must exist when tx flow is enabled"),
                            runtime,
                            peer_id,
                            signed.tx,
                            tx_fee,
                            now_unix_sec,
                        ) {
                            Ok(()) => {}
                            Err(NodeError::Gossip(GossipError::ReplacementRateLimited {
                                ..
                            })) => {
                                rate_limited_events = rate_limited_events.saturating_add(1);
                            }
                            Err(NodeError::Mempool(
                                MempoolError::MultipleConflicts { .. }
                                | MempoolError::ReplacementTooManyDescendants { .. }
                                | MempoolError::FeeTooLow { .. }
                                | MempoolError::Full { .. },
                            )) => {}
                            Err(other) => return Err(other),
                        }
                    }
                    Err(NodeError::InsufficientFunds { .. }) => break,
                    Err(other) => return Err(other),
                }
            }

            let relay = relay_state
                .as_mut()
                .expect("relay state must exist when tx flow is enabled");
            let ranked = relay.mempool.txids_by_feerate_desc();
            let mut round_txs = Vec::<Transaction>::new();
            for txid in ranked.into_iter().take(args.txs_per_round as usize) {
                if let Some(tx) = relay.mempool.get(&txid) {
                    round_txs.push(tx.clone());
                }
            }

            if !round_txs.is_empty() {
                let tx_count = round_txs.len() as u64;
                let included_txids = round_txs.iter().map(Transaction::txid).collect::<Vec<_>>();
                mine_block_with_transactions(
                    runtime,
                    args.interval_sec,
                    args.max_nonce,
                    cfg.block_subsidy,
                    miner_key_hash,
                    format!("soak-tx-{round}"),
                    round_txs,
                )?;
                let removed_confirmed = relay.mempool.remove_confirmed_txids(&included_txids);
                if has_inventory_delta_changes(0, removed_confirmed.len()) {
                    let _ = relay
                        .gossip
                        .apply_mempool_inventory_delta(Vec::new(), &removed_confirmed);
                }
                tx_blocks_mined = tx_blocks_mined.saturating_add(1);
                txs_included = txs_included.saturating_add(tx_count);
            }
            let _ = relay.orphan_pool.expire(now_unix_sec);
        }

        if let Some(path) = args.telemetry_out.as_ref()
            && should_emit_periodic_round(round, args.telemetry_every_rounds)
        {
            let snapshot = if let Some(relay) = relay_state.as_ref() {
                let mem = relay.mempool.telemetry();
                let orphan = relay.orphan_pool.telemetry();
                let gossip = relay.gossip.telemetry();
                SoakTelemetrySnapshot {
                    round,
                    unix_sec: now_unix_sec,
                    tip_height: runtime.tip_height(),
                    mempool_len: relay.mempool.len(),
                    orphan_pool_len: relay.orphan_pool.len(),
                    mempool_accepted_total: mem.accepted_total,
                    mempool_replaced_total: mem.replaced_total,
                    mempool_removed_by_replacement_total: mem.removed_by_replacement_total,
                    mempool_evicted_total: mem.evicted_total,
                    mempool_removed_by_block_total: mem.removed_by_block_total,
                    mempool_rejected_conflict_total: mem.rejected_conflict_total,
                    orphan_accepted_total: orphan.accepted_total,
                    orphan_evicted_total: orphan.evicted_total,
                    orphan_expired_total: orphan.expired_total,
                    orphan_promoted_total: orphan.promoted_total,
                    gossip_announced_txs_total: gossip.announced_txs_total,
                    gossip_removed_txs_total: gossip.removed_txs_total,
                    gossip_inbound_replacement_events_total: gossip
                        .inbound_replacement_events_total,
                    gossip_replacement_rate_limited_total: gossip.replacement_rate_limited_total,
                }
            } else {
                SoakTelemetrySnapshot {
                    round,
                    unix_sec: now_unix_sec,
                    tip_height: runtime.tip_height(),
                    mempool_len: 0,
                    orphan_pool_len: 0,
                    mempool_accepted_total: 0,
                    mempool_replaced_total: 0,
                    mempool_removed_by_replacement_total: 0,
                    mempool_evicted_total: 0,
                    mempool_removed_by_block_total: 0,
                    mempool_rejected_conflict_total: 0,
                    orphan_accepted_total: 0,
                    orphan_evicted_total: 0,
                    orphan_expired_total: 0,
                    orphan_promoted_total: 0,
                    gossip_announced_txs_total: 0,
                    gossip_removed_txs_total: 0,
                    gossip_inbound_replacement_events_total: 0,
                    gossip_replacement_rate_limited_total: 0,
                }
            };
            append_soak_telemetry_snapshot(path, &snapshot)?;
        }

        if should_persist_round(round, persist_every_rounds) {
            persist_runtime_db(runtime, &runtime_db_path)?;
        }
        Ok(())
    })?;
    persist_runtime_db(&runtime, &runtime_db_path)?;

    let blocks_per_sec = blocks_per_second(summary.blocks_mined, summary.elapsed_sec);
    println!("Soak run complete");
    println!("Network: {}", cfg.network_id);
    println!("Config: {}", config_path.display());
    println!("Runtime source: {}", source);
    println!("Runtime DB: {}", runtime_db_path.display());
    println!("Rounds: {}", summary.rounds);
    println!("Blocks mined: {}", summary.blocks_mined);
    println!("Height: {} -> {}", summary.start_height, summary.end_height);
    println!("Elapsed sec: {}", summary.elapsed_sec);
    println!("Blocks/sec: {:.2}", blocks_per_sec);
    println!("TX flow enabled: {}", tx_flow_enabled);
    if tx_flow_enabled {
        let projected_wall_clock_sec =
            (args.rounds as u64).saturating_mul(args.sleep_per_round_sec);
        println!("TXs/round target: {}", args.txs_per_round);
        println!("TX amount: {}", args.tx_amount);
        println!("TX fee: {}", args.tx_fee);
        println!("TX blocks mined: {}", tx_blocks_mined);
        println!("TXs included: {}", txs_included);
        println!("Replacement rate-limited events: {}", rate_limited_events);
        if let Some(path) = args.telemetry_out.as_ref() {
            println!("Telemetry out: {}", path.display());
            println!(
                "Telemetry snapshots every {} round(s)",
                args.telemetry_every_rounds
            );
        }
        println!("Round sleep sec: {}", args.sleep_per_round_sec);
        println!(
            "Projected wall-clock sec (round sleeps): {}",
            projected_wall_clock_sec
        );
    }
    Ok(())
}

fn run_reorg_demo(args: ReorgDemoArgs) -> Result<(), NodeError> {
    let config_path = args
        .config
        .unwrap_or_else(|| PathBuf::from(format!("config/{}.toml", args.network.as_str())));
    let mut cfg = load_chain_config(&config_path)?;
    cfg.difficulty_adjustment_window =
        reorg_min_difficulty_window(cfg.difficulty_adjustment_window);
    let miner_key_hash = cfg.genesis_reward_key_hash20()?;
    let mut runtime = ChainRuntime::from_config(cfg.clone())?;

    let main_params = MiningLoopParams {
        count: args.main_blocks,
        interval_sec: args.main_interval_sec,
        max_nonce: args.max_nonce,
        subsidy: cfg.block_subsidy,
        miner_key_hash,
        label_prefix: "main",
        print_each: false,
    };
    mine_blocks_on_runtime(&mut runtime, &main_params)?;

    let old_tip = runtime.tip_hash();
    let Some(fork_from_hash) = runtime.block_hash_at_height(args.fork_from_height) else {
        return Err(NodeError::Runtime(format!(
            "fork_from_height {} out of range",
            args.fork_from_height
        )));
    };
    let Some(fork_header) = runtime.header_by_hash(&fork_from_hash).cloned() else {
        return Err(NodeError::Runtime("fork header missing".to_owned()));
    };
    let fork_target = fork_header.target;
    let mut fork_prev = fork_from_hash;
    let mut fork_ts = fork_header.timestamp.saturating_add(args.fork_interval_sec);

    let mut reorg_count = 0u32;
    for i in 0..args.fork_blocks {
        let template = BlockTemplate {
            version: 1,
            prev_block: fork_prev,
            timestamp: fork_ts,
            target: fork_target,
            transactions: vec![build_coinbase_tx(
                format!("fork-{i}"),
                cfg.block_subsidy,
                miner_key_hash,
            )],
        };

        let Some(block) = mine_block(&template, args.max_nonce) else {
            return Err(NodeError::Runtime(format!(
                "cannot mine fork block {i} in range 0..={}",
                args.max_nonce
            )));
        };
        fork_prev = block.header.block_hash();
        fork_ts = fork_ts.saturating_add(args.fork_interval_sec);

        let outcome = runtime.submit_block(block)?;
        match outcome {
            BlockSubmissionOutcome::AlreadyKnown { block_hash } => {
                println!("fork block already known: {}", block_hash);
            }
            BlockSubmissionOutcome::StoredSideBranch { block_hash } => {
                println!("stored side block: {}", block_hash);
            }
            BlockSubmissionOutcome::ExtendedTip {
                new_tip,
                new_height,
            } => {
                println!(
                    "extended tip via fork path: h={} hash={}",
                    new_height, new_tip
                );
            }
            BlockSubmissionOutcome::Reorged {
                old_tip,
                new_tip,
                new_height,
            } => {
                reorg_count = reorg_count.saturating_add(1);
                println!(
                    "reorg occurred: old_tip={} -> new_tip={} at h={}",
                    old_tip, new_tip, new_height
                );
            }
        }
    }

    println!("Reorg demo summary");
    println!("Initial main tip: {}", old_tip);
    println!(
        "Final tip: h={} hash={}",
        runtime.tip_height(),
        runtime.tip_hash()
    );
    println!("Reorg events: {}", reorg_count);
    Ok(())
}

#[derive(Clone, Debug, Serialize, Deserialize)]
struct RpcMiningTemplate {
    version: u32,
    prev_hash_hex: String,
    merkle_root_hex: String,
    ntime: u64,
    network_target_hex: String,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
struct TemplateProviderRequest {
    channel_id: u32,
    version: u32,
    prev_hash_hex: String,
    ntime: u64,
    network_target_hex: String,
    block_subsidy: u64,
    reward_key_hash20_hex: String,
    coinbase_label: String,
}

