    #[test]
    fn decode_optional_hex32_handles_none_valid_and_invalid_values() {
        let none = super::decode_optional_hex32("field", &None).expect("none decode");
        assert!(none.is_none());

        let valid_raw = Some("11".repeat(32));
        let valid = super::decode_optional_hex32("field", &valid_raw).expect("valid decode");
        assert_eq!(valid, Some([0x11u8; 32]));

        let invalid_len = Some("aa".repeat(31));
        let err = super::decode_optional_hex32("field", &invalid_len).expect_err("invalid len");
        match err {
            super::NodeError::InvalidHexLength {
                field,
                expected,
                got,
            } => {
                assert_eq!(field, "field");
                assert_eq!(expected, 32);
                assert_eq!(got, 31);
            }
            other => panic!("unexpected decode error variant: {other}"),
        }
    }

    #[test]
    fn lock_conflict_detectors_are_exact_and_case_sensitive_for_expected_fragments() {
        let lock_open = super::NodeError::Runtime("Database already open".to_owned());
        let lock_acquire = super::NodeError::Runtime("Cannot acquire lock".to_owned());
        let lock_contended = super::NodeError::Runtime("runtime db is lock-contended".to_owned());
        let other = super::NodeError::Runtime("permission denied".to_owned());
        let lowercase = super::NodeError::Runtime("database already open".to_owned());

        assert!(super::is_runtime_db_lock_conflict(&lock_open));
        assert!(super::is_runtime_db_lock_conflict(&lock_acquire));
        assert!(super::is_runtime_db_lock_conflict(&lock_contended));
        assert!(!super::is_runtime_db_lock_conflict(&other));
        assert!(!super::is_runtime_db_lock_conflict(&lowercase));

        assert!(super::is_mempool_db_lock_conflict(&lock_open));
        assert!(super::is_mempool_db_lock_conflict(&lock_acquire));
        assert!(super::is_mempool_db_lock_conflict(&lock_contended));
        assert!(!super::is_mempool_db_lock_conflict(&other));
        assert!(!super::is_mempool_db_lock_conflict(&lowercase));

        assert!(super::is_peer_book_db_lock_conflict(&lock_open));
        assert!(super::is_peer_book_db_lock_conflict(&lock_acquire));
        assert!(super::is_peer_book_db_lock_conflict(&lock_contended));
        assert!(!super::is_peer_book_db_lock_conflict(&other));
        assert!(!super::is_peer_book_db_lock_conflict(&lowercase));

        assert!(super::submit_tx_retryable_lock_conflict(&lock_open));
        assert!(super::submit_tx_retryable_lock_conflict(&lock_acquire));
        assert!(super::submit_tx_retryable_lock_conflict(&lock_contended));
        assert!(!super::submit_tx_retryable_lock_conflict(&other));

        assert!(super::submit_tx_retry_has_remaining_attempts(0, 2));
        assert!(!super::submit_tx_retry_has_remaining_attempts(1, 2));
        assert!(!super::submit_tx_retry_has_remaining_attempts(0, 1));
    }

    #[test]
    fn submit_tx_with_retry_retries_only_on_lock_conflicts() {
        use std::sync::Arc;
        use std::sync::atomic::{AtomicUsize, Ordering};

        let lock_err = || super::NodeError::Runtime("Cannot acquire lock".to_owned());
        let non_lock_err = || super::NodeError::Runtime("permission denied".to_owned());

        let non_lock_calls = Arc::new(AtomicUsize::new(0));
        let non_lock_calls_clone = non_lock_calls.clone();
        let start = Instant::now();
        let err = super::submit_tx_with_retry::<(), _>(4, 200, move || {
            non_lock_calls_clone.fetch_add(1, Ordering::Relaxed);
            Err(non_lock_err())
        })
        .expect_err("non-lock errors must return immediately");
        assert!(err.to_string().contains("permission denied"));
        assert_eq!(non_lock_calls.load(Ordering::Relaxed), 1);
        assert!(
            start.elapsed() < Duration::from_millis(300),
            "non-lock path should not backoff"
        );

        let retry_then_ok_calls = Arc::new(AtomicUsize::new(0));
        let retry_then_ok_calls_clone = retry_then_ok_calls.clone();
        let result = super::submit_tx_with_retry(3, 1, move || {
            let idx = retry_then_ok_calls_clone.fetch_add(1, Ordering::Relaxed);
            if idx < 2 { Err(lock_err()) } else { Ok("ok") }
        })
        .expect("third attempt should succeed");
        assert_eq!(result, "ok");
        assert_eq!(retry_then_ok_calls.load(Ordering::Relaxed), 3);

        let lock_exhausted_calls = Arc::new(AtomicUsize::new(0));
        let lock_exhausted_calls_clone = lock_exhausted_calls.clone();
        let start = Instant::now();
        let exhausted = super::submit_tx_with_retry::<(), _>(3, 120, move || {
            lock_exhausted_calls_clone.fetch_add(1, Ordering::Relaxed);
            Err(lock_err())
        })
        .expect_err("lock conflicts must fail after bounded retries");
        assert!(exhausted.to_string().contains("Cannot acquire lock"));
        assert_eq!(lock_exhausted_calls.load(Ordering::Relaxed), 3);
        let elapsed = start.elapsed();
        assert!(
            elapsed >= Duration::from_millis(180),
            "expected two backoff sleeps, elapsed={elapsed:?}"
        );
        assert!(
            elapsed < Duration::from_millis(450),
            "unexpected extra sleeps, elapsed={elapsed:?}"
        );

        let single_try_calls = Arc::new(AtomicUsize::new(0));
        let single_try_calls_clone = single_try_calls.clone();
        let single = super::submit_tx_with_retry::<(), _>(0, 200, move || {
            single_try_calls_clone.fetch_add(1, Ordering::Relaxed);
            Err(lock_err())
        })
        .expect_err("attempts=0 should still run exactly one attempt");
        assert!(single.to_string().contains("Cannot acquire lock"));
        assert_eq!(single_try_calls.load(Ordering::Relaxed), 1);
    }

    #[test]
    fn persist_with_retry_retries_only_for_lock_conflicts() {
        use std::sync::Arc;
        use std::sync::atomic::{AtomicUsize, Ordering};

        let tries_ok = Arc::new(AtomicUsize::new(0));
        let tries_ok_clone = tries_ok.clone();
        super::persist_with_retry(
            3,
            1,
            super::is_runtime_db_lock_conflict,
            "unknown",
            move || {
                let attempt = tries_ok_clone.fetch_add(1, Ordering::Relaxed);
                if attempt == 0 {
                    Err(super::NodeError::Runtime(
                        "Database already open".to_owned(),
                    ))
                } else {
                    Ok(())
                }
            },
        )
        .expect("second attempt should succeed");
        assert_eq!(tries_ok.load(Ordering::Relaxed), 2);

        let tries_err = Arc::new(AtomicUsize::new(0));
        let tries_err_clone = tries_err.clone();
        let non_lock_err = super::persist_with_retry(
            5,
            20,
            super::is_runtime_db_lock_conflict,
            "unknown",
            move || {
                tries_err_clone.fetch_add(1, Ordering::Relaxed);
                Err(super::NodeError::Runtime("permission denied".to_owned()))
            },
        )
        .expect_err("non lock errors should not retry");
        assert!(non_lock_err.to_string().contains("permission denied"));
        assert_eq!(tries_err.load(Ordering::Relaxed), 1);

        let tries_zero = Arc::new(AtomicUsize::new(0));
        let tries_zero_clone = tries_zero.clone();
        let exhausted = super::persist_with_retry(
            0,
            1,
            super::is_runtime_db_lock_conflict,
            "unknown runtime persist error",
            move || {
                tries_zero_clone.fetch_add(1, Ordering::Relaxed);
                Err(super::NodeError::Runtime(
                    "Database already open".to_owned(),
                ))
            },
        )
        .expect_err("attempts=0 still performs one try");
        assert!(exhausted.to_string().contains("Database already open"));
        assert_eq!(tries_zero.load(Ordering::Relaxed), 1);

        let start = Instant::now();
        let timed = super::persist_with_retry(
            2,
            200,
            super::is_runtime_db_lock_conflict,
            "unknown runtime persist error",
            || {
                Err(super::NodeError::Runtime(
                    "Database already open".to_owned(),
                ))
            },
        )
        .expect_err("lock-conflict path must fail after bounded retries");
        assert!(timed.to_string().contains("Database already open"));
        let elapsed = start.elapsed();
        assert!(
            elapsed >= Duration::from_millis(160),
            "expected one 200ms backoff sleep, elapsed={elapsed:?}"
        );
        assert!(
            elapsed < Duration::from_millis(350),
            "unexpected extra backoff sleeps, elapsed={elapsed:?}"
        );

        let start = Instant::now();
        let timed_three = super::persist_with_retry(
            3,
            150,
            super::is_runtime_db_lock_conflict,
            "unknown runtime persist error",
            || {
                Err(super::NodeError::Runtime(
                    "Database already open".to_owned(),
                ))
            },
        )
        .expect_err("attempts=3 should perform two backoff sleeps");
        assert!(timed_three.to_string().contains("Database already open"));
        let elapsed = start.elapsed();
        assert!(
            elapsed >= Duration::from_millis(260),
            "expected two backoff sleeps for attempts=3, elapsed={elapsed:?}"
        );
        assert!(
            elapsed < Duration::from_millis(500),
            "unexpected extra backoffs for attempts=3, elapsed={elapsed:?}"
        );
    }

    #[test]
    fn load_mempool_with_retry_inner_retries_lock_conflicts_and_stops_on_other_errors() {
        use std::sync::Arc;
        use std::sync::atomic::{AtomicUsize, Ordering};

        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");

        let calls_fallback = Arc::new(AtomicUsize::new(0));
        let calls_fallback_clone = calls_fallback.clone();
        let start = Instant::now();
        let mempool = super::load_mempool_with_retry_inner(&cfg, 2, 200, move || {
            calls_fallback_clone.fetch_add(1, Ordering::Relaxed);
            Err(super::NodeError::Runtime(
                "Database already open".to_owned(),
            ))
        })
        .expect("fallback to empty mempool");
        assert_eq!(mempool.len(), 0);
        assert_eq!(calls_fallback.load(Ordering::Relaxed), 2);
        let elapsed = start.elapsed();
        assert!(
            elapsed >= Duration::from_millis(160),
            "expected one 200ms backoff sleep on lock conflict, elapsed={elapsed:?}"
        );
        assert!(
            elapsed < Duration::from_millis(350),
            "unexpected extra backoff sleeps on lock conflict, elapsed={elapsed:?}"
        );

        let max_txs = cfg.max_mempool_txs as usize;
        let min_fee = cfg.min_relay_fee_per_kb;
        let calls_success = Arc::new(AtomicUsize::new(0));
        let calls_success_clone = calls_success.clone();
        let mempool = super::load_mempool_with_retry_inner(&cfg, 4, 1, move || {
            let attempt = calls_success_clone.fetch_add(1, Ordering::Relaxed);
            if attempt == 0 {
                return Err(super::NodeError::Runtime("Cannot acquire lock".to_owned()));
            }
            Mempool::with_policy(max_txs, min_fee).map_err(super::NodeError::from)
        })
        .expect("second attempt should succeed");
        assert_eq!(mempool.len(), 0);
        assert_eq!(calls_success.load(Ordering::Relaxed), 2);

        let calls_err = Arc::new(AtomicUsize::new(0));
        let calls_err_clone = calls_err.clone();
        let err = super::load_mempool_with_retry_inner(&cfg, 5, 25, move || {
            calls_err_clone.fetch_add(1, Ordering::Relaxed);
            Err(super::NodeError::Runtime("permission denied".to_owned()))
        })
        .expect_err("non-lock errors must fail immediately");
        assert!(err.to_string().contains("permission denied"));
        assert_eq!(calls_err.load(Ordering::Relaxed), 1);
    }

    #[test]
    fn load_with_retry_retries_lock_conflicts_and_bubbles_non_lock_errors() {
        use std::sync::Arc;
        use std::sync::atomic::{AtomicUsize, Ordering};

        let calls_none = Arc::new(AtomicUsize::new(0));
        let calls_none_clone = calls_none.clone();
        let start = Instant::now();
        let none: Option<u64> =
            super::load_with_retry(2, 200, super::is_runtime_db_lock_conflict, move || {
                calls_none_clone.fetch_add(1, Ordering::Relaxed);
                Err(super::NodeError::Runtime(
                    "Database already open".to_owned(),
                ))
            })
            .expect("lock conflicts should degrade to None");
        assert!(none.is_none());
        assert_eq!(calls_none.load(Ordering::Relaxed), 2);
        let elapsed = start.elapsed();
        assert!(
            elapsed >= Duration::from_millis(160),
            "expected one 200ms backoff sleep, elapsed={elapsed:?}"
        );
        assert!(
            elapsed < Duration::from_millis(350),
            "unexpected extra backoff sleeps, elapsed={elapsed:?}"
        );

        let calls_some = Arc::new(AtomicUsize::new(0));
        let calls_some_clone = calls_some.clone();
        let some = super::load_with_retry(3, 1, super::is_runtime_db_lock_conflict, move || {
            let attempt = calls_some_clone.fetch_add(1, Ordering::Relaxed);
            if attempt == 0 {
                Err(super::NodeError::Runtime("Cannot acquire lock".to_owned()))
            } else {
                Ok(7u64)
            }
        })
        .expect("second attempt should succeed");
        assert_eq!(some, Some(7));
        assert_eq!(calls_some.load(Ordering::Relaxed), 2);

        let calls_err = Arc::new(AtomicUsize::new(0));
        let calls_err_clone = calls_err.clone();
        let err = super::load_with_retry(5, 1, super::is_runtime_db_lock_conflict, move || {
            calls_err_clone.fetch_add(1, Ordering::Relaxed);
            Err::<u64, super::NodeError>(super::NodeError::Runtime("permission denied".to_owned()))
        })
        .expect_err("non-lock errors should not retry");
        assert!(err.to_string().contains("permission denied"));
        assert_eq!(calls_err.load(Ordering::Relaxed), 1);
    }

    #[test]
    fn remove_confirmed_txids_from_mempool_db_handles_missing_and_readonly_db_paths() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let work_dir = temp_dir("test-remove-confirmed-mempool-db");
        fs::create_dir_all(&work_dir).expect("mkdir");
        let missing_db = work_dir.join("missing-mempool.redb");
        let txid = Hash256([0x55; 32]);

        let removed = super::remove_confirmed_txids_from_mempool_db(&cfg, &missing_db, &[txid])
            .expect("missing db path should be accepted");
        assert_eq!(removed, 0);
        assert!(
            !missing_db.exists(),
            "missing mempool DB should stay absent when nothing is removed"
        );

        let existing_db = work_dir.join("existing-mempool.redb");
        let snapshot = MempoolSnapshot {
            network_id: cfg.network_id.clone(),
            entries: Vec::new(),
        };
        save_mempool_db(&existing_db, &snapshot).expect("persist snapshot");
        let mut perms = fs::metadata(&existing_db).expect("metadata").permissions();
        perms.set_readonly(true);
        fs::set_permissions(&existing_db, perms).expect("set readonly");

        let err = super::remove_confirmed_txids_from_mempool_db(&cfg, &existing_db, &[txid])
            .expect_err("readonly existing db should fail on persist");
        assert!(
            err.to_string().contains("Permission denied"),
            "unexpected readonly error: {err}"
        );

        let writable_db = work_dir.join("writable-empty-mempool.redb");
        save_mempool_db(
            &writable_db,
            &MempoolSnapshot {
                network_id: cfg.network_id.clone(),
                entries: Vec::new(),
            },
        )
        .expect("save writable snapshot");
        let persist_calls_before = super::mempool_persist_calls_for_tests();
        let removed = super::remove_confirmed_txids_from_mempool_db(&cfg, &writable_db, &[txid])
            .expect("existing writable db should still persist even when nothing is removed");
        assert_eq!(removed, 0);
        assert!(
            super::mempool_persist_calls_for_tests() > persist_calls_before,
            "persist path must be exercised for existing writable db even when removed set is empty"
        );

        let _ = fs::remove_dir_all(work_dir);
    }

    #[test]
    fn remove_confirmed_txids_present_on_chain_drops_confirmed_entries() {
        let mut cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        cfg.coinbase_maturity = 1;
        cfg.validate().expect("config validate");

        let mnemonic = WalletMnemonic::parse(SOAK_FLOW_MNEMONIC).expect("mnemonic");
        let seed = mnemonic.to_seed("");
        let sender_key = derive_wallet_key(&seed, 0, 0).expect("sender key");
        let recipient_key = derive_wallet_key(&seed, 0, 1).expect("recipient key");
        let sender_key_hash20 = scam_core::hash160_blake3(&sender_key.pubkey_compressed());
        let recipient_key_hash20 = scam_core::hash160_blake3(&recipient_key.pubkey_compressed());

        let mut runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        mine_blocks_on_runtime(
            &mut runtime,
            &super::MiningLoopParams {
                count: 2,
                interval_sec: cfg.target_block_time_sec,
                max_nonce: 500_000,
                subsidy: cfg.block_subsidy,
                miner_key_hash: sender_key_hash20,
                label_prefix: "remove-confirmed-helper",
                print_each: false,
            },
        )
        .expect("mine funding");

        let fee = 1_000u64;
        let signed = super::build_signed_transfer_tx(
            &runtime,
            &cfg.network_id,
            &sender_key,
            recipient_key_hash20,
            100_000,
            fee,
        )
        .expect("signed transfer");
        let confirmed_txid = signed.tx.txid();

        let mut mempool =
            Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool");
        mempool
            .insert_with_fee(signed.tx.clone(), fee)
            .expect("insert transfer");
        assert!(mempool.contains(&confirmed_txid));

        let template_params = super::MempoolTemplateParams {
            version: 1,
            prev_block: runtime.tip_hash(),
            timestamp: runtime
                .tip_header()
                .timestamp
                .saturating_add(cfg.target_block_time_sec),
            target: runtime.expected_target_for_next_block().expect("target"),
            block_subsidy: cfg.block_subsidy,
            miner_key_hash20: sender_key_hash20,
            coinbase_tag: "remove-confirmed-helper-template".to_owned(),
            max_txs: cfg.max_mempool_txs as usize,
        };
        let (template, summary) =
            super::build_template_from_mempool(&template_params, &mempool).expect("template");
        assert!(summary.included_txids.contains(&confirmed_txid));
        let mined = mine_block(&template, 500_000).expect("mine tx block");
        runtime.apply_next_block(mined).expect("apply tx block");

        let removed = super::remove_confirmed_txids_present_on_chain(&runtime, &mut mempool);
        assert_eq!(removed, 1);
        assert!(!mempool.contains(&confirmed_txid));
    }

    #[test]
    fn remove_mempool_txs_with_missing_inputs_removes_stale_dependency_chain() {
        let mut cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        cfg.coinbase_maturity = 1;
        cfg.min_relay_fee_per_kb = 0;
        cfg.validate().expect("config validate");

        let mnemonic = WalletMnemonic::parse(SOAK_FLOW_MNEMONIC).expect("mnemonic");
        let seed = mnemonic.to_seed("");
        let sender_key = derive_wallet_key(&seed, 0, 0).expect("sender key");
        let sender_key_hash20 = scam_core::hash160_blake3(&sender_key.pubkey_compressed());
        let recipient_key_hash20 = scam_core::hash160_blake3(
            &derive_wallet_key(&seed, 0, 1)
                .expect("recipient key")
                .pubkey_compressed(),
        );

        let mut runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        mine_blocks_on_runtime(
            &mut runtime,
            &super::MiningLoopParams {
                count: 2,
                interval_sec: cfg.target_block_time_sec,
                max_nonce: 500_000,
                subsidy: cfg.block_subsidy,
                miner_key_hash: sender_key_hash20,
                label_prefix: "remove-missing-helper",
                print_each: false,
            },
        )
        .expect("mine funding");

        let signed_parent = super::build_signed_transfer_tx(
            &runtime,
            &cfg.network_id,
            &sender_key,
            recipient_key_hash20,
            100_000,
            1_000,
        )
        .expect("signed parent");
        let mut stale_parent = signed_parent.tx;
        stale_parent.inputs[0].prev_out = OutPoint {
            txid: Hash256([0xA5; 32]),
            vout: 0,
        };
        let stale_parent_txid = stale_parent.txid();

        let stale_child = Transaction {
            version: 1,
            inputs: vec![TxIn {
                prev_out: OutPoint {
                    txid: stale_parent_txid,
                    vout: 0,
                },
                signature: vec![1],
                pubkey_compressed: sender_key.pubkey_compressed().to_vec(),
                sequence: u32::MAX,
            }],
            outputs: vec![TxOut {
                value: 50_000,
                key_hash20: sender_key_hash20,
            }],
            lock_time: 0,
        };
        let stale_child_txid = stale_child.txid();

        let mut mempool =
            Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool");
        mempool
            .insert_with_fee(stale_parent, 10_000)
            .expect("insert stale parent");
        mempool
            .insert_with_fee(stale_child, 10_000)
            .expect("insert stale child");
        assert!(mempool.contains(&stale_parent_txid));
        assert!(mempool.contains(&stale_child_txid));

        let removed = super::remove_mempool_txs_with_missing_inputs(&runtime, &mut mempool);
        assert_eq!(removed, 2, "stale parent + child must both be removed");
        assert!(!mempool.contains(&stale_parent_txid));
        assert!(!mempool.contains(&stale_child_txid));
        assert!(mempool.is_empty());
    }

