    #[test]
    fn relay_send_message_or_closed_maps_closed_io_to_disconnect() {
        let framing = FramingConfig::default();
        let ping = WireMessage::Ping { nonce: 7 };

        let mut ok = Vec::<u8>::new();
        let sent = super::relay_send_message_or_closed(&mut ok, &ping, &framing).expect("send ok");
        assert!(sent);
        assert!(!ok.is_empty());

        struct ClosedWriter;
        impl Write for ClosedWriter {
            fn write(&mut self, _buf: &[u8]) -> std::io::Result<usize> {
                Err(std::io::Error::from(std::io::ErrorKind::BrokenPipe))
            }

            fn flush(&mut self) -> std::io::Result<()> {
                Ok(())
            }
        }
        let mut closed = ClosedWriter;
        let sent = super::relay_send_message_or_closed(&mut closed, &ping, &framing)
            .expect("closed-like errors should map to graceful disconnect");
        assert!(!sent);

        struct DeniedWriter;
        impl Write for DeniedWriter {
            fn write(&mut self, _buf: &[u8]) -> std::io::Result<usize> {
                Err(std::io::Error::from(std::io::ErrorKind::PermissionDenied))
            }

            fn flush(&mut self) -> std::io::Result<()> {
                Ok(())
            }
        }
        let mut denied = DeniedWriter;
        let err = super::relay_send_message_or_closed(&mut denied, &ping, &framing)
            .expect_err("non-closed write errors must bubble up");
        assert!(err.to_string().contains("io error"));
    }

    #[test]
    fn relay_send_messages_until_closed_sends_all_messages_or_stops_cleanly() {
        let framing = FramingConfig::default();
        let messages = vec![
            WireMessage::Ping { nonce: 7 },
            WireMessage::Ping { nonce: 8 },
        ];

        let mut out = Vec::<u8>::new();
        let sent_all =
            super::relay_send_messages_until_closed(&mut out, &messages, &framing).expect("send");
        assert!(sent_all);
        let mut reader = std::io::Cursor::new(out);
        let first = read_message(&mut reader, &framing).expect("first");
        let second = read_message(&mut reader, &framing).expect("second");
        assert!(matches!(first, WireMessage::Ping { nonce: 7 }));
        assert!(matches!(second, WireMessage::Ping { nonce: 8 }));

        struct ClosedWriter;
        impl Write for ClosedWriter {
            fn write(&mut self, _buf: &[u8]) -> std::io::Result<usize> {
                Err(std::io::Error::from(std::io::ErrorKind::BrokenPipe))
            }

            fn flush(&mut self) -> std::io::Result<()> {
                Ok(())
            }
        }
        let mut closed = ClosedWriter;
        let sent_all = super::relay_send_messages_until_closed(&mut closed, &messages, &framing)
            .expect("closed path");
        assert!(!sent_all);
    }

    #[test]
    fn relay_send_message_or_closed_async_classifies_closed_and_fatal_errors() {
        struct ErrorAsyncWriter {
            kind: std::io::ErrorKind,
        }

        impl tokio::io::AsyncWrite for ErrorAsyncWriter {
            fn poll_write(
                self: std::pin::Pin<&mut Self>,
                _cx: &mut std::task::Context<'_>,
                _buf: &[u8],
            ) -> std::task::Poll<std::io::Result<usize>> {
                std::task::Poll::Ready(Err(std::io::Error::from(self.kind)))
            }

            fn poll_flush(
                self: std::pin::Pin<&mut Self>,
                _cx: &mut std::task::Context<'_>,
            ) -> std::task::Poll<std::io::Result<()>> {
                std::task::Poll::Ready(Ok(()))
            }

            fn poll_shutdown(
                self: std::pin::Pin<&mut Self>,
                _cx: &mut std::task::Context<'_>,
            ) -> std::task::Poll<std::io::Result<()>> {
                std::task::Poll::Ready(Ok(()))
            }
        }

        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("tokio runtime");
        rt.block_on(async {
            let framing = FramingConfig::default();
            let message = WireMessage::Ping { nonce: 11 };

            let mut closed = ErrorAsyncWriter {
                kind: std::io::ErrorKind::BrokenPipe,
            };
            let sent =
                super::relay_send_message_or_closed_async(&mut closed, &message, &framing, 1)
                    .await
                    .expect("closed-like io must map to graceful false");
            assert!(!sent);

            let mut denied = ErrorAsyncWriter {
                kind: std::io::ErrorKind::PermissionDenied,
            };
            let err = super::relay_send_message_or_closed_async(&mut denied, &message, &framing, 1)
                .await
                .expect_err("fatal io must bubble up");
            assert!(err.to_string().contains("io error"));
        });
    }

    #[test]
    fn relay_send_message_or_closed_async_applies_diffusion_delay_for_tx_inventory() {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("tokio runtime");
        rt.block_on(async {
            super::RELAY_TX_DIFFUSION_BASE_MS.store(30, std::sync::atomic::Ordering::Relaxed);
            super::RELAY_TX_DIFFUSION_MAX_MS.store(30, std::sync::atomic::Ordering::Relaxed);

            let framing = FramingConfig::default();
            let txid = scam_core::hash::hash256(b"diffusion-latency");
            let message = WireMessage::Inv {
                items: vec![InventoryItem::Tx(txid)],
            };
            let mut sink = tokio::io::sink();
            let start = std::time::Instant::now();
            let sent = super::relay_send_message_or_closed_async(&mut sink, &message, &framing, 1)
                .await
                .expect("send");
            let elapsed = start.elapsed();
            assert!(sent);
            assert!(
                elapsed >= Duration::from_millis(25),
                "diffusion delay should be applied for tx inv, elapsed={elapsed:?}"
            );

            super::RELAY_TX_DIFFUSION_BASE_MS.store(0, std::sync::atomic::Ordering::Relaxed);
            super::RELAY_TX_DIFFUSION_MAX_MS.store(0, std::sync::atomic::Ordering::Relaxed);
        });
    }

