    #[test]
    fn map_sv2_read_result_handles_timeout_and_fatal_errors() {
        let timeout = super::map_sv2_read_result(Err(scam_stratum::StratumError::Io(
            std::io::Error::from(std::io::ErrorKind::TimedOut),
        )))
        .expect("timeout maps to read timeout");
        assert!(matches!(timeout, super::StratumReadOutcome::Timeout));

        let closed = super::map_sv2_read_result(Err(scam_stratum::StratumError::Io(
            std::io::Error::from(std::io::ErrorKind::ConnectionReset),
        )))
        .expect("closed-like io maps to closed");
        assert!(matches!(closed, super::StratumReadOutcome::Closed));

        let keepalive = super::map_sv2_read_result(Ok(Some(Sv2Message::KeepAlive)))
            .expect("message pass-through");
        assert!(matches!(
            keepalive,
            super::StratumReadOutcome::Message(Sv2Message::KeepAlive)
        ));

        let clean_close = super::map_sv2_read_result(Ok(None)).expect("closed pass-through");
        assert!(matches!(clean_close, super::StratumReadOutcome::Closed));

        let fatal = match super::map_sv2_read_result(Err(
            scam_stratum::StratumError::InvalidFrameLength(17),
        )) {
            Ok(_) => panic!("fatal stratum error should bubble up"),
            Err(err) => err,
        };
        assert!(fatal.to_string().contains("stratum read failed"));

        let fatal_io = match super::map_sv2_read_result(Err(scam_stratum::StratumError::Io(
            std::io::Error::from(std::io::ErrorKind::PermissionDenied),
        ))) {
            Ok(_) => panic!("non-timeout io errors must bubble up"),
            Err(err) => err,
        };
        assert!(fatal_io.to_string().contains("stratum read failed"));
    }

    #[test]
    fn map_rpc_accept_result_retries_only_for_shutdown_nonblocking_errors() {
        let mapped = super::map_rpc_accept_result(
            Err(std::io::Error::from(std::io::ErrorKind::Interrupted)),
            true,
        )
        .expect("shutdown mode should treat interrupted accept as retry");
        assert!(mapped.is_none());

        let retry = super::map_rpc_accept_result(
            Err(std::io::Error::from(std::io::ErrorKind::WouldBlock)),
            true,
        )
        .expect("shutdown mode should treat would-block as retry");
        assert!(retry.is_none());

        let no_shutdown = super::map_rpc_accept_result(
            Err(std::io::Error::from(std::io::ErrorKind::WouldBlock)),
            false,
        )
        .expect_err("without shutdown flag, would-block must be fatal");
        assert!(no_shutdown.to_string().contains("rpc accept failed"));

        let fatal = super::map_rpc_accept_result(
            Err(std::io::Error::from(std::io::ErrorKind::PermissionDenied)),
            true,
        )
        .expect_err("non-retry io errors must stay fatal");
        assert!(fatal.to_string().contains("rpc accept failed"));
    }

