    #[test]
    fn relay_reputation_helpers_require_positive_deltas() {
        assert!(super::relay_startup_send_failed(false));
        assert!(!super::relay_startup_send_failed(true));
        assert!(super::relay_should_abort_after_startup_send(
            super::RelayPeerSessionMode::Outbound,
            false
        ));
        assert!(!super::relay_should_abort_after_startup_send(
            super::RelayPeerSessionMode::Outbound,
            true
        ));
        assert!(!super::relay_should_abort_after_startup_send(
            super::RelayPeerSessionMode::Inbound,
            false
        ));
        assert!(!super::should_persist_peer_reputation(
            super::RuntimePeerReputation {
                replacement_rate_limited_total: 0,
                last_replacement_rate_limited_unix_sec: 1,
                protocol_violation_total: 0,
                last_protocol_violation_unix_sec: 0,
            }
        ));
        assert!(super::should_persist_peer_reputation(
            super::RuntimePeerReputation {
                replacement_rate_limited_total: 1,
                last_replacement_rate_limited_unix_sec: 1,
                protocol_violation_total: 0,
                last_protocol_violation_unix_sec: 0,
            }
        ));
        assert!(super::should_persist_peer_reputation(
            super::RuntimePeerReputation {
                replacement_rate_limited_total: 0,
                last_replacement_rate_limited_unix_sec: 0,
                protocol_violation_total: 1,
                last_protocol_violation_unix_sec: 1,
            }
        ));

        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        let relay = RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool"),
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)
                .expect("orphan"),
            gossip: GossipEngine::new(16).expect("gossip"),
        };
        let mut state = RelayServerState::new(runtime, relay);
        super::relay_mark_peer_replacement_rate_limited(&mut state, 7, 100);
        super::relay_mark_peer_replacement_rate_limited(&mut state, 7, 110);
        let delta = super::relay_take_peer_runtime_reputation(&mut state, 7);
        assert_eq!(delta.replacement_rate_limited_total, 2);
        assert_eq!(delta.last_replacement_rate_limited_unix_sec, 110);
        super::relay_mark_protocol_violation(&mut state, 7, 120);
        let protocol_delta = super::relay_take_peer_runtime_reputation(&mut state, 7);
        assert_eq!(protocol_delta.protocol_violation_total, 1);
        assert_eq!(protocol_delta.last_protocol_violation_unix_sec, 120);
        let empty = super::relay_take_peer_runtime_reputation(&mut state, 7);
        assert_eq!(empty.replacement_rate_limited_total, 0);
    }

    #[test]
    fn run_stratum_client_async_rejects_submit_before_setup_without_tcp_socket() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        let runtime_tip_height = runtime.tip_height();
        let runtime_tip_hash = runtime.tip_hash();
        let runtime_db_path = temp_dir("test-stratum-client-async-logic").join("runtime.redb");
        let mempool_db_path = runtime_db_path.with_file_name("mempool.redb");
        let pool_ledger_db_path = runtime_db_path.with_file_name("pool-ledger.redb");
        let pool_ledger_state = super::StratumPoolLedgerState::new(
            cfg.network_id.clone(),
            runtime_tip_height,
            runtime_tip_hash,
            super::current_unix_sec().unwrap_or(1),
            super::POOL_DEFAULT_SHARE_RETENTION,
            super::POOL_DEFAULT_ROUND_RETENTION,
        );
        let ctx = super::StratumServerContext {
            cfg: cfg.clone(),
            runtime: std::sync::Arc::new(std::sync::Mutex::new(runtime)),
            runtime_db_path,
            mempool_db_path,
            max_template_txs: cfg.max_mempool_txs as usize,
            share_target: Target::MAX,
            min_share_target: Target::from_hex(&cfg.stratum_min_share_target)
                .expect("min share target parse"),
            max_share_target: Target::from_hex(&cfg.stratum_max_share_target)
                .expect("max share target parse"),
            vardiff_target_shares_per_minute: cfg.stratum_vardiff_target_shares_per_minute,
            vardiff_retarget_interval_shares: cfg.stratum_vardiff_retarget_interval_shares as usize,
            vardiff_clamp_up: cfg.stratum_vardiff_clamp_up,
            vardiff_clamp_down: cfg.stratum_vardiff_clamp_down,
            max_rejected_shares: cfg.stratum_max_rejected_shares,
            read_timeout_sec: 1,
            handshake_timeout_sec: 1,
            keepalive_sec: 1,
            idle_timeout_sec: 3,
            max_protocol_violations: 4,
            next_channel_id: std::sync::Arc::new(std::sync::atomic::AtomicU32::new(0)),
            template_provider: super::RuntimeTemplateProvider,
            job_declarator: std::sync::Arc::new(std::sync::Mutex::new(
                scam_stratum::SequentialJobDeclarator::default(),
            )),
            max_jobs_per_channel: cfg.stratum_max_jobs_per_channel as usize,
            active_clients: std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0)),
            secure_transport: false,
            secure_transport_mode: super::SecureTransportMode::NoiseXx,
            secure_rekey_interval_messages: 16,
            secure_static_private_key: None,
            secure_expected_remote_static_public_key: None,
            template_provider_addr: None,
            job_declarator_addr: None,
            telemetry_state: std::sync::Arc::new(std::sync::Mutex::new(
                super::StratumPoolTelemetryState::default(),
            )),
            pool_ledger_state: std::sync::Arc::new(std::sync::Mutex::new(pool_ledger_state)),
            pool_ledger_db_path,
            pool_payout_cfg: super::PoolPayoutConfig::default(),
            pool_payout_key: None,
            pool_coinbase_key_hash20: cfg.genesis_reward_key_hash20().expect("reward key"),
        };

        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("tokio runtime");
        rt.block_on(async move {
            let (mut peer, server_stream) = tokio::io::duplex(8 * 1024);
            super::write_sv2_frame_async(
                &mut peer,
                &Sv2Message::SubmitSharesStandard {
                    channel_id: 1,
                    job_id: 7,
                    nonce: 0,
                    ntime: 0,
                },
            )
            .await
            .expect("send malformed-for-state message");
            drop(peer);

            let permit = std::sync::Arc::new(tokio::sync::Semaphore::new(1))
                .acquire_owned()
                .await
                .expect("permit");
            let err = super::run_stratum_client_async(server_stream, ctx, permit)
                .await
                .expect_err("submit-before-setup must be rejected");
            assert!(
                err.to_string()
                    .contains("submit_share received before active channel")
                    || err.to_string().contains("broken pipe"),
                "unexpected error: {err}"
            );
        });
    }

