    #[test]
    fn sync_book_helpers_match_addresses_and_dedup_records() {
        let mut book = PeerAddressBook {
            network_id: "devnet".to_owned(),
            peers: vec![
                PeerAddressRecord {
                    address: "127.0.0.1:18444".to_owned(),
                    last_seen_unix_sec: 1,
                    ban_score: 2,
                },
                PeerAddressRecord {
                    address: "127.0.0.1:18443".to_owned(),
                    last_seen_unix_sec: 0,
                    ban_score: 0,
                },
                PeerAddressRecord {
                    address: "127.0.0.1:18444".to_owned(),
                    last_seen_unix_sec: 9,
                    ban_score: 9,
                },
            ],
        };

        assert!(super::peer_book_contains_address(&book, "127.0.0.1:18444"));
        assert!(!super::peer_book_contains_address(&book, "127.0.0.1:29999"));

        super::sort_and_dedup_peer_book(&mut book);
        assert_eq!(book.peers.len(), 2);
        assert_eq!(book.peers[0].address, "127.0.0.1:18443");
        assert_eq!(book.peers[1].address, "127.0.0.1:18444");

        let peer = super::find_peer_record_mut(&mut book, "127.0.0.1:18444").expect("peer");
        peer.ban_score = 7;
        assert_eq!(
            super::find_peer_record_mut(&mut book, "127.0.0.1:18444")
                .expect("peer")
                .ban_score,
            7
        );
        assert_eq!(
            book.peers
                .iter()
                .find(|peer| peer.address == "127.0.0.1:18443")
                .expect("other peer")
                .ban_score,
            0,
            "mutating a matched peer must not affect other entries"
        );
        assert_eq!(
            book.peers
                .iter()
                .find(|peer| peer.address == "127.0.0.1:18444")
                .expect("target peer")
                .ban_score,
            7
        );
        assert!(!super::sync_book_has_success(0));
        assert!(super::sync_book_has_success(1));
    }

    #[test]
    fn peer_reputation_store_roundtrip_and_weight_decay() {
        let peers_dir = temp_dir("test-peer-reputation-roundtrip");
        std::fs::create_dir_all(&peers_dir).expect("mkdir peers");
        let store = super::PeerReputationStore::from_peers_dir(&peers_dir, "devnet");
        let now = 1_770_000_000u64;

        super::update_peer_reputation_store(
            &store,
            "127.0.0.1:18444",
            super::RuntimePeerReputation {
                replacement_rate_limited_total: 3,
                last_replacement_rate_limited_unix_sec: now,
                protocol_violation_total: 0,
                last_protocol_violation_unix_sec: 0,
            },
            now,
        )
        .expect("first reputation update");
        super::update_peer_reputation_store(
            &store,
            "127.0.0.1:18444",
            super::RuntimePeerReputation {
                replacement_rate_limited_total: 2,
                last_replacement_rate_limited_unix_sec: now + 10,
                protocol_violation_total: 2,
                last_protocol_violation_unix_sec: now + 10,
            },
            now + 10,
        )
        .expect("second reputation update");

        let loaded =
            super::load_peer_reputation_book(&store.path, "devnet").expect("load reputation book");
        assert_eq!(loaded.peers.len(), 1);
        assert_eq!(loaded.peers[0].replacement_rate_limited_total, 5);
        assert_eq!(
            loaded.peers[0].last_replacement_rate_limited_unix_sec,
            now + 10
        );
        assert_eq!(loaded.peers[0].protocol_violation_total, 2);
        assert_eq!(loaded.peers[0].last_protocol_violation_unix_sec, now + 10);

        let immediate =
            super::load_peer_reputation_weights(&store, now + 10).expect("load immediate weights");
        assert_eq!(
            immediate.get("127.0.0.1:18444").copied(),
            Some(9),
            "protocol violations are weighted stronger than replacement-limit events"
        );

        let decayed = super::load_peer_reputation_weights(&store, now + 2 * 24 * 60 * 60)
            .expect("load decayed weights");
        assert_eq!(decayed.get("127.0.0.1:18444").copied(), Some(5));

        let expired = super::load_peer_reputation_weights(&store, now + 8 * 24 * 60 * 60)
            .expect("load expired weights");
        assert!(
            !expired.contains_key("127.0.0.1:18444"),
            "old reputation should age out of selection penalties"
        );

        let _ = std::fs::remove_dir_all(peers_dir);
    }

