    #[test]
    fn relay_server_snapshot_uses_max_known_tip_from_peers() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        let relay = RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool"),
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)
                .expect("orphan"),
            gossip: GossipEngine::new(64).expect("gossip"),
        };
        let mut state = RelayServerState::new(runtime, relay);
        assert_eq!(state.runtime.tip_height(), 0);

        state.peer_reported_tip_heights.insert(11, 7);
        state.peer_reported_tip_heights.insert(22, 9);
        let snapshot = super::relay_server_snapshot(&state, 2, 10_000);
        assert_eq!(snapshot.tip_height, 0);
        assert_eq!(snapshot.max_known_tip_height, 9);
        assert_eq!(snapshot.global_sync_lag_blocks, 9);
    }

    #[test]
    fn relay_headers_catchup_requests_use_probe_and_ahead_intervals() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        let relay = RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool"),
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)
                .expect("orphan"),
            gossip: GossipEngine::new(64).expect("gossip"),
        };
        let mut state = RelayServerState::new(runtime, relay);
        let peer_id = 17u64;

        // Same height => periodic probe requests headers.
        state.peer_reported_tip_heights.insert(peer_id, 0);
        let probe = super::relay_maybe_request_headers_catchup(&mut state, peer_id, 100)
            .expect("equal height should trigger periodic probe");
        assert!(matches!(
            probe,
            WireMessage::GetHeaders {
                locator: _,
                stop: None
            }
        ));
        assert!(
            super::relay_maybe_request_headers_catchup(&mut state, peer_id, 114).is_none(),
            "probe cooldown must suppress early refreshes"
        );
        assert!(
            super::relay_maybe_request_headers_catchup(&mut state, peer_id, 115).is_some(),
            "probe should fire again after probe interval"
        );

        // Peer moderately ahead => request cadence uses normal catchup interval.
        state.peer_reported_tip_heights.insert(peer_id, 3);
        let first = super::relay_maybe_request_headers_catchup(&mut state, peer_id, 117)
            .expect("should request headers");
        assert!(matches!(
            first,
            WireMessage::GetHeaders {
                locator: _,
                stop: None
            }
        ));

        // Cooldown applies.
        assert!(
            super::relay_maybe_request_headers_catchup(&mut state, peer_id, 118).is_none(),
            "cooldown must suppress rapid repeats"
        );
        assert!(
            super::relay_maybe_request_headers_catchup(&mut state, peer_id, 119).is_some(),
            "request should re-open after cooldown interval"
        );

        // Peer far ahead => aggressive interval allows one-second cadence.
        state.peer_reported_tip_heights.insert(peer_id, 10);
        let aggressive = super::relay_maybe_request_headers_catchup(&mut state, peer_id, 120)
            .expect("aggressive catchup should request immediately");
        assert!(matches!(
            aggressive,
            WireMessage::GetHeaders {
                locator: _,
                stop: None
            }
        ));
        assert!(
            super::relay_maybe_request_headers_catchup(&mut state, peer_id, 121).is_some(),
            "aggressive lag mode should allow one-second catchup cadence"
        );
    }

    #[test]
    fn relay_blocks_catchup_requests_only_when_peer_is_ahead() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        let relay = RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool"),
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)
                .expect("orphan"),
            gossip: GossipEngine::new(64).expect("gossip"),
        };
        let mut state = RelayServerState::new(runtime, relay);
        let peer_id = 33u64;

        state.peer_reported_tip_heights.insert(peer_id, 0);
        assert!(
            super::relay_maybe_request_blocks_catchup(&mut state, peer_id, 100).is_none(),
            "equal tip height must not trigger periodic getblocks"
        );

        state.peer_reported_tip_heights.insert(peer_id, 2);
        let first = super::relay_maybe_request_blocks_catchup(&mut state, peer_id, 101)
            .expect("lagging node should request blocks");
        assert!(matches!(
            first,
            WireMessage::GetBlocks {
                locator: _,
                stop: None
            }
        ));
        assert_eq!(
            state.peer_last_blocks_request_sec.get(&peer_id).copied(),
            Some(101)
        );
        assert!(
            super::relay_maybe_request_blocks_catchup(&mut state, peer_id, 104).is_none(),
            "normal blocks catchup interval must rate-limit requests"
        );
        assert!(
            super::relay_maybe_request_blocks_catchup(&mut state, peer_id, 105).is_some(),
            "normal interval should allow another request at boundary"
        );

        state.peer_reported_tip_heights.insert(peer_id, 10);
        assert!(
            super::relay_maybe_request_blocks_catchup(&mut state, peer_id, 106).is_none(),
            "aggressive cadence still honors latest request timestamp"
        );
        let aggressive = super::relay_maybe_request_blocks_catchup(&mut state, peer_id, 107)
            .expect("large lag should use aggressive blocks cadence");
        assert!(matches!(
            aggressive,
            WireMessage::GetBlocks {
                locator: _,
                stop: None
            }
        ));
        assert!(
            super::relay_maybe_request_blocks_catchup(&mut state, peer_id, 108).is_none(),
            "aggressive cadence still enforces one-cycle cooldown"
        );
        assert!(
            super::relay_maybe_request_blocks_catchup(&mut state, peer_id, 109).is_some(),
            "aggressive interval should re-open quickly for large lag"
        );
    }

    #[test]
    fn relay_inv_unknown_block_triggers_fast_headers_catchup() {
        let mut state = relay_state_for_tests();
        let peer_id = 9u64;
        state.relay.gossip.connect_peer(peer_id);
        let unknown_block = Hash256([0x91; 32]);

        let first = super::process_relay_wire_message(
            &mut state,
            peer_id,
            WireMessage::Inv {
                items: vec![InventoryItem::Block(unknown_block)],
            },
            1_000,
        )
        .expect("inv handling");

        assert!(
            first
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetHeaders { stop: None, .. })),
            "unknown block inv should trigger immediate headers catchup"
        );
        assert!(
            first
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetBlocks { stop: None, .. })),
            "unknown block inv should trigger immediate blocks catchup"
        );
        assert!(
            first
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetData { items }
                if items == &vec![InventoryItem::Block(unknown_block)])),
            "unknown block inv should still request block body via getdata"
        );
        assert_eq!(
            state.peer_last_headers_request_sec.get(&peer_id).copied(),
            Some(1_000)
        );
        assert_eq!(
            state.peer_reported_tip_heights.get(&peer_id).copied(),
            Some(state.runtime.tip_height().saturating_add(1)),
            "single unknown block inv should mark peer tip at least one block ahead"
        );

        let second_unknown = Hash256([0x92; 32]);
        let second = super::process_relay_wire_message(
            &mut state,
            peer_id,
            WireMessage::Inv {
                items: vec![InventoryItem::Block(second_unknown)],
            },
            1_000,
        )
        .expect("second inv handling");
        assert!(
            !second
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetHeaders { .. })),
            "headers catchup fast-path must not emit duplicate getheaders in the same second"
        );
        assert!(
            !second
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetBlocks { .. })),
            "blocks catchup fast-path must not emit duplicate getblocks in the same second"
        );

        let third_unknown = Hash256([0x93; 32]);
        let third = super::process_relay_wire_message(
            &mut state,
            peer_id,
            WireMessage::Inv {
                items: vec![InventoryItem::Block(third_unknown)],
            },
            1_001,
        )
        .expect("third inv handling");
        assert!(
            third
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetHeaders { .. })),
            "headers catchup fast-path should reopen after one-second inv cooldown"
        );
        assert!(
            third
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetBlocks { .. })),
            "blocks catchup fast-path should reopen after one-second inv cooldown"
        );
    }

    #[test]
    fn relay_inv_unknown_block_batch_updates_peer_tip_by_unknown_count() {
        let mut state = relay_state_for_tests();
        let peer_id = 11u64;
        state.relay.gossip.connect_peer(peer_id);
        let local_tip = state.runtime.tip_height();
        let unknown_a = Hash256([0xA1; 32]);
        let unknown_b = Hash256([0xA2; 32]);
        let unknown_c = Hash256([0xA3; 32]);

        let out = super::process_relay_wire_message(
            &mut state,
            peer_id,
            WireMessage::Inv {
                items: vec![
                    InventoryItem::Block(unknown_a),
                    InventoryItem::Block(unknown_b),
                    InventoryItem::Block(unknown_c),
                ],
            },
            1_111,
        )
        .expect("batched unknown inv handling");
        assert!(
            out.iter()
                .any(|msg| matches!(msg, WireMessage::GetHeaders { .. })),
            "unknown block batch should trigger headers catchup"
        );
        assert!(
            out.iter()
                .any(|msg| matches!(msg, WireMessage::GetBlocks { .. })),
            "unknown block batch should trigger blocks catchup"
        );
        assert_eq!(
            state.peer_reported_tip_heights.get(&peer_id).copied(),
            Some(local_tip.saturating_add(3)),
            "peer tip tracking should scale with unknown block batch size"
        );
    }

    #[test]
    fn relay_inv_known_or_tx_only_inventory_does_not_trigger_headers_catchup() {
        let mut state = relay_state_for_tests();
        let peer_id = 10u64;
        state.relay.gossip.connect_peer(peer_id);
        let known_block = state.runtime.tip_hash();

        let known_block_out = super::process_relay_wire_message(
            &mut state,
            peer_id,
            WireMessage::Inv {
                items: vec![InventoryItem::Block(known_block)],
            },
            2_000,
        )
        .expect("known block inv handling");
        assert!(
            !known_block_out
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetHeaders { .. })),
            "known block inventory must not trigger headers catchup"
        );
        assert!(
            !known_block_out
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetBlocks { .. })),
            "known block inventory must not trigger blocks catchup"
        );

        let txid = Hash256([0xA3; 32]);
        let tx_only_out = super::process_relay_wire_message(
            &mut state,
            peer_id,
            WireMessage::Inv {
                items: vec![InventoryItem::Tx(txid)],
            },
            2_001,
        )
        .expect("tx inv handling");
        assert!(
            !tx_only_out
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetHeaders { .. })),
            "tx-only inventory must not trigger headers catchup"
        );
        assert!(
            !tx_only_out
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetBlocks { .. })),
            "tx-only inventory must not trigger blocks catchup"
        );
    }

