    #[test]
    fn relay_tx_diffusion_delay_applies_only_to_tx_inventory_and_respects_bounds() {
        super::RELAY_TX_DIFFUSION_BASE_MS.store(20, std::sync::atomic::Ordering::Relaxed);
        super::RELAY_TX_DIFFUSION_MAX_MS.store(80, std::sync::atomic::Ordering::Relaxed);

        let txid = scam_core::hash::hash256(b"tx-diffusion");
        let inv = WireMessage::Inv {
            items: vec![InventoryItem::Tx(txid)],
        };
        let delay = super::relay_tx_diffusion_delay_for_message(&inv);
        assert!(
            delay >= Duration::from_millis(20) && delay <= Duration::from_millis(80),
            "unexpected diffusion delay {:?}",
            delay
        );

        let ping = WireMessage::Ping { nonce: 7 };
        let ping_delay = super::relay_tx_diffusion_delay_for_message(&ping);
        assert_eq!(ping_delay, Duration::from_millis(0));

        super::RELAY_TX_DIFFUSION_BASE_MS.store(0, std::sync::atomic::Ordering::Relaxed);
        super::RELAY_TX_DIFFUSION_MAX_MS.store(0, std::sync::atomic::Ordering::Relaxed);
    }

    #[test]
    fn relay_tx_diffusion_delay_seed_math_is_deterministic_and_bounded() {
        let fixed = super::relay_tx_diffusion_delay_ms_from_seed(20, 80, 0x0102_0304_0506_0708);
        assert_eq!(fixed, 20);
        let same = super::relay_tx_diffusion_delay_ms_from_seed(20, 80, 0x0102_0304_0506_0708);
        assert_eq!(same, fixed);
        let different = super::relay_tx_diffusion_delay_ms_from_seed(20, 80, 0x1112_1314_1516_1718);
        assert!((20..=80).contains(&different));
        assert_ne!(fixed, different);
        assert_eq!(super::relay_tx_diffusion_delay_ms_from_seed(0, 80, 1), 0);
        assert_eq!(super::relay_tx_diffusion_delay_ms_from_seed(20, 0, 1), 0);
        assert_eq!(super::relay_tx_diffusion_delay_ms_from_seed(80, 20, 1), 0);
        assert_eq!(
            super::relay_tx_diffusion_delay_ms_from_seed(42, 42, 0xA5A5_A5A5_A5A5_A5A5),
            42
        );
        assert_eq!(
            super::relay_tx_diffusion_delay_ms_from_seed(20, 800, 0x1112_1314_1516_1718),
            87
        );
        assert_eq!(
            super::relay_tx_diffusion_delay_ms_from_seed(50, 150, 0xFFFF_FFFF_FFFF_FFFF),
            112
        );
        assert_eq!(
            super::relay_tx_diffusion_delay_ms_from_seed(
                10_000_000_000,
                u64::MAX,
                16_806_898_589_309_566_640,
            ),
            10_499_273_757
        );
    }

    #[test]
    fn relay_tx_diffusion_seed_changes_with_txid_and_timestamp() {
        let tx_a = scam_core::hash::hash256(b"tx-a");
        let tx_b = scam_core::hash::hash256(b"tx-b");
        let seed_a = super::relay_tx_diffusion_seed(1_700_000_000_000_000_000, tx_a);
        let seed_b = super::relay_tx_diffusion_seed(1_700_000_000_000_000_000, tx_b);
        let seed_c = super::relay_tx_diffusion_seed(1_700_000_000_000_000_001, tx_a);
        assert_ne!(seed_a, seed_b);
        assert_ne!(seed_a, seed_c);
        assert_eq!(
            seed_a,
            super::relay_tx_diffusion_seed(1_700_000_000_000_000_000, tx_a)
        );
    }

