    #[test]
    fn protocol_violation_response_maps_state_errors_to_sv2_errors() {
        let reason = scam_stratum::StratumError::ProtocolState("bad state".to_owned());

        let setup = super::protocol_violation_response(
            &Sv2Message::SetupConnection {
                protocol: 2,
                min_version: 2,
                max_version: 2,
                flags: 0,
                user_agent: "ua".to_owned(),
            },
            &reason,
        )
        .expect("setup error");
        assert!(matches!(
            setup,
            Sv2Message::SetupConnectionError { code, .. } if code == "protocol_state"
        ));

        let open = super::protocol_violation_response(
            &Sv2Message::OpenStandardMiningChannel {
                request_id: 9,
                user: "worker".to_owned(),
            },
            &reason,
        )
        .expect("open error");
        assert!(matches!(
            open,
            Sv2Message::OpenStandardMiningChannelError {
                request_id: 9,
                code,
                ..
            } if code == "protocol_state"
        ));

        let open_extended = super::protocol_violation_response(
            &Sv2Message::OpenExtendedMiningChannel {
                request_id: 10,
                user: "worker".to_owned(),
                extranonce_size: 8,
            },
            &reason,
        )
        .expect("open extended error");
        assert!(matches!(
            open_extended,
            Sv2Message::OpenExtendedMiningChannelError {
                request_id: 10,
                code,
                ..
            } if code == "protocol_state"
        ));

        let submit = super::protocol_violation_response(
            &Sv2Message::SubmitSharesStandard {
                channel_id: 11,
                job_id: 33,
                nonce: 1,
                ntime: 2,
            },
            &reason,
        )
        .expect("submit error");
        assert!(matches!(
            submit,
            Sv2Message::SubmitSharesError {
                channel_id: 11,
                code,
                ..
            } if code == "protocol_state"
        ));

        let submit_extended = super::protocol_violation_response(
            &Sv2Message::SubmitSharesExtended {
                channel_id: 12,
                job_id: 44,
                nonce: 1,
                ntime: 2,
                version: 1,
                extranonce_hex: "00".to_owned(),
            },
            &reason,
        )
        .expect("submit extended error");
        assert!(matches!(
            submit_extended,
            Sv2Message::SubmitSharesError {
                channel_id: 12,
                code,
                ..
            } if code == "protocol_state"
        ));
    }

    #[test]
    fn read_http_request_rejects_invalid_content_length_header() {
        let raw = b"POST /wallet/new HTTP/1.1\r\nHost: localhost\r\nContent-Length: nope\r\n\r\n";
        let result = read_http_request_from_raw(raw);
        if let Err(err) = &result
            && err.to_string().contains("permission denied")
        {
            return;
        }
        let err = result.expect_err("must reject invalid content-length");
        assert!(err.to_string().contains("invalid Content-Length"));
    }

    #[test]
    fn read_http_request_rejects_missing_header_terminator() {
        let raw = b"GET /health HTTP/1.1\r\nHost: localhost\r\n";
        let result = read_http_request_from_raw(raw);
        if let Err(err) = &result
            && err.to_string().contains("permission denied")
        {
            return;
        }
        let err = result.expect_err("must reject malformed headers");
        assert!(err.to_string().contains("missing header terminator"));
    }

