    #[test]
    fn relay_connect_target_async_uses_distinct_error_paths_for_clearnet_and_cjdns() {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("tokio runtime");
        rt.block_on(async {
            let policy = super::RelayNetworkPolicy {
                allow_onion: false,
                allow_i2p: false,
                allow_cjdns: true,
                socks5_proxy: Some("127.0.0.1:19050".to_owned()),
            };

            let clearnet_err = super::relay_connect_target_async("127.0.0.1:9", &policy)
                .await
                .expect_err("clearnet dial should fail without listener");
            assert!(
                clearnet_err
                    .to_string()
                    .contains("outbound relay connect to 127.0.0.1:9 failed"),
                "unexpected clearnet error path: {clearnet_err}"
            );

            let cjdns_err = super::relay_connect_target_async("[fc00::1]:9", &policy)
                .await
                .expect_err("cjdns dial should fail without listener");
            assert!(
                cjdns_err
                    .to_string()
                    .contains("outbound cjdns connect to [fc00::1]:9 failed"),
                "unexpected cjdns error path: {cjdns_err}"
            );
        });
    }

    #[test]
    fn relay_connect_via_socks5_async_accepts_255_byte_host_before_connect_attempt() {
        let endpoint = super::RelayTargetEndpoint {
            host: "z".repeat(255),
            port: 9735,
        };
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("tokio runtime");
        rt.block_on(async {
            let err = super::relay_connect_via_socks5_async("127.0.0.1:9", &endpoint)
                .await
                .expect_err("missing proxy listener should fail connect");
            let text = err.to_string();
            assert!(
                text.contains("SOCKS5 connect"),
                "expected connect path error, got: {text}"
            );
            assert!(
                !text.contains("invalid SOCKS5 host length"),
                "255-byte host should pass length guard"
            );
        });
    }

