    #[test]
    fn relay_proactive_inventory_messages_announces_tip_and_new_mempool_txids_once() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");

        let mut relay = RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool"),
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)
                .expect("orphan"),
            gossip: GossipEngine::new(128).expect("gossip"),
        };
        let tx = Transaction {
            version: 1,
            inputs: vec![TxIn {
                prev_out: OutPoint {
                    txid: Hash256([7u8; 32]),
                    vout: 0,
                },
                signature: vec![1u8; 64],
                pubkey_compressed: vec![2u8; 33],
                sequence: 0,
            }],
            outputs: vec![TxOut {
                value: 10,
                key_hash20: [9u8; 20],
            }],
            lock_time: 0,
        };
        relay
            .mempool
            .insert_with_fee(tx.clone(), 2_000)
            .expect("insert tx");

        let state = RelayServerState::new(runtime, relay);
        let mut last_tip_announced = None;
        let mut announced_txids = std::collections::HashSet::<Hash256>::new();
        let first = super::relay_proactive_inventory_messages(
            &state,
            &mut last_tip_announced,
            &mut announced_txids,
            128,
        );
        assert!(
            first.iter().any(|msg| match msg {
                WireMessage::Inv { items } => items.iter().any(|item| {
                    matches!(item, InventoryItem::Block(hash) if *hash == state.runtime.tip_hash())
                }),
                _ => false,
            }),
            "first proactive pass must announce tip hash"
        );
        assert!(
            first.iter().any(|msg| match msg {
                WireMessage::Inv { items } => items
                    .iter()
                    .any(|item| matches!(item, InventoryItem::Tx(txid) if *txid == tx.txid())),
                _ => false,
            }),
            "first proactive pass must announce unseen mempool txid"
        );

        let second = super::relay_proactive_inventory_messages(
            &state,
            &mut last_tip_announced,
            &mut announced_txids,
            128,
        );
        assert!(
            second.is_empty(),
            "second proactive pass must not re-announce unchanged inventory"
        );
    }

    #[test]
    fn relay_proactive_inventory_messages_include_headers_when_tip_advances() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let reward_key = cfg.genesis_reward_key_hash20().expect("reward key");
        let mut runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        super::mine_blocks_on_runtime(
            &mut runtime,
            &super::MiningLoopParams {
                count: 2,
                interval_sec: cfg.target_block_time_sec,
                max_nonce: 500_000,
                subsidy: cfg.block_subsidy,
                miner_key_hash: reward_key,
                label_prefix: "relay-proactive-headers",
                print_each: false,
            },
        )
        .expect("mine");
        let previous_tip = runtime
            .block_hash_at_height(runtime.tip_height().saturating_sub(1))
            .expect("previous tip");

        let relay = RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool"),
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)
                .expect("orphan"),
            gossip: GossipEngine::new(128).expect("gossip"),
        };
        let state = RelayServerState::new(runtime, relay);
        let mut announced_txids = std::collections::HashSet::<Hash256>::new();
        let mut last_tip_announced = Some(previous_tip);
        let messages = super::relay_proactive_inventory_messages(
            &state,
            &mut last_tip_announced,
            &mut announced_txids,
            128,
        );
        let headers = messages
            .iter()
            .find_map(|message| match message {
                WireMessage::Headers { headers } => Some(headers),
                _ => None,
            })
            .expect("headers announcement");
        let announced_tip = headers.last().expect("headers non-empty").block_hash();
        assert_eq!(announced_tip, state.runtime.tip_hash());
    }

    #[test]
    fn relay_getaddr_and_addr_messages_exchange_known_peers() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        let relay = RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool"),
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)
                .expect("orphan"),
            gossip: GossipEngine::new(64).expect("gossip"),
        };
        let mut state = RelayServerState::new(runtime, relay);
        state.known_peer_addresses = vec![super::PeerAddress {
            address: "127.0.0.1:18444".to_owned(),
            services: 1,
            last_seen_unix_sec: 10,
        }];

        let response =
            process_relay_wire_message(&mut state, 1, WireMessage::GetAddr, 100).expect("getaddr");
        assert!(
            response.iter().any(|message| matches!(
                message,
                WireMessage::Addr { peers } if peers.iter().any(|entry| entry.address == "127.0.0.1:18444")
            )),
            "getaddr response must contain known peer records"
        );

        process_relay_wire_message(
            &mut state,
            1,
            WireMessage::Addr {
                peers: vec![super::PeerAddress {
                    address: "127.0.0.1:19444".to_owned(),
                    services: 1,
                    last_seen_unix_sec: 20,
                }],
            },
            101,
        )
        .expect("addr merge");
        assert!(
            state
                .known_peer_addresses
                .iter()
                .any(|entry| entry.address == "127.0.0.1:19444")
        );
    }

