    #[test]
    fn relay_block_unknown_parent_requests_recovery_and_promotes_orphan_when_parent_arrives() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        cfg.validate().expect("config validate");
        let miner_key_hash = cfg.genesis_reward_key_hash20().expect("reward key");

        let mut producer = ChainRuntime::from_config(cfg.clone()).expect("producer runtime");
        let mine_params = super::MiningLoopParams {
            count: 2,
            interval_sec: cfg.target_block_time_sec,
            max_nonce: 500_000,
            subsidy: cfg.block_subsidy,
            miner_key_hash,
            label_prefix: "relay-orphan-recovery",
            print_each: false,
        };
        mine_blocks_on_runtime(&mut producer, &mine_params).expect("mine producer chain");
        let chain = producer.block_hashes().to_vec();
        let parent_hash = chain[1];
        let child_hash = chain[2];
        let parent_block = producer
            .block_by_hash(&parent_hash)
            .expect("parent block")
            .clone();
        let child_block = producer
            .block_by_hash(&child_hash)
            .expect("child block")
            .clone();

        let runtime = ChainRuntime::from_config(cfg.clone()).expect("consumer runtime");
        let mut gossip = GossipEngine::with_limits_and_replacement(
            64,
            50,
            ReplacementRateLimit {
                window_sec: 60,
                max_replacements: 5,
                penalty: 10,
            },
        )
        .expect("gossip");
        gossip.connect_peer(42);
        let relay = RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool"),
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)
                .expect("orphan"),
            gossip,
        };
        let mut state = RelayServerState::new(runtime, relay);

        let recover = process_relay_wire_message(
            &mut state,
            42,
            WireMessage::Block { block: child_block },
            1_000,
        )
        .expect("unknown parent should trigger recovery path");
        assert!(
            recover.iter().any(|msg| matches!(
                msg,
                WireMessage::GetData { items }
                    if items.contains(&InventoryItem::Block(parent_hash))
            )),
            "recovery path must request missing parent block"
        );
        assert!(
            recover
                .iter()
                .any(|msg| matches!(msg, WireMessage::GetBlocks { .. })),
            "recovery path must request block locator sync"
        );
        assert_eq!(state.runtime.tip_height(), 0);
        assert_eq!(state.pending_block_orphans.len(), 1);

        let post_parent = process_relay_wire_message(
            &mut state,
            42,
            WireMessage::Block {
                block: parent_block.clone(),
            },
            1_001,
        )
        .expect("parent apply");
        assert!(post_parent.is_empty());
        assert_eq!(state.runtime.tip_hash(), child_hash);
        assert!(state.pending_block_orphans.is_empty());
    }

    #[test]
    fn relay_should_request_parent_sync_enforces_cooldown_and_prunes_stale_entries() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        let relay = RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool"),
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)
                .expect("orphan"),
            gossip: GossipEngine::new(32).expect("gossip"),
        };
        let mut state = RelayServerState::new(runtime, relay);
        let parent = Hash256([0xAA; 32]);
        let stale_parent = Hash256([0x55; 32]);
        state.last_parent_sync_request_sec.insert(stale_parent, 1);

        assert!(
            super::relay_should_request_parent_sync(&mut state, parent, 100),
            "first request should be allowed"
        );
        assert!(
            !super::relay_should_request_parent_sync(&mut state, parent, 101),
            "cooldown should block immediate retry"
        );
        assert!(
            super::relay_should_request_parent_sync(&mut state, parent, 102),
            "cooldown boundary should permit retry"
        );
        let mid_parent = Hash256([0x77; 32]);
        state.last_parent_sync_request_sec.insert(mid_parent, 50);
        assert!(
            super::relay_should_request_parent_sync(&mut state, Hash256([0x78; 32]), 100),
            "unrelated parent request should still be allowed"
        );
        assert!(
            state.last_parent_sync_request_sec.contains_key(&mid_parent),
            "entries newer than 30*cooldown must be retained"
        );
        assert!(
            !state
                .last_parent_sync_request_sec
                .contains_key(&stale_parent),
            "stale parent sync records should be pruned"
        );
    }

    #[test]
    fn relay_parent_request_cache_cleanup_expires_entries_at_ttl_boundary() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        let relay = RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool"),
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)
                .expect("orphan"),
            gossip: GossipEngine::new(16).expect("gossip"),
        };
        let mut state = RelayServerState::new(runtime, relay);
        let keep = Hash256([1u8; 32]);
        let drop = Hash256([2u8; 32]);
        state.pending_parent_tx_requests.insert(keep, 100);
        state
            .pending_parent_tx_requests
            .insert(drop, 100 - super::RELAY_PARENT_REQUEST_TTL_SEC);

        super::relay_parent_request_cache_cleanup(&mut state, 100);
        assert!(
            state.pending_parent_tx_requests.contains_key(&keep),
            "fresh entry should remain"
        );
        assert!(
            !state.pending_parent_tx_requests.contains_key(&drop),
            "entry exactly at TTL boundary must expire"
        );
    }

    #[test]
    fn relay_parent_getdata_accepts_exact_request_limit_and_rejects_overflow() {
        let cfg: ChainConfig =
            toml::from_str(include_str!("../../../config/devnet.toml")).expect("config parse");
        let runtime = ChainRuntime::from_config(cfg.clone()).expect("runtime");
        let relay = RelayAdmissionState {
            mempool: Mempool::with_policy(cfg.max_mempool_txs as usize, cfg.min_relay_fee_per_kb)
                .expect("mempool"),
            orphan_pool: OrphanPool::new(cfg.max_orphan_txs as usize, cfg.orphan_ttl_sec)
                .expect("orphan"),
            gossip: GossipEngine::new(16).expect("gossip"),
        };
        let mut state = RelayServerState::new(runtime, relay);

        let missing = (0..super::RELAY_MAX_ORPHAN_PARENT_REQUESTS)
            .map(|idx| OutPoint {
                txid: scam_core::hash::hash256(&idx.to_le_bytes()),
                vout: 0,
            })
            .collect::<Vec<_>>();
        let items = super::relay_parent_getdata_for_missing_outpoints(&mut state, &missing, 1_000)
            .expect("exact parent request limit should pass");
        assert_eq!(items.len(), super::RELAY_MAX_ORPHAN_PARENT_REQUESTS);

        let mut overflow = missing.clone();
        overflow.push(OutPoint {
            txid: scam_core::hash::hash256(b"overflow"),
            vout: 0,
        });
        let err = super::relay_parent_getdata_for_missing_outpoints(&mut state, &overflow, 1_001)
            .expect_err("overflow parent request set must fail");
        assert!(err.to_string().contains("too many unknown parents"));
    }

